    /**
     * The old public registration API accepts a Satellite subclass outside the
     * built-in nine-class list. Its numeric position, item lookup and SavedData
     * NBT round-trip must remain class-driven rather than requiring a modern
     * LegacySatelliteType enum entry.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void satelliteRegistryKeepsLegacyCustomSubclassContract(GameTestHelper helper) {
        List<Class<? extends com.hbm.saveddata.satellites.Satellite>> savedClasses =
                new ArrayList<>(com.hbm.saveddata.satellites.Satellite.satellites);
        Map<Item, Class<? extends com.hbm.saveddata.satellites.Satellite>> savedItems =
                new HashMap<>(com.hbm.saveddata.satellites.Satellite.itemToClass);
        try {
            int customId = com.hbm.saveddata.satellites.Satellite.satellites.size();
            com.hbm.saveddata.satellites.Satellite.registerSatellite(RegisteredSatelliteExtension.class, Items.STICK);
            com.hbm.saveddata.satellites.Satellite.registerSatellite(RegisteredSatelliteExtension.class, Items.BLAZE_ROD);

            assertEquals(customId, com.hbm.saveddata.satellites.Satellite.getIDFromItem(Items.STICK),
                    "legacy custom satellite keeps its appended registration ID");
            assertEquals(-1, com.hbm.saveddata.satellites.Satellite.getIDFromItem(Items.BLAZE_ROD),
                    "legacy duplicate class registration does not replace its first item");
            com.hbm.saveddata.satellites.Satellite created =
                    com.hbm.saveddata.satellites.Satellite.create(customId);
            assertTrue(created instanceof RegisteredSatelliteExtension,
                    "legacy custom satellite ID creates its registered subclass");
            assertTrue(created.type() == null,
                    "legacy custom satellite is not forced into a built-in modern type");

            RegisteredSatelliteExtension source = (RegisteredSatelliteExtension) created;
            source.value = 37;
            com.hbm.saveddata.SatelliteSavedData data = new com.hbm.saveddata.SatelliteSavedData("satellite_extension_test");
            data.sats.put(91_301, source);
            com.hbm.saveddata.SatelliteSavedData reloaded =
                    com.hbm.saveddata.SatelliteSavedData.load(data.save(new CompoundTag()));
            assertTrue(reloaded.getSatFromFreq(91_301) instanceof RegisteredSatelliteExtension,
                    "legacy SavedData restores the registered custom satellite subclass");
            assertEquals(37, ((RegisteredSatelliteExtension) reloaded.getSatFromFreq(91_301)).value,
                    "legacy SavedData retains the custom subclass NBT payload");

            // SatPanelPacket creates the satellite even when its NBT read
            // returns null, but the old handler skips readFromNBT in that
            // case.  Keep the packet/cache carrier distinct from an empty
            // compound so extension load hooks do not run without source NBT.
            ClientPanelData.clearAll();
            ClientPanelData.update(HbmNetworkActions.SATELLITE_PANEL, customId, null);
            ClientSatelliteData.SatelliteSnapshot nullPayloadSnapshot = ClientSatelliteData.current().orElseThrow(() ->
                    new AssertionError("null-NBT panel packet still creates its legacy satellite"));
            assertTrue(nullPayloadSnapshot.satellite() instanceof RegisteredSatelliteExtension,
                    "null-NBT panel packet creates the registered legacy extension");
            assertFalse(ClientPanelData.get(HbmNetworkActions.SATELLITE_PANEL).orElseThrow().hasNbt(),
                    "panel cache preserves the legacy null-NBT carrier instead of normalizing it to an empty tag");
            assertEquals(0, ((RegisteredSatelliteExtension) nullPayloadSnapshot.satellite()).loadCalls,
                    "null-NBT panel packet skips the legacy extension load hook");
        } finally {
            ClientPanelData.clearAll();
            com.hbm.saveddata.satellites.Satellite.satellites.clear();
            com.hbm.saveddata.satellites.Satellite.satellites.addAll(savedClasses);
            com.hbm.saveddata.satellites.Satellite.itemToClass.clear();
            com.hbm.saveddata.satellites.Satellite.itemToClass.putAll(savedItems);
        }
        helper.succeed();
    }

    /**
     * SatPanelPacket creates and assigns the satellite inside a broad legacy
     * catch block. An invalid id consequently leaves its old client global
     * null; it must not turn the first later GUI/cache read into an Optional
     * mapper exception.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void satellitePanelCacheKeepsLegacyUnknownIdNullBoundary(GameTestHelper helper) {
        ClientPanelData.clearAll();
        try {
            CompoundTag mapperData = new CompoundTag();
            mapperData.putInt("frequency", 83_091);
            ClientPanelData.update(HbmNetworkActions.SATELLITE_PANEL, LegacySatelliteType.MAPPER.legacyId(), mapperData);
            ClientSatelliteData.SatelliteSnapshot mapper = ClientSatelliteData.current().orElseThrow(() ->
                    new AssertionError("source-known panel id creates a client satellite snapshot"));
            assertTrue(mapper.satellite() instanceof com.hbm.saveddata.satellites.SatelliteMapper,
                    "panel cache creates the source mapper facade before reading its NBT");
            assertEquals(83_091, mapper.frequency(), "panel cache keeps its packet frequency carrier");

            ClientPanelData.update(HbmNetworkActions.SATELLITE_PANEL, 99_999, new CompoundTag());
            assertTrue(ClientSatelliteData.current().isEmpty(),
                    "unknown legacy panel id clears the satellite snapshot instead of throwing from Optional.map");
        } finally {
            ClientPanelData.clearAll();
        }
        helper.succeed();
    }

