    /**
     * ISatChip only tested the legacy stack reference and item class.  A
     * count-zero chip was therefore still an ISatChip carrier: reading creates
     * its empty tag and writing its exact integer frequency.  Non-chip stacks
     * and null stay no-op through the static legacy facade.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void satelliteChipFrequencyKeepsLegacyNbtAndZeroCountBoundaries(GameTestHelper helper) {
        ItemStack taglessChip = new ItemStack(ModItems.SAT_CHIP.get());
        assertFalse(taglessChip.hasTag(), "fresh satellite chip starts without a tag");
        assertEquals(0, com.hbm.items.ISatChip.getFreqS(taglessChip),
                "legacy static chip read returns zero when freq is absent");
        assertTrue(taglessChip.getTag() != null,
                "legacy static chip read materializes the empty NBT compound");
        assertFalse(taglessChip.getTag().contains(ISatelliteChip.TAG_FREQUENCY),
                "legacy static chip read does not invent an absent freq key");

        com.hbm.items.ISatChip.setFreqS(taglessChip, -91_307);
        assertEquals(-91_307, com.hbm.items.ISatChip.getFreqS(taglessChip),
                "legacy facade writes and reads the exact signed frequency integer");

        ItemStack zeroCountChip = new ItemStack(ModItems.SAT_CHIP.get());
        zeroCountChip.setCount(0);
        assertTrue(zeroCountChip.isEmpty(), "fixture is a modern count-zero ItemStack");
        assertEquals(0, ISatelliteChip.getFrequencyFromStack(zeroCountChip),
                "legacy item-class dispatch still reads a count-zero satellite chip");
        assertTrue(zeroCountChip.getTag() != null,
                "legacy count-zero satellite chip read still materializes its empty NBT compound");
        ISatelliteChip.setFrequencyOnStack(zeroCountChip, 27);
        assertEquals(27, zeroCountChip.getTag().getInt(ISatelliteChip.TAG_FREQUENCY),
                "legacy item-class dispatch writes a count-zero satellite chip");

        ItemStack nonChip = new ItemStack(Items.STICK);
        assertEquals(0, com.hbm.items.ISatChip.getFreqS(nonChip),
                "legacy static read returns zero for a non-chip item");
        com.hbm.items.ISatChip.setFreqS(nonChip, 33);
        assertFalse(nonChip.hasTag(), "legacy static write leaves a non-chip item untouched");
        assertEquals(0, com.hbm.items.ISatChip.getFreqS(null),
                "legacy static read returns zero for a null stack");
        com.hbm.items.ISatChip.setFreqS(null, 44);
        helper.succeed();
    }

    /**
     * MachineSatLink is a separate ground station, not the inventory-based
     * machine_satlinker.  Keep its direct footprint, satellite/ROR path,
     * sky gate, chip interaction, and NBT contract source-backed.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void satelliteGroundStationKeepsLegacyLinkContract(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos corePos = helper.absolutePos(new BlockPos(6, 2, 6));
        // The GameTest rig can retain a structural block above its local empty
        // template.  MachineSatLink deliberately uses the world height map,
        // so give the unobstructed half of this source-contract test a real
        // clear sky column before installing the station.
        clearBox(level, corePos.above(), new BlockPos(corePos.getX(), level.getMaxBuildHeight() - 1, corePos.getZ()));
        BlockState state = ModBlocks.MACHINE_SATLINK.get().defaultBlockState()
                .setValue(HorizontalMachineBlock.FACING, Direction.NORTH);
        level.setBlock(corePos, state, Block.UPDATE_ALL);
        var block = (com.hbm.ntm.block.SatelliteLinkBlock) ModBlocks.MACHINE_SATLINK.get();
        block.completeDirectMultiblockPlacement(level, corePos, state, null, ItemStack.EMPTY);
        if (!(level.getBlockEntity(corePos) instanceof com.hbm.ntm.blockentity.SatelliteLinkBlockEntity link)) {
            throw new AssertionError("satellite ground-station fixture did not create its block entity");
        }

        var layout = block.getMultiblockLayout(state, level, corePos);
        BlockPos behind = com.hbm.ntm.multiblock.LegacyMultiblockLayout.behind(Direction.NORTH);
        BlockPos clockwise = com.hbm.ntm.multiblock.LegacyMultiblockLayout.clockwise(Direction.NORTH);
        for (BlockPos offset : List.of(behind, clockwise, behind.offset(clockwise))) {
            assertTrue(layout.isLegacyExtraOffset(offset),
                    "satlink retains its source extra Combo proxy offset " + offset);
            assertTrue(layout.proxyMode(offset).equals(com.hbm.ntm.multiblock.LegacyProxyMode.fullCombo()),
                    "satlink extra offset retains full TileEntityProxyCombo capabilities " + offset);
            assertSame(link, MultiblockHelper.resolveCoreBlockEntity(level, corePos.offset(offset)),
                    "satlink Combo proxy resolves to the ground-station core " + offset);
        }

        int frequency = 87_341;
        com.hbm.ntm.satellite.SatelliteSavedData data = com.hbm.ntm.satellite.SatelliteSavedData.get(level);
        data.removeSatellite(frequency);
        assertTrue(data.putSatellite(frequency, com.hbm.ntm.satellite.LegacySatelliteType.PRECISION_LASER),
                "satlink test installs a source SatelliteBase-compatible satellite");
        link.setFrequency(frequency);
        com.hbm.ntm.blockentity.SatelliteLinkBlockEntity.serverTick(level, corePos, state, link);
        assertTrue(link.isConnected(), "unobstructed satlink connects to its assigned occupied frequency");
        assertEquals("", link.provideRORValue("VAL:rx"), "new SatelliteBase starts with an empty ROR receive value");
        link.runRORFunction("FUN:tx", new String[] {"settarget 12 34"});
        link.runRORFunction("FUN:tx", new String[] {"gettarget"});
        assertEquals("12;34", link.provideRORValue("VAL:rx"),
                "satlink tx splits legacy commands and exposes SatelliteBase replies through rx");
        link.runRORFunction("FUN:setfreq", new String[] {"99999.6"});
        assertEquals(100_000, link.getFrequency(), "satlink ROR setfreq retains legacy decimal rounding within 0..100000");

        ItemStack chip = new ItemStack(ModItems.SAT_CHIP.get());
        ISatelliteChip.setFrequencyOnStack(chip, frequency);
        var player = gameTestPlayer(level);
        player.setShiftKeyDown(false);
        player.setItemInHand(InteractionHand.MAIN_HAND, chip);
        assertSame(InteractionResult.SUCCESS, block.use(state, level, corePos, player, InteractionHand.MAIN_HAND,
                blockHit(corePos)), "satlink accepts a satellite chip through its normal right-click path");
        assertEquals(frequency, link.getFrequency(), "satlink copies its held satellite-chip frequency");

        level.setBlock(corePos.above(2), Blocks.STONE.defaultBlockState(), Block.UPDATE_ALL);
        com.hbm.ntm.blockentity.SatelliteLinkBlockEntity.serverTick(level, corePos, state, link);
        assertFalse(link.isConnected(), "satlink disconnects when the source height-map sky path is blocked");

        CompoundTag saved = link.saveWithoutMetadata();
        assertTrue(saved.contains("freq", Tag.TAG_INT) && !saved.contains("power", Tag.TAG_INT),
                "satlink saves its frequency with the source NBT key");
        var restored = new com.hbm.ntm.blockentity.SatelliteLinkBlockEntity(corePos, state);
        restored.load(saved);
        assertEquals(frequency, restored.getFrequency(), "satlink restores its saved frequency after reload");
        data.removeSatellite(frequency);
        helper.succeed();
    }

    /**
     * {@code CommandSatellites} is a player command, not merely a SavedData
     * helper: its legacy-name path must consume the held satellite, list the
     * public map by concrete class name, and return the descended frequency.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void legacySatelliteCommandKeepsOrbitListAndDescendContracts(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        var player = gameTestPlayer(level);
        player.getInventory().clearContent();
        BlockPos origin = helper.absolutePos(new BlockPos(2, 2, 2));
        player.setPos(Vec3.atCenterOf(origin));

        int frequency = 91_217;
        com.hbm.ntm.satellite.SatelliteSavedData data = com.hbm.ntm.satellite.SatelliteSavedData.get(level);
        data.sats.remove(frequency);
        data.setDirty(false);

        ItemStack mapper = SatelliteItem.stack(ModItems.SATELLITE.get(), SatelliteItem.Variant.SPY);
        ISatelliteChip.setFrequencyOnStack(mapper, frequency);
        player.setItemInHand(InteractionHand.MAIN_HAND, mapper);

        CapturingCommandSource capture = new CapturingCommandSource();
        CommandSourceStack source = player.createCommandSourceStack()
                .withSource(capture)
                .withPermission(4);
        int orbitResult = level.getServer().getCommands().performPrefixedCommand(source, "ntmsatellites orbit");
        assertEquals(1, orbitResult, "legacy satellite orbit command returns success");
        assertTrue(player.getMainHandItem().isEmpty(), "legacy satellite orbit consumes exactly the held satellite");
        assertTrue(data.sats.containsKey(frequency), "legacy satellite orbit writes the selected frequency");
        assertTrue(data.isDirty(), "legacy satellite orbit marks SavedData dirty");

        int listResult = level.getServer().getCommands().performPrefixedCommand(source, "ntmsatellites list");
        assertTrue(listResult >= 1, "legacy satellite list returns the current public-map size");
        assertTrue(String.join("\n", capture.messages()).contains(frequency + " - SatelliteMapper"),
                "legacy satellite list uses the concrete legacy class simple name");

        data.setDirty(false);
        int descendResult = level.getServer().getCommands().performPrefixedCommand(source,
                "ntmsatellites descend " + frequency);
        assertEquals(frequency, descendResult, "legacy satellite descend returns the removed frequency");
        assertFalse(data.sats.containsKey(frequency), "legacy satellite descend removes the selected frequency");
        assertTrue(data.isDirty(), "legacy satellite descend marks SavedData dirty");

        ItemStack blankChip = new ItemStack(ModItems.SAT_CHIP.get());
        player.setItemInHand(InteractionHand.MAIN_HAND, blankChip);
        assertEquals(0, level.getServer().getCommands().performPrefixedCommand(source, "ntmsatellites orbit"),
                "legacy satellite command rejects the blank satellite chip");
        assertEquals(1, player.getMainHandItem().getCount(), "rejected blank chip is not consumed");
        helper.succeed();
    }

    /**
     * {@code DecoPoleSatelliteReceiver#onBlockPlacedBy} encoded player yaw as
     * metadata {@code 2/5/3/4}; its TESR rendered those values at
     * {@code 0/90/180/270} degrees.  The static OBJ replacement keeps that
     * visual order through its horizontal blockstate and the source-backed
     * renderer-only BlockEntity.
     */
    // The four source-backed placement probes span x=2..11.  minecraft:empty
    // is a 1x1x1 structure, so its neighbouring GameTest fixtures can occupy
    // the final probe even though the receiver implementation is correct.
    // Reuse the existing 24x8x16 empty fixture to keep every probe inside this
    // test's reserved structure volume.
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "drone_empty", batch = "missileSatellites")
    public static void poleSatelliteReceiverKeepsLegacyYawPlacementOrder(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        var player = gameTestPlayer(level);
        player.getInventory().clearContent();
        assertTrue(ModBlocks.POLE_SATELLITE_RECEIVER.get().asItem()
                        instanceof com.hbm.ntm.item.PoleSatelliteReceiverBlockItem,
                "satellite receiver item keeps the legacy custom-render bridge");

        float[] legacyYaw = {0.0F, 90.0F, 180.0F, 270.0F};
        Direction[] expectedFacing = {Direction.NORTH, Direction.EAST, Direction.SOUTH, Direction.WEST};
        for (int index = 0; index < legacyYaw.length; index++) {
            BlockPos support = helper.absolutePos(new BlockPos(2 + index * 3, 2, 2));
            BlockPos receiver = support.above();
            level.setBlock(support, Blocks.STONE.defaultBlockState(), Block.UPDATE_ALL);
            player.setPos(support.getX() + 0.5D, support.getY() + 1.0D, support.getZ() + 2.5D);
            player.setYRot(legacyYaw[index]);

            ItemStack dish = new ItemStack(ModBlocks.POLE_SATELLITE_RECEIVER.get());
            player.setItemInHand(InteractionHand.MAIN_HAND, dish);
            InteractionResult result = dish.useOn(new UseOnContext(player, InteractionHand.MAIN_HAND, blockHit(support)));
            assertTrue(result.consumesAction(), "satellite receiver places for legacy yaw " + legacyYaw[index]);

            var state = level.getBlockState(receiver);
            assertTrue(state.is(ModBlocks.POLE_SATELLITE_RECEIVER.get()),
                    "satellite receiver block is placed for legacy yaw " + legacyYaw[index]);
            assertEquals(expectedFacing[index], state.getValue(net.minecraft.world.level.block.HorizontalDirectionalBlock.FACING),
                    "legacy receiver yaw " + legacyYaw[index] + " keeps its TESR rotation order");
            assertTrue(level.getBlockEntity(receiver) instanceof com.hbm.ntm.blockentity.PoleSatelliteReceiverBlockEntity,
                    "legacy receiver keeps its renderer TileEntity carrier for yaw " + legacyYaw[index]);
            assertEquals(net.minecraft.world.level.block.RenderShape.ENTITYBLOCK_ANIMATED,
                    state.getRenderShape(), "legacy receiver routes world geometry through its TESR carrier");
        }
        helper.succeed();
    }

    /**
     * {@code SatelliteSavedData} exposes a plain public HashMap in 1.7.10.
     * {@code Satellite.orbit(...)} and {@code CommandSatellites descend} mark
     * the data dirty explicitly after changing it; direct map mutation itself
     * does not acquire a modern persistence side effect.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void satellitePublicMapKeepsLegacyExplicitDirtyBoundary(GameTestHelper helper) {
        com.hbm.saveddata.SatelliteSavedData data = new com.hbm.saveddata.SatelliteSavedData("satellite_test");
        com.hbm.saveddata.satellites.Satellite mapper =
                com.hbm.saveddata.satellites.Satellite.create(LegacySatelliteType.MAPPER.legacyId());
        assertTrue(mapper != null, "legacy mapper fixture is registered");

        data.setDirty(false);
        data.sats.put(91_001, mapper);
        assertFalse(data.isDirty(), "direct legacy sats.put does not mark SavedData dirty");
        data.markDirty();
        assertTrue(data.isDirty(), "legacy callers explicitly mark SavedData after sats.put");

        data.setDirty(false);
        data.sats.remove(91_001);
        assertFalse(data.isDirty(), "direct legacy sats.remove does not mark SavedData dirty");

        data.putSatellite(91_002, mapper);
        assertTrue(data.isDirty(), "modern helper retains its explicit persistence contract");
        data.setDirty(false);
        assertTrue(data.removeSatellite(91_002), "modern helper removes its registered satellite");
        assertTrue(data.isDirty(), "modern remove helper retains its explicit persistence contract");
        helper.succeed();
    }

    /**
     * {@code SatelliteLaser#onClick} writes {@code lastOp} but, unlike the Satellite Dock miner-launch
     * path, does not call {@code SatelliteSavedData.markDirty()} in 1.7.10.  Retain that distinct
     * persistence boundary instead of treating every satellite runtime timestamp as auto-persisted.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void satelliteLaserKeepsLegacyUnmarkedCooldownWrite(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        com.hbm.ntm.satellite.SatelliteSavedData data = com.hbm.ntm.satellite.SatelliteSavedData.get(level);
        data.setDirty(false);

        com.hbm.saveddata.satellites.SatelliteLaser laser = new com.hbm.saveddata.satellites.SatelliteLaser();
        BlockPos target = helper.absolutePos(new BlockPos(2, 2, 2));
        assertTrue(laser.tryClick(level, target.getX(), target.getZ()),
                "legacy laser accepts an elapsed cooldown action");
        assertTrue(laser.lastOp > 0L, "legacy laser writes its lastOp timestamp");
        assertFalse(data.isDirty(), "legacy laser cooldown write does not mark SatelliteSavedData dirty");

        for (com.hbm.ntm.entity.logic.DeathBlastEntity blast
                : level.getEntitiesOfClass(com.hbm.ntm.entity.logic.DeathBlastEntity.class,
                new AABB(target.getX() - 2.0D, level.getMinBuildHeight(), target.getZ() - 2.0D,
                        target.getX() + 3.0D, level.getMaxBuildHeight(), target.getZ() + 3.0D))) {
            assertFalse(blast.fireImmune(),
                    "EntityDeathBlast keeps its legacy default fire-vulnerability state");
            blast.tick();
            assertEquals(0, blast.tickCount,
                    "EntityDeathBlast omits the parent tick, so its legacy age does not advance itself");
            assertEquals(0, blast.legacyRenderAge(),
                    "RenderDeathBlast reads the raw legacy age without adding a partial render tick");
            assertFalse(blast.isRemoved(),
                    "a fresh legacy DeathBlast does not reach its age-gated explosion branch by ticking itself");
            blast.discard();
        }
        helper.succeed();
    }

    /**
     * {@code EntityDeathBlast#onUpdate} has a dormant-in-normal-play age gate because that legacy
     * override omits its parent tick.  If an external lifecycle nevertheless supplies age 60, its
     * exact source payload is a no-radiation MK5 strength-80 blast plus 100 MASKMAN bolts at y + 2.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void deathBlastKeepsLegacyAgeGatedNuclearBoltPayload(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos origin = helper.absolutePos(new BlockPos(5, 3, 5));
        com.hbm.ntm.entity.logic.DeathBlastEntity deathBlast =
                new com.hbm.ntm.entity.logic.DeathBlastEntity(level);
        deathBlast.setPos(origin.getX() + 0.5D, origin.getY(), origin.getZ() + 0.5D);
        deathBlast.tickCount = com.hbm.ntm.entity.logic.DeathBlastEntity.MAX_AGE;
        deathBlast.tick();

        assertTrue(deathBlast.isRemoved(), "age-gated legacy DeathBlast discards itself before spawning payload");
        AABB payloadBounds = new AABB(origin).inflate(1.0D, 3.0D, 1.0D);
        List<com.hbm.ntm.entity.logic.NukeExplosionMk5Entity> explosions = level.getEntitiesOfClass(
                com.hbm.ntm.entity.logic.NukeExplosionMk5Entity.class, payloadBounds);
        assertEquals(1, explosions.size(), "legacy DeathBlast spawns exactly one MK5 payload");
        CompoundTag explosionData = explosions.get(0).saveWithoutId(new CompoundTag());
        assertEquals(80, explosionData.getInt("strength"), "legacy no-radiation radius 40 produces MK5 strength 80");
        assertFalse(explosionData.getBoolean("fallout"), "legacy DeathBlast MK5 payload disables fallout");

        List<BulletProjectileEntity> bolts = level.getEntitiesOfClass(BulletProjectileEntity.class, payloadBounds);
        assertEquals(100, bolts.size(), "legacy DeathBlast spawns all 100 MASKMAN bolts");
        assertLegacyDeathBlastBolt(bolts, 0.2D, -0.01D, 0.0D, "0 degrees");
        assertLegacyDeathBlastBolt(bolts, 0.0D, -0.01D, -0.2D, "90 degrees");
        assertLegacyDeathBlastBolt(bolts, -0.2D, -0.01D, 0.0D, "180 degrees");
        assertLegacyDeathBlastBolt(bolts, 0.0D, -0.01D, 0.2D, "270 degrees");
        for (BulletProjectileEntity bolt : bolts) {
            assertTrue(Math.abs(bolt.getX() - deathBlast.getX()) < 1.0E-12D
                            && Math.abs(bolt.getY() - (deathBlast.getY() + 2.0D)) < 1.0E-12D
                            && Math.abs(bolt.getZ() - deathBlast.getZ()) < 1.0E-12D,
                    "legacy DeathBlast bolt keeps the shared y + 2 spawn position");
            bolt.discard();
        }
        explosions.forEach(com.hbm.ntm.entity.logic.NukeExplosionMk5Entity::discard);
        helper.succeed();
    }

    private static void assertLegacyDeathBlastBolt(List<BulletProjectileEntity> bolts, double x, double y, double z,
            String direction) {
        assertTrue(bolts.stream().map(BulletProjectileEntity::getDeltaMovement).anyMatch(motion ->
                Math.abs(motion.x - x) < 1.0E-12D && Math.abs(motion.y - y) < 1.0E-12D
                        && Math.abs(motion.z - z) < 1.0E-12D),
                "legacy DeathBlast keeps MASKMAN bolt direction " + direction);
    }

    /**
     * Horizons creates EntityTom directly.  EntityTom's 1.7.10 override did
     * not call Entity#onUpdate, leaving ticksExisted at zero and consequently
     * taking its modulo-100 chime branch on every flight tick.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void horizonsTomProjectileKeepsLegacyNoParentTickCadence(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        TomProjectileEntity tom = new TomProjectileEntity(level);
        double startY = level.getMaxBuildHeight() - 8.0D;
        tom.setPos(4.25D, startY, 4.25D);
        tom.setDeltaMovement(0.125D, 0.25D, -0.375D);

        tom.tick();
        assertEquals(0, tom.tickCount, "TOM skips the modern parent tick counter on its first flight tick");
        assertTrue(Math.abs(tom.getX() - 4.375D) < 0.000001D
                        && Math.abs(tom.getY() - (startY + 0.25D)) < 0.000001D
                        && Math.abs(tom.getZ() - 3.875D) < 0.000001D,
                "TOM keeps its legacy manually applied first motion step");
        assertTrue(Math.abs(tom.getDeltaMovement().y + 0.5D) < 0.000001D,
                "TOM writes its legacy downward velocity after movement");

        tom.tick();
        assertEquals(0, tom.tickCount, "TOM continues to skip the parent tick counter on later flight ticks");
        assertTrue(Math.abs(tom.getY() - (startY - 0.25D)) < 0.000001D,
                "TOM applies the prior -0.5 velocity only on its following tick");
        helper.succeed();
    }

    /** Burning FOEQ owns EntityThrowable's old manual update body just like TOM. */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void burningFoeqKeepsLegacyManualFallCadence(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BurningFoeqEntity foeq = new BurningFoeqEntity(level);
        assertEquals(0xF000F0, BurningFoeqEntity.LEGACY_FULL_BRIGHT_LIGHT,
                "Burning FOEQ keeps EntityBurningFOEQ's full-bright lightmap contract");
        double startY = level.getMaxBuildHeight() - 8.0D;
        foeq.setPos(4.25D, startY, 4.25D);
        foeq.setDeltaMovement(0.125D, -0.25D, -0.375D);

        foeq.tick();
        assertEquals(0, foeq.tickCount, "Burning FOEQ skips the modern parent tick counter");
        assertTrue(Math.abs(foeq.getX() - 4.375D) < 0.000001D
                        && Math.abs(foeq.getY() - (startY - 0.25D)) < 0.000001D
                        && Math.abs(foeq.getZ() - 3.875D) < 0.000001D,
                "Burning FOEQ applies its legacy manual motion before gravity");
        assertTrue(Math.abs(foeq.getDeltaMovement().y + 0.35D) < 0.000001D,
                "Burning FOEQ reduces legacy vertical motion by 0.1 after movement");
        assertTrue(foeq.shouldRenderAtSqrDistance(262143.999D)
                        && !foeq.shouldRenderAtSqrDistance(262144.0D),
                "Burning FOEQ uses the global strict 512-block model culling boundary");
        helper.succeed();
    }

