    /**
     * ContainerSatDock's player-side quick move uses the literal [0,15)
     * legacy merge range. Its {@code SlotTakeOnly} outputs reject new
     * placement, but the old Container merge pass first tops up an existing
     * compatible output stack without asking that predicate.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void satelliteDockQuickMoveKeepsLegacyExistingOutputStackBoundary(GameTestHelper helper) {
        var dock = new com.hbm.ntm.blockentity.SatelliteDockBlockEntity(helper.absolutePos(BlockPos.ZERO),
                ModBlocks.SAT_DOCK.get().defaultBlockState());
        var player = gameTestPlayer(helper.getLevel());
        var menu = new com.hbm.ntm.menu.SatelliteDockMenu(0, player.getInventory(), dock);
        int playerMenuSlot = com.hbm.ntm.blockentity.SatelliteDockBlockEntity.SLOT_COUNT;

        dock.getItems().setStackInSlot(0, new ItemStack(Items.DIAMOND, 63));
        player.getInventory().setItem(9, new ItemStack(Items.DIAMOND));
        ItemStack moved = menu.quickMoveStack(player, playerMenuSlot);
        assertEquals(64, dock.getItems().getStackInSlot(0).getCount(),
                "sat dock shift-click tops up an existing take-only output stack through legacy merge");
        assertTrue(player.getInventory().getItem(9).isEmpty(),
                "sat dock shift-click clears the player stack after the existing output accepts it");
        assertSame(Items.DIAMOND, moved.getItem(),
                "sat dock shift-click returns the source copy when legacy existing-stack merge succeeds");
        assertTrue(dock.getItems().getStackInSlot(com.hbm.ntm.blockentity.SatelliteDockBlockEntity.SLOT_CHIP).isEmpty(),
                "sat dock player quick-move never widens the legacy [0,15) range to chip slot 15");

        var emptyDock = new com.hbm.ntm.blockentity.SatelliteDockBlockEntity(helper.absolutePos(new BlockPos(1, 0, 0)),
                ModBlocks.SAT_DOCK.get().defaultBlockState());
        var emptyMenu = new com.hbm.ntm.menu.SatelliteDockMenu(1, player.getInventory(), emptyDock);
        player.getInventory().setItem(9, new ItemStack(Items.EMERALD));
        assertTrue(emptyMenu.quickMoveStack(player, playerMenuSlot).isEmpty(),
                "sat dock shift-click cannot create a new take-only output stack");
        assertSame(Items.EMERALD, player.getInventory().getItem(9).getItem(),
                "sat dock leaves the player stack intact when no existing output can merge");
        assertTrue(emptyDock.getItems().getStackInSlot(0).isEmpty(),
                "sat dock's first empty output remains empty after rejected shift-click placement");
        helper.succeed();
    }

    /**
     * TileEntityMachineSatDock keeps its plain inventory separate from
     * ContainerSatDock: only the menu's manual chip slot is ItemSatChip-only.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void satelliteDockKeepsLegacyGenericInventoryChipSlot(GameTestHelper helper) {
        var dock = new com.hbm.ntm.blockentity.SatelliteDockBlockEntity(helper.absolutePos(BlockPos.ZERO),
                ModBlocks.SAT_DOCK.get().defaultBlockState());
        ItemStack lens = new ItemStack(ModItems.NEUTRINO_LENS.get());

        assertTrue(dock.getItems().isItemValid(com.hbm.ntm.blockentity.SatelliteDockBlockEntity.SLOT_CHIP, lens),
                "sat dock's legacy inventory accepts any item in its chip slot outside the manual menu");
        assertFalse(dock.getItems().isItemValid(0, lens),
                "sat dock's legacy inventory keeps cargo output slots insertion-only false");
        assertTrue(dock.getItems().insertItem(com.hbm.ntm.blockentity.SatelliteDockBlockEntity.SLOT_CHIP,
                lens.copy(), false).isEmpty(),
                "sat dock's generic chip inventory insertion consumes the supplied stack");
        assertSame(lens.getItem(), dock.getItems()
                        .getStackInSlot(com.hbm.ntm.blockentity.SatelliteDockBlockEntity.SLOT_CHIP).getItem(),
                "sat dock keeps the directly inserted non-satellite stack without inventing a chip conversion");

        CompoundTag dockEmptyName = dock.saveWithoutMetadata();
        dockEmptyName.putString("name", "");
        dock.load(dockEmptyName);
        assertTrue(dock.saveWithoutMetadata().contains("name", Tag.TAG_STRING),
                "satellite dock writes a non-null empty legacy custom name");

        ServerLevel level = helper.getLevel();
        com.hbm.ntm.satellite.SatelliteSavedData data = com.hbm.ntm.satellite.SatelliteSavedData.get(level);
        assertTrue(data.putSatellite(0, LegacySatelliteType.MINER),
                "satellite dock fixture registers the legacy frequency-zero miner");
        dock.getItems().setStackInSlot(com.hbm.ntm.blockentity.SatelliteDockBlockEntity.SLOT_CHIP,
                new ItemStack(Items.DIRT));
        com.hbm.ntm.blockentity.SatelliteDockBlockEntity.serverTick(level, dock.getBlockPos(),
                dock.getBlockState(), dock);
        assertEquals(1, level.getEntitiesOfClass(MinerRocketEntity.class,
                        new AABB(dock.getBlockPos().getX(), 299.0D, dock.getBlockPos().getZ(),
                                dock.getBlockPos().getX() + 1.0D, 301.0D, dock.getBlockPos().getZ() + 1.0D)).size(),
                "sat dock keeps TileEntityMachineSatDock's non-empty non-chip frequency-zero launch boundary");
        helper.succeed();
    }

    /**
     * TileEntityMachineSatDock only guarded its mismatched-rocket explosion
     * with a non-null slot 15.  The unloading branch still read getFreqS(null)
     * as frequency zero, so a docked zero-frequency miner remains unloadable
     * after its chip is removed.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void satelliteDockKeepsLegacyEmptyChipFrequencyZeroUnload(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos dockPos = helper.absolutePos(new BlockPos(12, 96, 12));
        level.setBlock(dockPos, ModBlocks.SAT_DOCK.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(dockPos) instanceof com.hbm.ntm.blockentity.SatelliteDockBlockEntity dock)) {
            throw new AssertionError("satellite dock fixture did not create its block entity");
        }

        com.hbm.ntm.satellite.SatelliteSavedData data = com.hbm.ntm.satellite.SatelliteSavedData.get(level);
        assertTrue(data.putSatellite(0, LegacySatelliteType.MINER),
                "satellite dock fixture registers the legacy frequency-zero miner");

        MinerRocketEntity rocket = new MinerRocketEntity(level);
        rocket.setPos(dockPos.getX() + 0.5D, dockPos.getY() + 1.75D, dockPos.getZ() + 0.5D);
        rocket.setSatelliteFrequency(0);
        level.addFreshEntity(rocket);
        for (int i = 0; i < 50; i++) {
            rocket.tick();
        }
        assertEquals(MinerRocketEntity.MODE_UNLOADING, rocket.mode(),
                "frequency-zero miner is still docked while reaching the legacy unload tick");
        assertEquals(50, rocket.timer(), "frequency-zero miner reaches the exact legacy cargo tick");
        assertTrue(dock.getItems().getStackInSlot(com.hbm.ntm.blockentity.SatelliteDockBlockEntity.SLOT_CHIP).isEmpty(),
                "fixture leaves the satellite dock chip slot empty");

        com.hbm.ntm.blockentity.SatelliteDockBlockEntity.serverTick(level, dockPos,
                level.getBlockState(dockPos), dock);

        assertFalse(dock.getItems().getStackInSlot(0).isEmpty(),
                "empty chip slot still unloads the legacy frequency-zero miner cargo");
        helper.succeed();
    }

