    /**
     * TileEntityMachineSatDock#addToInv merges by item and legacy metadata only:
     * incoming NBT is ignored both when stacking and when filling an empty output.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void satelliteDockKeepsLegacyCargoNbtDiscardBoundary(GameTestHelper helper) {
        var dock = new com.hbm.ntm.blockentity.SatelliteDockBlockEntity(helper.absolutePos(BlockPos.ZERO),
                ModBlocks.SAT_DOCK.get().defaultBlockState());
        ItemStack existing = new ItemStack(Items.DIAMOND, 60);
        existing.setHoverName(Component.literal("stored cargo"));
        dock.getItems().setStackInSlot(0, existing);

        ItemStack incoming = new ItemStack(Items.DIAMOND, 3);
        incoming.setHoverName(Component.literal("incoming cargo"));
        invokeSatelliteDockAddToOutput(dock, incoming);

        ItemStack merged = dock.getItems().getStackInSlot(0);
        assertEquals(63, merged.getCount(), "sat dock adds all matching legacy cargo to the existing output stack");
        assertTrue(merged.hasCustomHoverName() && "stored cargo".equals(merged.getHoverName().getString()),
                "sat dock keeps the existing stack's NBT instead of matching incoming cargo NBT");

        ItemStack emptySlotIncoming = new ItemStack(Items.EMERALD, 4);
        emptySlotIncoming.setHoverName(Component.literal("discarded cargo tag"));
        invokeSatelliteDockAddToOutput(dock, emptySlotIncoming);
        ItemStack bareOutput = dock.getItems().getStackInSlot(1);
        assertEquals(1, bareOutput.getCount(), "sat dock creates exactly one legacy bare output item in an empty slot");
        assertFalse(bareOutput.hasCustomHoverName(), "sat dock strips incoming cargo NBT for a new output slot");
        helper.succeed();
    }

    /**
     * TileEntityMachineSatDock ejects through IInventory even when the same
     * target also exposes a modern item-handler capability: exactly one item
     * joins the first matching legacy stack during this tick.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void satelliteDockEjectKeepsLegacyContainerPriorityAndSingleItemRate(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos dockPos = helper.absolutePos(new BlockPos(4, 2, 4));
        level.setBlock(dockPos, ModBlocks.SAT_DOCK.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(dockPos) instanceof com.hbm.ntm.blockentity.SatelliteDockBlockEntity dock)) {
            throw new AssertionError("satellite dock fixture did not create its block entity");
        }
        ChestBlockEntity chest = placeChest(level, dockPos.offset(2, 0, 0));
        assertTrue(chest.getCapability(ForgeCapabilities.ITEM_HANDLER).isPresent(),
                "modern chest exposes the capability fallback in addition to its Container contract");

        ItemStack stored = new ItemStack(Items.DIAMOND, 63);
        stored.setHoverName(Component.literal("legacy target stack"));
        chest.setItem(0, stored);
        ItemStack output = new ItemStack(Items.DIAMOND, 2);
        output.setHoverName(Component.literal("legacy target stack"));
        dock.getItems().setStackInSlot(0, output);

        com.hbm.ntm.blockentity.SatelliteDockBlockEntity.serverTick(level, dockPos,
                level.getBlockState(dockPos), dock);

        assertEquals(64, chest.getItem(0).getCount(),
                "sat dock adds only one output item to the matching adjacent legacy container stack");
        assertEquals(1, dock.getItems().getStackInSlot(0).getCount(),
                "sat dock retains the second output item until a later legacy tick");
        assertTrue("legacy target stack".equals(chest.getItem(0).getHoverName().getString()),
                "sat dock retains adjacent Container stack data when it merges one legacy item");
        helper.succeed();
    }

    /**
     * TileEntityMachineSatDock#ejectInto only recognizes IInventory.  A modern
     * capability-only block entity must therefore not become an extra output
     * destination merely because Forge exposes an item handler for it.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void satelliteDockRejectsCapabilityOnlyOutputTarget(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos dockPos = helper.absolutePos(new BlockPos(8, 2, 8));
        BlockPos batteryPos = dockPos.offset(2, 0, 0);
        level.setBlock(dockPos, ModBlocks.SAT_DOCK.get().defaultBlockState(), Block.UPDATE_ALL);
        level.setBlock(batteryPos, ModBlocks.MACHINE_BATTERY.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(dockPos) instanceof com.hbm.ntm.blockentity.SatelliteDockBlockEntity dock)) {
            throw new AssertionError("satellite dock fixture did not create its block entity");
        }
        BlockEntity target = level.getBlockEntity(batteryPos);
        assertTrue(target != null, "machine battery fixture creates a target block entity");
        assertFalse(target instanceof Container,
                "machine battery is a real capability-only target, not a legacy Container");
        IItemHandler targetItems = target.getCapability(ForgeCapabilities.ITEM_HANDLER).resolve()
                .orElseThrow(() -> new AssertionError("machine battery exposes its item handler capability"));

        dock.getItems().setStackInSlot(0, new ItemStack(Items.DIRT));
        com.hbm.ntm.blockentity.SatelliteDockBlockEntity.serverTick(level, dockPos,
                level.getBlockState(dockPos), dock);

        assertSame(Items.DIRT, dock.getItems().getStackInSlot(0).getItem(),
                "sat dock retains cargo when adjacent target has no legacy Container contract");
        for (int slot = 0; slot < targetItems.getSlots(); slot++) {
            assertTrue(targetItems.getStackInSlot(slot).isEmpty(),
                    "capability-only target inventory stays empty in slot " + slot);
        }
        helper.succeed();
    }

    /**
     * TileEntityMachineSatLinker rejects every inventory insertion path.  Its
     * ordinary legacy Slots inherit that rejection, including player
     * shift-click, even though pre-filled chip stacks are still processed.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void satelliteLinkerKeepsLegacyNoInsertionBoundary(GameTestHelper helper) {
        var linker = new com.hbm.ntm.blockentity.SatelliteLinkerBlockEntity(helper.absolutePos(BlockPos.ZERO),
                ModBlocks.MACHINE_SATLINKER.get().defaultBlockState());
        ItemStack chip = new ItemStack(ModItems.SAT_CHIP.get());
        var player = gameTestPlayer(helper.getLevel());
        var menu = new com.hbm.ntm.menu.SatelliteLinkerMenu(0, player.getInventory(), linker);

        for (int slot = 0; slot < com.hbm.ntm.blockentity.SatelliteLinkerBlockEntity.SLOT_COUNT; slot++) {
            assertFalse(linker.getItems().isItemValid(slot, chip),
                    "satellite linker rejects automation insertion for slot " + slot);
            assertFalse(menu.getSlot(slot).mayPlace(chip),
                    "satellite linker ordinary legacy slot rejects manual insertion for slot " + slot);
            assertSame(chip.getItem(), linker.getItems().insertItem(slot, chip.copy(), false).getItem(),
                    "satellite linker returns the rejected automation stack for slot " + slot);
        }

        player.getInventory().setItem(9, chip.copy());
        assertTrue(menu.quickMoveStack(player, 3).isEmpty(),
                "satellite linker player shift-click cannot bypass the legacy source-slot rejection");
        assertTrue(linker.getItems().getStackInSlot(0).isEmpty(),
                "satellite linker source slot stays empty after rejected player shift-click");

        CompoundTag linkerEmptyName = linker.saveWithoutMetadata();
        linkerEmptyName.putString("name", "");
        linker.load(linkerEmptyName);
        assertTrue(linker.saveWithoutMetadata().contains("name", Tag.TAG_STRING),
                "satellite linker writes a non-null empty legacy custom name");
        helper.succeed();
    }

    /**
     * ContainerMachineSatLinker moves slot zero through its literal legacy
     * {@code [1, end)} range in reverse.  The ordinary slot rejection still
     * prevents new placement, but an existing compatible randomizer stack is
     * merged after all full player slots have been tried.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void satelliteLinkerKeepsLegacySourceQuickMoveRange(GameTestHelper helper) {
        var linker = new com.hbm.ntm.blockentity.SatelliteLinkerBlockEntity(helper.absolutePos(BlockPos.ZERO),
                ModBlocks.MACHINE_SATLINKER.get().defaultBlockState());
        var player = gameTestPlayer(helper.getLevel());
        var menu = new com.hbm.ntm.menu.SatelliteLinkerMenu(0, player.getInventory(), linker);

        for (int slot = 0; slot < player.getInventory().getContainerSize(); slot++) {
            player.getInventory().setItem(slot, new ItemStack(Items.DIAMOND, 64));
        }
        linker.getItems().setStackInSlot(com.hbm.ntm.blockentity.SatelliteLinkerBlockEntity.SLOT_SOURCE,
                new ItemStack(Items.DIAMOND));
        linker.getItems().setStackInSlot(com.hbm.ntm.blockentity.SatelliteLinkerBlockEntity.SLOT_RANDOMIZE,
                new ItemStack(Items.DIAMOND, 63));

        ItemStack quickMoved = menu.quickMoveStack(player,
                com.hbm.ntm.blockentity.SatelliteLinkerBlockEntity.SLOT_SOURCE);
        assertTrue(linker.getItems().getStackInSlot(com.hbm.ntm.blockentity.SatelliteLinkerBlockEntity.SLOT_SOURCE)
                        .isEmpty(),
                "satellite linker source clears after the legacy range accepts its stack");
        assertEquals(64, linker.getItems().getStackInSlot(
                        com.hbm.ntm.blockentity.SatelliteLinkerBlockEntity.SLOT_RANDOMIZE).getCount(),
                "satellite linker source quick move reaches the existing randomizer stack through [1,end)");
        assertSame(Items.DIAMOND, quickMoved.getItem(),
                "satellite linker source quick move returns its legacy source copy; source="
                        + linker.getItems().getStackInSlot(com.hbm.ntm.blockentity.SatelliteLinkerBlockEntity.SLOT_SOURCE)
                        + ", randomizer=" + linker.getItems().getStackInSlot(
                        com.hbm.ntm.blockentity.SatelliteLinkerBlockEntity.SLOT_RANDOMIZE));
        helper.succeed();
    }

    /**
     * TileEntityMachineSatLinker always writes the source frequency to a
     * target chip and writes an available random candidate without first
     * reading that chip.  This preserves the legacy freq-tag materialization
     * boundary for otherwise-default chips.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void satelliteLinkerKeepsLegacyFrequencyWriteBoundary(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos pos = helper.absolutePos(new BlockPos(2, 2, 2));
        var linker = new com.hbm.ntm.blockentity.SatelliteLinkerBlockEntity(pos,
                ModBlocks.MACHINE_SATLINKER.get().defaultBlockState());
        ItemStack source = new ItemStack(ModItems.SAT_CHIP.get());
        ItemStack target = new ItemStack(ModItems.SAT_CHIP.get());
        ItemStack randomizer = new ItemStack(ModItems.SAT_CHIP.get());
        linker.getItems().setStackInSlot(0, source);
        linker.getItems().setStackInSlot(1, target);
        linker.getItems().setStackInSlot(2, randomizer);

        com.hbm.ntm.blockentity.SatelliteLinkerBlockEntity.serverTick(level, pos,
                ModBlocks.MACHINE_SATLINKER.get().defaultBlockState(), linker);

        assertTrue(target.getTag() != null && target.getTag().contains("freq", Tag.TAG_INT),
                "legacy linker writes target freq even when both chips initially read as zero");
        assertTrue(randomizer.getTag() != null && randomizer.getTag().contains("freq", Tag.TAG_INT),
                "legacy linker writes an available random frequency without a prior target read");
        helper.succeed();
    }

    /**
     * MachineSatDock#breakBlock uses the shared legacy machine inventory spill:
     * each slot gets one offset, then splits into 10..30 item entities with
     * copied item NBT instead of using the vanilla one-stack drop path.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void satelliteDockBreakKeepsLegacyRandomInventoryDrops(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos dockPos = helper.absolutePos(new BlockPos(4, 2, 4));
        level.setBlock(dockPos, ModBlocks.SAT_DOCK.get().defaultBlockState(), Block.UPDATE_ALL);
        var dock = (com.hbm.ntm.blockentity.SatelliteDockBlockEntity) level.getBlockEntity(dockPos);
        ItemStack stored = new ItemStack(Items.EMERALD, 64);
        stored.setHoverName(Component.literal("legacy dock cargo"));
        dock.getItems().setStackInSlot(0, stored);

        level.removeBlock(dockPos, false);

        List<ItemEntity> drops = level.getEntitiesOfClass(ItemEntity.class,
                AABB.ofSize(Vec3.atCenterOf(dockPos), 3.0D, 3.0D, 3.0D),
                entity -> entity.getItem().is(Items.EMERALD));
        assertTrue(drops.size() >= 3 && drops.size() <= 7,
                "legacy dock inventory drop splits 64 items into 10..30-sized entities");
        assertEquals(64, drops.stream().mapToInt(entity -> entity.getItem().getCount()).sum(),
                "legacy dock inventory drop preserves the total stack count");
        for (ItemEntity drop : drops) {
            assertTrue(drop.getItem().getCount() <= 30,
                    "legacy dock inventory drop never exceeds the 30-item split ceiling");
            assertTrue(drop.getItem().hasCustomHoverName()
                            && "legacy dock cargo".equals(drop.getItem().getHoverName().getString()),
                    "legacy dock inventory drop copies the source item NBT to every split entity");
        }
        assertTrue(dock.getItems().getStackInSlot(0).isEmpty(),
                "legacy dock inventory is cleared after its contents are spilled");
        helper.succeed();
    }

