        BlockPos tablePos = helper.absolutePos(new BlockPos(8, 7, 5));
        BlockState tableState = ModBlocks.LAUNCH_TABLE.get().defaultBlockState();
        level.setBlock(tablePos, tableState, Block.UPDATE_ALL);
        assertSame(InteractionResult.PASS, tableState.use(level, player, InteractionHand.MAIN_HAND, blockHit(tablePos)),
                "sneaking on launch_table keeps the legacy pass-through interaction");

