    /**
     * The legacy launcher blocks do not share a generic XR footprint contract:
     * LaunchTable replaces its centre cross even when it was occupied, clears
     * eleven blocks in the yaw-selected launch column, and has local zero-height
     * plate dummies. CompactLauncher instead rejects any occupied 3x3 member and
     * keeps only its cardinal plate dummies zero-height. Keep these placement and
     * local-shape details separate from the proxy/capability tests.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileLaunchChain")
    public static void customLauncherPlacementKeepsLegacyClearanceAndPlateShapes(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos tableSupport = helper.absolutePos(new BlockPos(8, 2, 8));
        BlockPos tablePos = tableSupport.above();
        forceLoadedChunks(level, tablePos.offset(-8, -1, -8), tablePos.offset(30, 13, 8));
        clearBox(level, tablePos.offset(-8, 0, -8), tablePos.offset(30, 12, 8));
        level.setBlock(tableSupport, Blocks.STONE.defaultBlockState(), Block.UPDATE_ALL);

        // Player yaw 180 is legacy d=2: it clears -X and puts plate dummies on
        // the Z axis. The legacy pre-flight check deliberately skips the cross.
        level.setBlock(tablePos.east(), Blocks.DIRT.defaultBlockState(), Block.UPDATE_ALL);
        level.setBlock(tablePos.north(), Blocks.DIRT.defaultBlockState(), Block.UPDATE_ALL);
        for (int height = 1; height < 12; height++) {
            level.setBlock(tablePos.west(3).above(height), Blocks.DIRT.defaultBlockState(), Block.UPDATE_ALL);
        }

        var player = gameTestPlayer(level);
        player.setPos(tableSupport.getX() + 0.5D, tableSupport.getY() + 1.0D, tableSupport.getZ() + 7.5D);
        player.setYRot(180.0F);
        player.setXRot(0.0F);
        player.getInventory().clearContent();
        ItemStack tableStack = new ItemStack(ModBlocks.LAUNCH_TABLE.get());
        player.setItemInHand(InteractionHand.MAIN_HAND, tableStack);
        InteractionResult tableResult = tableStack.useOn(new UseOnContext(player, InteractionHand.MAIN_HAND,
                blockHit(tableSupport)));

        assertTrue(tableResult.consumesAction(),
                "launch_table accepts an occupied centre cross exactly as LaunchTable#onBlockPlacedBy does");
        assertTrue(level.getBlockEntity(tablePos) instanceof LaunchTableBlockEntity,
                "launch_table core survives its source-backed destructive cross placement");
        assertTrue(level.getBlockState(tablePos).getValue(HorizontalMachineBlock.FACING) == Direction.SOUTH,
                "player yaw 180 maps launch_table to the modern facing carrying legacy d=2");
        for (int height = 1; height < 12; height++) {
            assertTrue(level.getBlockState(tablePos.west(3).above(height)).isAir(),
                    "launch_table clears legacy d=2 launch-column block " + height);
        }
        assertTrue(level.getBlockEntity(tablePos.north()) instanceof MultiblockDummyBlockEntity,
                "launch_table Z-axis plate is a linked dummy, not a residual centre-cross block");
        assertTrue(MultiblockHelper.findCore(level, tablePos.north()) != null,
                "launch_table Z-axis plate resolves its owning core before local shape lookup");
        assertFalse(level.getBlockState(tablePos.east()).getShape(level, tablePos.east()).isEmpty(),
                "launch_table X-axis port dummy keeps its local full selection shape");
        assertFalse(level.getBlockState(tablePos.east()).getCollisionShape(level, tablePos.east()).isEmpty(),
                "launch_table X-axis port dummy keeps its local full collision shape");
        assertTrue(level.getBlockState(tablePos.north()).getShape(level, tablePos.north()).isEmpty(),
                "launch_table Z-axis plate dummy keeps its legacy zero-height selection shape");
        assertTrue(level.getBlockState(tablePos.north()).getCollisionShape(level, tablePos.north()).isEmpty(),
                "launch_table Z-axis plate dummy keeps its legacy zero-height collision shape");

        BlockPos compactSupport = tableSupport.east(20);
        BlockPos compactPos = compactSupport.above();
        level.setBlock(compactSupport, Blocks.STONE.defaultBlockState(), Block.UPDATE_ALL);
        ItemStack compactStack = new ItemStack(ModBlocks.COMPACT_LAUNCHER.get());
        player.setPos(compactSupport.getX() + 0.5D, compactSupport.getY() + 1.0D, compactSupport.getZ() + 4.5D);
        player.setItemInHand(InteractionHand.MAIN_HAND, compactStack);
        InteractionResult compactResult = compactStack.useOn(new UseOnContext(player, InteractionHand.MAIN_HAND,
                blockHit(compactSupport)));

        assertTrue(compactResult.consumesAction(), "compact_launcher places on an empty 3x3 footprint");
        assertTrue(level.getBlockEntity(compactPos) instanceof CompactLauncherBlockEntity,
                "compact_launcher creates its core on an empty legacy footprint");
        assertTrue(level.getBlockState(compactPos).getShape(level, compactPos).isEmpty(),
                "compact_launcher core keeps old y=1..1 selection bounds");
        assertTrue(level.getBlockState(compactPos).getCollisionShape(level, compactPos).isEmpty(),
                "compact_launcher core keeps old y=1..1 collision bounds");
        assertTrue(level.getBlockState(compactPos.east()).getShape(level, compactPos.east()).isEmpty(),
                "compact_launcher cardinal plate dummy keeps a zero-height selection shape");
        assertTrue(level.getBlockState(compactPos.east()).getCollisionShape(level, compactPos.east()).isEmpty(),
                "compact_launcher cardinal plate dummy keeps a zero-height collision shape");
        assertFalse(level.getBlockState(compactPos.north().east()).getShape(level, compactPos.north().east()).isEmpty(),
                "compact_launcher corner port dummy keeps its local full selection shape");
        assertFalse(level.getBlockState(compactPos.north().east()).getCollisionShape(level,
                compactPos.north().east()).isEmpty(),
                "compact_launcher corner port dummy keeps its local full collision shape");

        BlockPos blockedSupport = compactSupport.east(6);
        BlockPos blockedCore = blockedSupport.above();
        level.setBlock(blockedSupport, Blocks.STONE.defaultBlockState(), Block.UPDATE_ALL);
        level.setBlock(blockedCore.east(), Blocks.DIRT.defaultBlockState(), Block.UPDATE_ALL);
        ItemStack blockedCompactStack = new ItemStack(ModBlocks.COMPACT_LAUNCHER.get());
        player.setItemInHand(InteractionHand.MAIN_HAND, blockedCompactStack);
        InteractionResult blockedResult = blockedCompactStack.useOn(new UseOnContext(player, InteractionHand.MAIN_HAND,
                blockHit(blockedSupport)));
        assertFalse(blockedResult.consumesAction(),
                "compact_launcher rejects an occupied footprint exactly as CompactLauncher#onBlockPlacedBy does");
        assertFalse(level.getBlockEntity(blockedCore) instanceof CompactLauncherBlockEntity,
                "rejected compact_launcher placement leaves no core behind");

        // LaunchPad, LaunchPadRusted, and LaunchPadLarge inherit BlockDummyable's
        // detailed collisionRayTrace footprint. Their core selection cannot fall
        // back to LegacyXrMultiblockBlock's local unit cube.
        BlockPos launchPadShapePos = compactSupport.east(14).above();
        BlockPos largeLaunchPadShapePos = compactSupport.east(16).above();
        BlockPos rustedLaunchPadShapePos = compactSupport.east(18).above();
        level.setBlock(launchPadShapePos, ModBlocks.LAUNCH_PAD.get().defaultBlockState(), Block.UPDATE_ALL);
        level.setBlock(largeLaunchPadShapePos, ModBlocks.LAUNCH_PAD_LARGE.get().defaultBlockState(), Block.UPDATE_ALL);
        level.setBlock(rustedLaunchPadShapePos, ModBlocks.LAUNCH_PAD_RUSTED.get().defaultBlockState(), Block.UPDATE_ALL);
        assertTrue(level.getBlockState(launchPadShapePos).getShape(level, launchPadShapePos).bounds().minX <= -1.5D,
                "launch_pad core selection keeps BlockDummyable's detailed 3x3 footprint");
        assertTrue(level.getBlockState(launchPadShapePos).getCollisionShape(level, launchPadShapePos).bounds().minX <= -1.5D,
                "launch_pad core collision keeps BlockDummyable's detailed 3x3 footprint");
        assertTrue(level.getBlockState(largeLaunchPadShapePos).getShape(level, largeLaunchPadShapePos).bounds().minX <= -4.5D,
                "launch_pad_large core selection keeps BlockDummyable's detailed 9x9 footprint");
        assertTrue(level.getBlockState(largeLaunchPadShapePos).getCollisionShape(level, largeLaunchPadShapePos).bounds().minX <= -4.5D,
                "launch_pad_large core collision keeps BlockDummyable's detailed 9x9 footprint");
        assertTrue(level.getBlockState(rustedLaunchPadShapePos).getShape(level, rustedLaunchPadShapePos).bounds().minX <= -1.5D,
                "launch_pad_rusted core selection keeps BlockDummyable's detailed 3x3 footprint");
        assertTrue(level.getBlockState(rustedLaunchPadShapePos).getCollisionShape(level, rustedLaunchPadShapePos).bounds().minX <= -1.5D,
                "launch_pad_rusted core collision keeps BlockDummyable's detailed 3x3 footprint");
        helper.succeed();
    }

    /**
     * EntityMissileBaseNT marks a shot dead before its damage-triggered destruction
     * explosion.  The modern VNT standard processor can include its exploder, so this
     * regression guards both that removal ordering and the resulting non-recursive
     * missile destruction path.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileLaunchChain")
    public static void missileDestructionRemovesItBeforeItsSelfDamageExplosion(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        MissileEntity missile = new MissileEntity(ModEntityTypes.MISSILE_TEST.get(), level, MissileEntity.Variant.TEST);
        missile.setPos(helper.absolutePos(new BlockPos(8, 8, 5)).getCenter());
        level.addFreshEntity(missile);

        assertTrue(missile.hurt(level.damageSources().generic(), 100.0F),
                "damage reaches the source-backed destructible missile");
        assertTrue(missile.isRemoved(),
                "missile is removed before its self-damaging destruction explosion can recurse");
        helper.succeed();
    }

    /**
     * EntityMissileBaseNT owns a single 50 HP field; Tier, form factor, radar
     * visibility, and tooltip part health never change a prebuilt missile's body HP.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileLaunchChain")
    public static void prebuiltMissilesKeepTheirSharedLegacyBaseHealth(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        for (MissileEntity.Variant variant : MissileEntity.Variant.values()) {
            MissileEntity missile = new MissileEntity(ModEntityTypes.MISSILE_TEST.get(), level, variant);
            assertTrue(missile.health() == MissileEntity.LEGACY_BASE_HEALTH,
                    "prebuilt " + variant + " keeps EntityMissileBaseNT's shared 50 HP");
        }
        helper.succeed();
    }

    /**
     * The old ABM source leaves {@code dist} at 1,000 after accepting a candidate,
     * so the last eligible entry in the radar cache wins rather than the nearest one.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileAbmRadarCache")
    public static void antiBallisticMissileKeepsLegacyRadarCacheIterationTarget(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos launchPos = helper.absolutePos(new BlockPos(112, 8, 5));

        AntiBallisticMissileEntity abm = new AntiBallisticMissileEntity(ModEntityTypes.MISSILE_ANTI_BALLISTIC.get(), level);
        abm.configureLaunch(launchPos.getX() + 0.5D, launchPos.getY() + 0.5D, launchPos.getZ() + 0.5D);

        MissileEntity firstEligible = new MissileEntity(ModEntityTypes.MISSILE_GENERIC.get(), level,
                MissileEntity.Variant.GENERIC);
        firstEligible.setPos(launchPos.getX() + 128.5D, launchPos.getY() + 96.0D, launchPos.getZ() + 0.5D);
        firstEligible.xo = firstEligible.getX();
        firstEligible.yo = firstEligible.getY();
        firstEligible.zo = firstEligible.getZ();
        level.addFreshEntity(firstEligible);

        MissileEntity lastEligible = new MissileEntity(ModEntityTypes.MISSILE_GENERIC.get(), level,
                MissileEntity.Variant.GENERIC);
        lastEligible.setPos(launchPos.getX() - 128.5D, launchPos.getY() + 96.0D, launchPos.getZ() + 0.5D);
        lastEligible.xo = lastEligible.getX();
        lastEligible.yo = lastEligible.getY();
        lastEligible.zo = lastEligible.getZ();
        level.addFreshEntity(lastEligible);
        RadarScanner.updateSystem(List.of(level));

        Entity expected = null;
        for (Entity candidate : RadarScanner.matchingEntitiesSnapshot()) {
            if (candidate instanceof MissileEntity missile && candidate.isAlive() && candidate.level() == level
                    && missile.radarProfile().canBeSeenBy(null)
                    && candidate.distanceToSqr(abm) < 1_000_000.0D) {
                expected = candidate;
            }
        }
        assertTrue(expected != null, "ABM fixture contributes an eligible source-backed radar-cache target");
        try {
            antiBallisticTargetMissile(abm);
            assertSame(expected, antiBallisticTrackingTarget(abm),
                    "ABM selects the last eligible legacy radar-cache missile instead of the nearest candidate");
        } finally {
            abm.discard();
            firstEligible.discard();
            lastEligible.discard();
        }
        helper.succeed();
    }

    /**
     * TileEntityLaunchPadBase#launchToEntity assigns the supplied entity directly to
     * the ABM.  The old ABM only replaces that target once it is dead; automatic
     * radar-cache acquisition is the separate missile-only path.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileAbmDirectTarget")
    public static void antiBallisticMissileKeepsDirectNonMissileTarget(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        // The empty template's upper barrier is at relative Y=122.  The ABM
        // spends forty ticks climbing before guidance, so keep this source
        // flight-path fixture above that barrier rather than testing impact.
        BlockPos launchPos = helper.absolutePos(new BlockPos(128, 124, 5));
        AntiBallisticMissileEntity abm = new AntiBallisticMissileEntity(ModEntityTypes.MISSILE_ANTI_BALLISTIC.get(), level);
        abm.configureLaunch(launchPos.getX() + 0.5D, launchPos.getY() + 0.5D, launchPos.getZ() + 0.5D);

        ItemEntity directTarget = new ItemEntity(level, launchPos.getX() + 128.5D, launchPos.getY() + 96.0D,
                launchPos.getZ() + 0.5D, new ItemStack(Items.IRON_INGOT));
        directTarget.xo = directTarget.getX();
        directTarget.yo = directTarget.getY();
        directTarget.zo = directTarget.getZ();
        level.addFreshEntity(directTarget);
        abm.setTrackingTarget(directTarget);
        RadarScanner.updateSystem(List.of(level));

        try {
            for (int tick = 0; tick <= 40; tick++) {
                abm.tick();
            }
            Vec3 targetDirection = directTarget.position().subtract(abm.position());
            assertTrue(abm.getDeltaMovement().dot(targetDirection) > 0.0D,
                    "ABM retains a still-live direct fire-control target even when it is not a missile");
        } finally {
            abm.discard();
            directTarget.discard();
        }
        helper.succeed();
    }

    /** The legacy ABM persists only its motion multiplier, not its activation state. */
