    /**
     * EntityMissileCustom deliberately leaves CLUSTER empty, while SCHRAB and
     * CUSTOM0..CUSTOM9 only have an optional CompatExternal callback in 1.7.10.
     * That integration is frozen, so none of those warheads may gain a synthetic
     * built-in explosion in the clean port.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileLaunchChain")
    public static void customMissileNoOpWarheadsKeepTheirLegacyImpactBoundary(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos impactPos = helper.absolutePos(new BlockPos(8, 8, 5));
        level.setBlock(impactPos, Blocks.STONE.defaultBlockState(), Block.UPDATE_ALL);
        Vec3 impact = impactPos.getCenter();

        assertTrue(CustomMissileExplosion.explode(level, impact.x, impact.y, impact.z, Vec3.ZERO, 10.0F,
                        CustomMissileExplosion.WarheadType.CLUSTER, null),
                "EntityMissileCustom keeps its legacy built-in cluster impact branch");
        assertTrue(level.getBlockState(impactPos).is(Blocks.STONE),
                "legacy custom cluster impact remains an intentional no-op");

        assertFalse(CustomMissileExplosion.explode(level, impact.x, impact.y, impact.z, Vec3.ZERO, 10.0F,
                        CustomMissileExplosion.WarheadType.SCHRAB, null),
                "SCHRAB has no built-in impact without the frozen legacy callback");
        for (CustomMissileExplosion.WarheadType type : List.of(
                CustomMissileExplosion.WarheadType.CUSTOM0, CustomMissileExplosion.WarheadType.CUSTOM1,
                CustomMissileExplosion.WarheadType.CUSTOM2, CustomMissileExplosion.WarheadType.CUSTOM3,
                CustomMissileExplosion.WarheadType.CUSTOM4, CustomMissileExplosion.WarheadType.CUSTOM5,
                CustomMissileExplosion.WarheadType.CUSTOM6, CustomMissileExplosion.WarheadType.CUSTOM7,
                CustomMissileExplosion.WarheadType.CUSTOM8, CustomMissileExplosion.WarheadType.CUSTOM9)) {
            assertFalse(CustomMissileExplosion.explode(level, impact.x, impact.y, impact.z, Vec3.ZERO, 10.0F, type, null),
                    type + " has no built-in impact without the frozen legacy callback");
        }
        assertTrue(level.getBlockState(impactPos).is(Blocks.STONE),
                "all source-backed custom-warhead no-op branches leave the impact block untouched");
        helper.succeed();
    }

