    /** Launch constructors enlarge missiles, while legacy world reloads return to EntityThrowable's default box. */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileLaunchChain")
    public static void missileFlightEntitiesKeepLegacyUniformCollisionSize(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        List<RegistryObject<EntityType<MissileEntity>>> prebuiltMissileTypes = List.of(
                ModEntityTypes.MISSILE_GENERIC, ModEntityTypes.MISSILE_DECOY, ModEntityTypes.MISSILE_INCENDIARY,
                ModEntityTypes.MISSILE_CLUSTER, ModEntityTypes.MISSILE_BUSTER, ModEntityTypes.MISSILE_STRONG,
                ModEntityTypes.MISSILE_INCENDIARY_STRONG, ModEntityTypes.MISSILE_CLUSTER_STRONG,
                ModEntityTypes.MISSILE_BUSTER_STRONG, ModEntityTypes.MISSILE_EMP_STRONG,
                ModEntityTypes.MISSILE_BURST, ModEntityTypes.MISSILE_INFERNO, ModEntityTypes.MISSILE_RAIN,
                ModEntityTypes.MISSILE_DRILL, ModEntityTypes.MISSILE_STEALTH, ModEntityTypes.MISSILE_EMP,
                ModEntityTypes.MISSILE_MICRO, ModEntityTypes.MISSILE_TEST, ModEntityTypes.MISSILE_SCHRABIDIUM,
                ModEntityTypes.MISSILE_BHOLE, ModEntityTypes.MISSILE_TAINT, ModEntityTypes.MISSILE_NUCLEAR,
                ModEntityTypes.MISSILE_NUCLEAR_CLUSTER, ModEntityTypes.MISSILE_VOLCANO,
                ModEntityTypes.MISSILE_DOOMSDAY, ModEntityTypes.MISSILE_SHUTTLE,
                ModEntityTypes.MISSILE_DOOMSDAY_RUSTED);

        for (RegistryObject<EntityType<MissileEntity>> missileType : prebuiltMissileTypes) {
            MissileEntity missile = missileType.get().create(level);
            if (missile == null) {
                throw new AssertionError("could not create prebuilt missile " + missileType.getId());
            }
            assertTrue(Math.abs(0.25F - missile.getBbWidth()) < 1.0E-6F,
                    missileType.getId() + " keeps EntityThrowable's world-constructor collision width");
            assertTrue(Math.abs(0.25F - missile.getBbHeight()) < 1.0E-6F,
                    missileType.getId() + " keeps EntityThrowable's world-constructor collision height");
            missile.configureLaunch(8.5D, 12.0D, -4.5D, 308.0D, 196.0D);
            assertTrue(Math.abs(1.5F - missile.getBbWidth()) < 1.0E-6F,
                    missileType.getId() + " keeps its legacy launch-constructor 1.5-wide collision");
            assertTrue(Math.abs(1.5F - missile.getBbHeight()) < 1.0E-6F,
                    missileType.getId() + " keeps its legacy launch-constructor 1.5-high collision");
            MissileEntity reloaded = missileType.get().create(level);
            if (reloaded == null) {
                throw new AssertionError("could not reload prebuilt missile " + missileType.getId());
            }
            reloaded.load(missile.saveWithoutId(new CompoundTag()));
            assertTrue(Math.abs(0.25F - reloaded.getBbWidth()) < 1.0E-6F,
                    missileType.getId() + " loses launch-only collision width after legacy NBT reload");
            assertTrue(Math.abs(0.25F - reloaded.getBbHeight()) < 1.0E-6F,
                    missileType.getId() + " loses launch-only collision height after legacy NBT reload");
        }

        AntiBallisticMissileEntity antiBallistic = new AntiBallisticMissileEntity(
                ModEntityTypes.MISSILE_ANTI_BALLISTIC.get(), level);
        CustomMissileEntity custom = new CustomMissileEntity(ModEntityTypes.MISSILE_CUSTOM.get(), level);
        assertEquals("entity_custom_missile", ModEntityTypes.MISSILE_CUSTOM.getId().getPath(),
                "custom missile keeps EntityMappings' legacy registry ID");
        assertTrue(Math.abs(1.5F - antiBallistic.getBbWidth()) < 1.0E-6F,
                "ABM keeps its explicit legacy 1.5-wide collision");
        assertTrue(Math.abs(1.5F - antiBallistic.getBbHeight()) < 1.0E-6F,
                "ABM keeps its explicit legacy 1.5-high collision");
        assertTrue(Math.abs(0.25F - custom.getBbWidth()) < 1.0E-6F,
                "custom missile keeps EntityThrowable's world-constructor collision width");
        assertTrue(Math.abs(0.25F - custom.getBbHeight()) < 1.0E-6F,
                "custom missile keeps EntityThrowable's world-constructor collision height");
        custom.configureLaunch(8.5D, 12.0D, -4.5D, 308.0D, 196.0D);
        assertTrue(Math.abs(1.5F - custom.getBbWidth()) < 1.0E-6F,
                "custom missile keeps its explicit legacy launch-constructor 1.5-wide collision");
        assertTrue(Math.abs(1.5F - custom.getBbHeight()) < 1.0E-6F,
                "custom missile keeps its explicit legacy launch-constructor 1.5-high collision");

        SoyuzCapsuleEntity soyuzCapsule = new SoyuzCapsuleEntity(ModEntityTypes.SOYUZ_CAPSULE.get(), level);
        assertTrue(Math.abs(0.25F - soyuzCapsule.getBbWidth()) < 1.0E-6F,
                "Soyuz capsule keeps EntityThrowable's legacy 0.25-wide collision");
        assertTrue(Math.abs(0.25F - soyuzCapsule.getBbHeight()) < 1.0E-6F,
                "Soyuz capsule keeps EntityThrowable's legacy 0.25-high collision");
        helper.succeed();
    }

