    /**
     * SoyuzCapsule consumes every client use, but server-side sneaking is its
     * sole legacy pass-through branch.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileLaunchChain")
    public static void soyuzCapsuleServerInteractionKeepsLegacySneakBranch(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos pos = helper.absolutePos(new BlockPos(14, 8, 14));
        level.setBlock(pos, ModBlocks.SOYUZ_CAPSULE.get().defaultBlockState(), Block.UPDATE_ALL);
        BlockState state = level.getBlockState(pos);
        var player = gameTestPlayer(level);

        player.setShiftKeyDown(false);
        assertSame(InteractionResult.CONSUME, state.use(level, player, InteractionHand.MAIN_HAND, blockHit(pos)),
                "Soyuz capsule server use opens its menu and consumes the legacy interaction");
        assertTrue(player.containerMenu instanceof com.hbm.ntm.menu.SoyuzCapsuleMenu,
                "Soyuz capsule server use opens SoyuzCapsuleMenu");
        player.closeContainer();

        player.setShiftKeyDown(true);
        assertSame(InteractionResult.PASS, state.use(level, player, InteractionHand.MAIN_HAND, blockHit(pos)),
                "sneaking on Soyuz capsule keeps the legacy server pass-through interaction");
        player.setShiftKeyDown(false);
        helper.succeed();
    }

    /**
     * TileEntityLaunchPadLarge only serializes its settled erector state.  The
     * schedule flag is a one-delay server animation latch, not saved state.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileLaunchChain")
    public static void largeLaunchPadKeepsErectionScheduleTransientAcrossReload(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos pos = helper.absolutePos(new BlockPos(4, 2, 4));
        BlockState state = ModBlocks.LAUNCH_PAD_LARGE.get().defaultBlockState();
        level.setBlock(pos, state, Block.UPDATE_ALL);
        if (!(level.getBlockEntity(pos) instanceof LargeLaunchPadBlockEntity launchPad)) {
            throw new AssertionError("No launch_pad_large block entity for transient erection fixture");
        }

        launchPad.getItems().setStackInSlot(LaunchPadBlockEntity.SLOT_MISSILE,
                new ItemStack(ModItems.MISSILE_ANTI_BALLISTIC.get()));
        energyStorage(launchPad).setPower(75_000L);
        CompoundTag reloaded = launchPad.saveWithoutMetadata();
        assertFalse(reloaded.contains("scheduleErect"),
                "large launch pad omits the legacy transient scheduleErect latch from NBT");

        // A tag produced by an earlier modern build must not turn this one-delay
        // latch into durable state.  With delay=10, preserving it would erect the
        // missile on this tick; old TileEntityLaunchPadLarge instead starts clean.
        reloaded.putBoolean("scheduleErect", true);
        reloaded.putFloat("lift", 0.0F);
        reloaded.putFloat("erector", 0.0F);
        reloaded.putInt("delay", 10);
        launchPad.load(reloaded);
        LargeLaunchPadBlockEntity.serverTick(level, pos, state, launchPad);
        assertFalse(launchPad.isErected(),
                "large launch pad reload ignores non-legacy scheduleErect and does not prematurely erect");
        assertFalse(launchPad.saveWithoutMetadata().contains("scheduleErect"),
                "large launch pad continues omitting the transient schedule latch after reload");
        helper.succeed();
    }

