    /**
     * {@code ExplosionChaos.cluster} passes missile degree fields into the legacy MK4
     * constructor's radian arguments.  Preserve that actual source behavior rather than
     * "correcting" the submunition cone to conventional degree conversion.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileLaunchChain")
    public static void missileClusterKeepsLegacyRadiansConstructorContract(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        Vec3 origin = Vec3.atCenterOf(helper.absolutePos(new BlockPos(14, 20, 9)));
        float legacyYawArgument = 1.0F;

        ExplosionChaos.cluster(level, origin.x, origin.y, origin.z, 1, legacyYawArgument, 0.0F,
                0.0F, 0.0F, 1.0F);
        List<BulletProjectileEntity> submunitions = level.getEntitiesOfClass(BulletProjectileEntity.class,
                new AABB(origin, origin).inflate(1.0D));
        assertEquals(1, submunitions.size(), "cluster impact spawns its one requested submunition");

        Vec3 motion = submunitions.get(0).getDeltaMovement();
        assertTrue(Math.abs(motion.x + Math.sin(legacyYawArgument)) < 1.0E-6D,
                "cluster submunition keeps the legacy radian-interpreted yaw X motion");
        assertTrue(Math.abs(motion.y) < 1.0E-6D,
                "zero legacy pitch argument keeps cluster submunition vertical motion zero");
        assertTrue(Math.abs(motion.z - Math.cos(legacyYawArgument)) < 1.0E-6D,
                "cluster submunition keeps the legacy radian-interpreted yaw Z motion");
        helper.succeed();
    }

    /** EntityMissileBaseNT updates target yaw and pitch even when motion is exactly zero. */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileLaunchChain")
    public static void missileZeroMotionKeepsLegacyRotationUpdate(GameTestHelper helper) {
        MissileEntity missile = new MissileEntity(ModEntityTypes.MISSILE_GENERIC.get(), helper.getLevel(),
                MissileEntity.Variant.GENERIC);
        missile.configureLaunch(4.5D, 12.0D, 4.5D, 20.0D, 4.0D);
        missile.setYRot(-37.0F);
        missile.setXRot(18.0F);

        missileUpdateRotationFromMotion(missile, Vec3.ZERO);

        float expectedYaw = (float) Math.toDegrees(Math.atan2(20.0D - 4.5D, 4.0D - 4.5D));
        assertTrue(Math.abs(missile.getYRot() - expectedYaw) < 1.0E-4F,
                "zero-motion missile still points yaw at its legacy integer X/Z target");
        assertTrue(Math.abs(missile.getXRot() + 90.0F) < 1.0E-6F,
                "zero-motion missile receives EntityMissileBaseNT's legacy -90 pitch");
        helper.succeed();
    }

    /** EntitySoyuz resets flight yaw and pitch to zero through setLocationAndAngles every tick. */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileLaunchChain")
    public static void soyuzFlightTickResetsLegacyRotation(GameTestHelper helper) {
        SoyuzEntity soyuz = new SoyuzEntity(helper.getLevel());
        assertFalse(soyuz.isNoGravity() || soyuz.noPhysics,
                "EntitySoyuz only bypasses its parent tick; its legacy constructor does not grant no-gravity or no-physics");
        soyuz.setPos(4.5D, 12.0D, 4.5D);
        soyuz.setYRot(73.0F);
        soyuz.setXRot(-26.0F);
        soyuz.setDeltaMovement(1.25D, 0.5D, -2.75D);

        soyuz.tick();

        assertTrue(Math.abs(soyuz.getYRot()) < 1.0E-6F,
                "Soyuz flight tick resets EntitySoyuz's legacy yaw to zero");
        assertTrue(Math.abs(soyuz.getXRot()) < 1.0E-6F,
                "Soyuz flight tick resets EntitySoyuz's legacy pitch to zero");
        assertTrue(Math.abs(soyuz.getX() - 5.75D) < 1.0E-6D,
                "Soyuz acceleration keeps EntitySoyuz's legacy horizontal X motion; actual=" + soyuz.getX());
        assertTrue(Math.abs(soyuz.getZ() - 1.75D) < 1.0E-6D,
                "Soyuz acceleration keeps EntitySoyuz's legacy horizontal Z motion; actual=" + soyuz.getZ());
        assertTrue(Math.abs(soyuz.getDeltaMovement().x - 1.25D) < 1.0E-6D
                        && Math.abs(soyuz.getDeltaMovement().z + 2.75D) < 1.0E-6D,
                "Soyuz acceleration does not clear legacy horizontal velocity");

        ItemStack referencedPayload = new ItemStack(Items.DIAMOND, 4);
        soyuz.setSat(referencedPayload);
        referencedPayload.setCount(1);
        CompoundTag soyuzPayloadSave = soyuz.saveWithoutId(new CompoundTag());
        assertEquals(1, soyuzPayloadSave.getList("items", Tag.TAG_COMPOUND).getCompound(0).getInt("Count"),
                "Soyuz setSat keeps the legacy direct ItemStack reference");

        CompoundTag soyuzPartialReload = new CompoundTag();
        soyuzPartialReload.put("items", new ListTag());
        soyuz.load(soyuzPartialReload);
        assertEquals(1, soyuz.saveWithoutId(new CompoundTag()).getList("items", Tag.TAG_COMPOUND)
                        .getCompound(0).getInt("Count"),
                "Soyuz empty legacy items reload retains cargo slots absent from the NBT list");
        helper.succeed();
    }

    /** SatelliteHorizons is a one-shot coordinate satellite that launches the legacy TOM descent entity. */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileLaunchChain")
    public static void horizonsSatelliteKeepsLegacyOneShotTomLaunch(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        Satellite created = Satellite.create(LegacySatelliteType.HORIZONS.legacyId());
        assertTrue(created instanceof com.hbm.saveddata.satellites.SatelliteHorizons,
                "legacy satellite ID creates the facade used by SavedData/runtime actions");
        com.hbm.saveddata.satellites.SatelliteHorizons horizons =
                (com.hbm.saveddata.satellites.SatelliteHorizons) created;
        var player = gameTestPlayer(level);
        int targetX = helper.absolutePos(new BlockPos(18, 8, -11)).getX();
        int targetZ = helper.absolutePos(new BlockPos(18, 8, -11)).getZ();

        // SatCoordPacket and ItemSatDesignator call the legacy public virtual,
        // not the modern boolean helper.  Exercise the direct modern class as
        // well as the SavedData facade below so this dispatch cannot silently
        // fall back to Satellite's empty base implementation.
        com.hbm.ntm.satellite.SatelliteHorizons directHorizons = new com.hbm.ntm.satellite.SatelliteHorizons();
        int directTargetX = targetX - 5;
        directHorizons.onCoordAction(level, player, directTargetX, 60, targetZ);
        assertTrue(directHorizons.used(),
                "direct modern Horizons public coordinate action keeps the legacy one-shot used write");
        directHorizons.onCoordAction(level, player, directTargetX + 7, 60, targetZ + 7);
        List<TomProjectileEntity> directToms = level.getEntitiesOfClass(TomProjectileEntity.class,
                new AABB(directTargetX, 599.5D, targetZ, directTargetX + 1.0D, 600.5D, targetZ + 1.0D));
        assertEquals(1, directToms.size(),
                "direct modern Horizons public coordinate action spawns exactly one legacy TOM projectile");
        directToms.forEach(TomProjectileEntity::discard);

        assertTrue(horizons.tryCoordAction(level, player, targetX, 60, targetZ),
                "unused Horizons satellite accepts its first legacy coordinate action");
        assertTrue(horizons.used(), "first Horizons coordinate action persists its one-shot used flag");
        assertFalse(horizons.tryCoordAction(level, player, targetX + 7, 60, targetZ + 7),
                "used Horizons satellite rejects a second legacy coordinate action");

        List<TomProjectileEntity> toms = level.getEntitiesOfClass(TomProjectileEntity.class,
                new AABB(targetX, 599.5D, targetZ, targetX + 1.0D, 600.5D, targetZ + 1.0D));
        assertEquals(1, toms.size(), "Horizons spawns exactly one TOM projectile at the legacy y=600 drop height");
        TomProjectileEntity tom = toms.get(0);
        assertTrue(Math.abs(tom.getX() - (targetX + 0.5D)) < 1.0E-6D
                        && Math.abs(tom.getZ() - (targetZ + 0.5D)) < 1.0E-6D,
                "Horizons preserves the legacy center-of-block TOM target coordinates");
        helper.succeed();
    }

    /** EntityMinerRocket resets flight yaw and pitch to zero through setPositionAndRotation every tick. */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileLaunchChain")
    public static void minerRocketFlightTickResetsLegacyRotation(GameTestHelper helper) {
        MinerRocketEntity rocket = new MinerRocketEntity(helper.getLevel());
        assertFalse(rocket.isNoGravity() || rocket.noPhysics,
                "EntityMinerRocket only bypasses its parent tick; its legacy constructor keeps default physics flags");
        rocket.setPos(4.5D, 12.0D, 4.5D);
        rocket.setYRot(-61.0F);
        rocket.setXRot(32.0F);
        rocket.setDeltaMovement(3.5D, 0.0D, -2.75D);

        rocket.tick();

        assertTrue(Math.abs(rocket.getYRot()) < 1.0E-6F,
                "miner rocket flight tick resets EntityMinerRocket's legacy yaw to zero");
        assertTrue(Math.abs(rocket.getXRot()) < 1.0E-6F,
                "miner rocket flight tick resets EntityMinerRocket's legacy pitch to zero");
        assertTrue(Math.abs(rocket.getX() - 4.5D) < 1.0E-6D
                        && Math.abs(rocket.getZ() - 4.5D) < 1.0E-6D,
                "miner rocket's legacy manual tick ignores horizontal delta movement");
        assertTrue(Math.abs(rocket.getDeltaMovement().x) < 1.0E-6D
                        && Math.abs(rocket.getDeltaMovement().z) < 1.0E-6D,
                "miner rocket resets legacy horizontal velocity to zero each tick");

        rocket.setMode(91);
        rocket.setPos(12.5D, 18.0D, 12.5D);
        rocket.setDeltaMovement(4.0D, 0.375D, -3.0D);
        rocket.tick();
        assertTrue(Math.abs(rocket.getY() - 18.375D) < 1.0E-6D,
                "miner rocket keeps legacy Y motion for an unrecognized watcher mode");
        assertTrue(Math.abs(rocket.getDeltaMovement().x) < 1.0E-6D
                        && Math.abs(rocket.getDeltaMovement().z) < 1.0E-6D,
                "miner rocket still clears X/Z for an unrecognized watcher mode");
        helper.succeed();
    }

    /**
     * EntityMinerRocket lands on the dock coordinate after its -0.75 descent,
     * spends exactly 101 unloading ticks before lifting, and persists only its
     * legacy mode/satellite/timer state.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void minerRocketKeepsLegacyDockingTimerAndNbtContract(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        // EntityMinerRocket's source coordinate casts are Java truncation, so
        // keep this source-shaped landing fixture above Y=0 as in 1.7.10.
        BlockPos dockPos = helper.absolutePos(new BlockPos(4, 96, 4));
        level.setBlock(dockPos, ModBlocks.SAT_DOCK.get().defaultBlockState(), Block.UPDATE_ALL);

        MinerRocketEntity rocket = new MinerRocketEntity(level);
        rocket.setPos(dockPos.getX() + 0.5D, dockPos.getY() + 1.75D, dockPos.getZ() + 0.5D);
        rocket.setSatelliteFrequency(73_311);
        rocket.tick();

        assertEquals(MinerRocketEntity.MODE_UNLOADING, rocket.mode(),
                "miner rocket switches from legacy landing to unloading when its descended foot coordinate is sat_dock");
        assertTrue(Math.abs(rocket.getY() - (dockPos.getY() + 1.0D)) < 1.0E-6D,
                "miner rocket truncates its landing Y to the legacy integer coordinate");
        assertTrue(Math.abs(rocket.getDeltaMovement().y) < 1.0E-6D,
                "miner rocket clears legacy vertical motion in the same tick it docks");
        assertEquals(1, rocket.timer(), "landing tick is the first legacy unloading timer tick");

        for (int i = 0; i < 99; i++) {
            rocket.tick();
        }
        assertEquals(100, rocket.timer(), "miner rocket remains unloading through legacy timer value 100");
        assertEquals(MinerRocketEntity.MODE_UNLOADING, rocket.mode(),
                "miner rocket does not lift until timer is strictly greater than 100");

        rocket.tick();
        assertEquals(101, rocket.timer(), "miner rocket increments its unloading timer before the lifting transition");
        assertEquals(MinerRocketEntity.MODE_LIFTING, rocket.mode(),
                "miner rocket switches to lifting exactly after legacy timer value 100");
        rocket.tick();
        assertTrue(Math.abs(rocket.getY() - (dockPos.getY() + 2.0D)) < 1.0E-6D,
                "lifting miner rocket moves upward by the legacy one block per tick");

        CompoundTag saved = rocket.saveWithoutId(new CompoundTag());
        assertTrue(saved.contains("mode", Tag.TAG_INT) && saved.contains("sat", Tag.TAG_INT)
                        && saved.contains("timer", Tag.TAG_INT),
                "miner rocket writes all three legacy NBT keys");
        MinerRocketEntity reloaded = new MinerRocketEntity(level);
        reloaded.load(saved);
        assertEquals(MinerRocketEntity.MODE_LIFTING, reloaded.mode(), "miner rocket reload keeps legacy mode");
        assertEquals(73_311, reloaded.satelliteFrequency(), "miner rocket reload keeps legacy satellite frequency");
        assertEquals(101, reloaded.timer(), "miner rocket reload keeps legacy unloading timer");
        helper.succeed();
    }

    /**
     * EntityBobmazon keeps its manual four-step descent loop rather than
     * entering Entity#onUpdate, and preserves its caller-supplied payload
     * stack reference through legacy NBT serialization.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void bobmazonDeliveryKeepsLegacyManualDescentAndPayloadReference(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos origin = helper.absolutePos(new BlockPos(4, 120, 4));
        BobmazonDeliveryEntity delivery = new BobmazonDeliveryEntity(level);
        assertFalse(delivery.isNoGravity() || delivery.noPhysics,
                "EntityBobmazon's manual descent does not set no-gravity or no-physics in its legacy constructor");
        delivery.setPos(origin.getX() + 0.5D, origin.getY(), origin.getZ() + 0.5D);
        delivery.setDeltaMovement(7.0D, 9.0D, -11.0D);

        // EntityBobmazon samples before every one of its four -0.5 steps.  The
        // GameTest runner's enclosing fixture blocks must not turn this pure
        // airborne-descent assertion into an intentional legacy impact test.
        List<BlockPos> flightSamples = List.of(
                new BlockPos(origin.getX(), origin.getY() + 1, origin.getZ()),
                new BlockPos(origin.getX(), origin.getY(), origin.getZ()),
                new BlockPos(origin.getX(), origin.getY(), origin.getZ()),
                new BlockPos(origin.getX(), origin.getY() - 1, origin.getZ()));
        for (BlockPos sample : flightSamples) {
            level.setBlock(sample, Blocks.AIR.defaultBlockState(), Block.UPDATE_ALL);
            assertTrue(level.getBlockState(sample).isAir(),
                    "Bobmazon airborne descent fixture clears legacy sample " + sample);
        }

        ItemStack payload = new ItemStack(Items.EMERALD, 2);
        delivery.setPayload(payload);
        payload.setCount(3);
        assertEquals(3, delivery.saveWithoutId(new CompoundTag()).getCompound("payload").getInt("Count"),
                "Bobmazon delivery keeps EntityBobmazon's caller payload-stack reference");

        delivery.tick();
        assertTrue(Math.abs(delivery.getX() - (origin.getX() + 0.5D)) < 1.0E-6D
                        && Math.abs(delivery.getY() - (origin.getY() - 2.0D)) < 1.0E-6D
                        && Math.abs(delivery.getZ() - (origin.getZ() + 0.5D)) < 1.0E-6D,
                "Bobmazon delivery keeps EntityBobmazon's four manual -0.5 descent steps and clears X/Z motion");
        assertEquals(0, delivery.tickCount,
                "Bobmazon delivery does not enter the modern parent tick absent from EntityBobmazon#onUpdate");
        helper.succeed();
    }

    /**
     * EntitySoyuzCapsule moves before applying gravity, then lands one block
     * above its integer-truncated impact coordinate with its legacy NBT cargo.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileLaunchChain")
    public static void soyuzCapsuleKeepsLegacyDescentLandingAndNbtContract(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos flightOrigin = helper.absolutePos(new BlockPos(4, 110, 4));

        SoyuzCapsuleEntity descent = new SoyuzCapsuleEntity(level);
        assertFalse(descent.isNoGravity() || descent.noPhysics,
                "EntitySoyuzCapsule's manual descent does not set no-gravity or no-physics in its legacy constructor");
        descent.setPos(flightOrigin.getX() + 0.5D, 110.5D, 4.5D);
        descent.setDeltaMovement(0.25D, -0.1D, -0.25D);
        descent.tick();
        assertTrue(Math.abs(descent.getX() - (flightOrigin.getX() + 0.75D)) < 1.0E-6D
                        && Math.abs(descent.getY() - 110.4D) < 1.0E-6D
                        && Math.abs(descent.getZ() - 4.25D) < 1.0E-6D,
                "Soyuz capsule moves using its pre-gravity legacy motion");
        assertTrue(Math.abs(descent.getDeltaMovement().y + 0.12D) < 1.0E-6D,
                "Soyuz capsule applies the legacy -0.02 gravity after moving");
        assertEquals(0, descent.tickCount,
                "Soyuz capsule keeps EntitySoyuzCapsule's no-parent-update tick counter boundary");

        SoyuzCapsuleEntity altitudeCap = new SoyuzCapsuleEntity(level);
        altitudeCap.setPos(8.5D, 599.95D, 8.5D);
        altitudeCap.setDeltaMovement(0.0D, 0.1D, 0.0D);
        altitudeCap.tick();
        assertTrue(Math.abs(altitudeCap.getY() - 600.0D) < 1.0E-6D,
                "Soyuz capsule caps post-move altitude at legacy Y=600");
        assertTrue(Math.abs(altitudeCap.getDeltaMovement().y - 0.08D) < 1.0E-6D,
                "Soyuz capsule still applies gravity on the legacy Y=600 cap tick");

        ItemStack[] payload = new ItemStack[SoyuzCapsuleEntity.PAYLOAD_SLOTS];
        payload[0] = new ItemStack(Items.DIAMOND, 3);
        payload[17] = new ItemStack(Items.PAPER, 2);
        SoyuzCapsuleEntity capsule = new SoyuzCapsuleEntity(level);
        assertTrue(capsule.fireImmune(), "Soyuz capsule keeps EntitySoyuzCapsule's legacy fire immunity");
        capsule.setSkin(91);
        assertEquals(91, capsule.soyuz,
                "Soyuz capsule keeps its raw public soyuz field outside the entity data watcher");
        capsule.payload = payload;
        assertSame(payload, capsule.payload,
                "Soyuz capsule exposes EntitySoyuzCapsule's nullable public payload array");
        assertTrue(capsule.payload[1] == null,
                "Soyuz capsule keeps an unassigned legacy payload slot null rather than normalizing it to EMPTY");
        payload[0].setCount(2);
        CompoundTag referenceSaved = capsule.saveWithoutId(new CompoundTag());
        assertEquals(2, referenceSaved.getList("items", Tag.TAG_COMPOUND).getCompound(0).getInt("Count"),
                "Soyuz capsule keeps EntitySoyuzCapsule's direct cargo-stack references");
        payload[0].setCount(3);
        CompoundTag saved = capsule.saveWithoutId(new CompoundTag());
        assertTrue(saved.contains("soyuz", Tag.TAG_INT) && saved.contains("items", Tag.TAG_LIST),
                "Soyuz capsule writes legacy soyuz and items NBT keys");
        ListTag savedItems = saved.getList("items", Tag.TAG_COMPOUND);
        assertEquals(2, savedItems.size(), "Soyuz capsule writes only non-empty legacy cargo slots");
        assertEquals(0, savedItems.getCompound(0).getByte("slot"), "Soyuz capsule keeps cargo slot zero NBT");
        assertEquals(17, savedItems.getCompound(1).getByte("slot"), "Soyuz capsule keeps cargo slot seventeen NBT");

        CompoundTag capsulePartialReload = new CompoundTag();
        capsulePartialReload.put("items", new ListTag());
        capsule.load(capsulePartialReload);
        assertEquals(2, capsule.saveWithoutId(new CompoundTag()).getList("items", Tag.TAG_COMPOUND).size(),
                "Soyuz capsule empty legacy items reload retains cargo slots absent from the NBT list");

        SoyuzCapsuleEntity reloaded = new SoyuzCapsuleEntity(level);
        reloaded.load(saved);
        BlockPos obstacle = helper.absolutePos(new BlockPos(12, 96, 12));
        level.setBlock(obstacle, Blocks.IRON_BLOCK.defaultBlockState(), Block.UPDATE_ALL);
        reloaded.setPos(obstacle.getX() + 0.5D, obstacle.getY() + 0.5D, obstacle.getZ() + 0.5D);
        reloaded.setDeltaMovement(0.0D, -0.5D, 0.0D);
        reloaded.tick();

        BlockPos landedAt = obstacle.above();
        assertTrue(reloaded.isRemoved(), "Soyuz capsule discards itself on its legacy integer-coordinate impact");
        assertSame(ModBlocks.SOYUZ_CAPSULE.get(), level.getBlockState(landedAt).getBlock(),
                "Soyuz capsule lands one block above its impact block");
        if (!(level.getBlockEntity(landedAt) instanceof com.hbm.ntm.blockentity.SoyuzCapsuleBlockEntity landed)) {
            throw new AssertionError("Soyuz capsule landing did not create its legacy 19-slot block entity");
        }
        assertSame(Items.DIAMOND, landed.getItems().getStackInSlot(0).getItem(),
                "Soyuz capsule restores cargo slot zero from legacy items NBT");
        assertEquals(3, landed.getItems().getStackInSlot(0).getCount(),
                "Soyuz capsule restores cargo slot zero count");
        assertSame(Items.PAPER, landed.getItems().getStackInSlot(17).getItem(),
                "Soyuz capsule restores cargo slot seventeen from legacy items NBT");
        ItemStack rocket = landed.getItems().getStackInSlot(18);
        assertSame(ModItems.MISSILE_SOYUZ.get(), rocket.getItem(),
                "Soyuz capsule stores a recovered Soyuz rocket in legacy slot eighteen");
        assertEquals(91, rocket.getOrCreateTag().getInt("skin"),
                "Soyuz capsule preserves its raw legacy soyuz watcher value in the recovered rocket");

        ItemStack[] directLandingPayload = new ItemStack[SoyuzCapsuleEntity.PAYLOAD_SLOTS];
        ItemStack directCargo = new ItemStack(Items.EMERALD, 4);
        directLandingPayload[0] = directCargo;
        SoyuzCapsuleEntity directLanding = new SoyuzCapsuleEntity(level);
        directLanding.payload = directLandingPayload;
        BlockPos directObstacle = helper.absolutePos(new BlockPos(16, 96, 12));
        level.setBlock(directObstacle, Blocks.IRON_BLOCK.defaultBlockState(), Block.UPDATE_ALL);
        directLanding.setPos(directObstacle.getX() + 0.5D, directObstacle.getY() + 0.5D, directObstacle.getZ() + 0.5D);
        directLanding.setDeltaMovement(0.0D, -0.5D, 0.0D);
        directLanding.tick();
        if (!(level.getBlockEntity(directObstacle.above())
                instanceof com.hbm.ntm.blockentity.SoyuzCapsuleBlockEntity directLanded)) {
            throw new AssertionError("Soyuz capsule direct-reference landing did not create its block entity");
        }
        assertSame(directCargo, directLanded.getItems().getStackInSlot(0),
                "Soyuz capsule landing keeps TileEntityInventoryBase's direct cargo-stack assignment");
        directCargo.setCount(2);
        assertEquals(2, directLanded.getItems().getStackInSlot(0).getCount(),
                "Soyuz capsule landed cargo remains the legacy source stack reference");

        var partialReload = new com.hbm.ntm.blockentity.SoyuzCapsuleBlockEntity(
                helper.absolutePos(new BlockPos(20, 8, 12)), ModBlocks.SOYUZ_CAPSULE.get().defaultBlockState());
        partialReload.getItems().setStackInSlot(0, new ItemStack(Items.EMERALD, 5));
        CompoundTag partialReloadTag = new CompoundTag();
        ListTag partialReloadItems = new ListTag();
        CompoundTag slotOne = new ItemStack(Items.DIAMOND, 2).save(new CompoundTag());
        slotOne.putByte("slot", (byte) 1);
        partialReloadItems.add(slotOne);
        partialReloadTag.put("items", partialReloadItems);
        partialReload.load(partialReloadTag);
        assertSame(Items.EMERALD, partialReload.getItems().getStackInSlot(0).getItem(),
                "Soyuz capsule partial legacy NBT read retains cargo slots absent from its list");
        assertSame(Items.DIAMOND, partialReload.getItems().getStackInSlot(1).getItem(),
                "Soyuz capsule partial legacy NBT read overwrites represented cargo slots");
        helper.succeed();
    }

