    /**
     * TileEntityLaunchPadRusted is a separate launch chain: release supplies its
     * non-launchable missile item, while firing consumes only a launch code and
     * retains the key.  Its designator target remains the legacy X/Z floor pair.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileLaunchChain")
    public static void rustedLaunchPadKeepsItsDedicatedCodeKeyAndCoordinateContract(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos launchPos = helper.absolutePos(new BlockPos(24, 7, 5));
        level.setBlock(launchPos, ModBlocks.LAUNCH_PAD_RUSTED.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(launchPos) instanceof RustedLaunchPadBlockEntity launchPad)) {
            throw new AssertionError("No launch_pad_rusted block entity for dedicated launch fixture");
        }

        var releasePlayer = gameTestPlayer(level);
        releasePlayer.setPos(launchPos.getX() + 0.5D, launchPos.getY() + 0.5D, launchPos.getZ() + 0.5D);
        assertTrue(launchPad.canReceiveLegacyButton(releasePlayer, 0, RustedLaunchPadBlockEntity.BUTTON_RELEASE),
                "rusted launch-pad release accepts the legacy button for an interacting player");
        releasePlayer.setPos(launchPos.getX() + 9.0D, launchPos.getY() + 0.5D, launchPos.getZ() + 0.5D);
        assertFalse(launchPad.canReceiveLegacyButton(releasePlayer, 0, RustedLaunchPadBlockEntity.BUTTON_RELEASE),
                "rusted launch-pad release rejects a player beyond its legacy eight-block use range");
        assertFalse(launchPad.canReceiveLegacyButton(releasePlayer, 0, RustedLaunchPadBlockEntity.BUTTON_RELEASE + 1),
                "rusted launch-pad release rejects an unknown legacy button id");

        launchPad.setMissileLoaded(true);
        launchPad.releaseMissile();
        assertFalse(launchPad.isMissileLoaded(), "release clears the rusted pad's loaded missile state");
        assertTrue(launchPad.getItems().getStackInSlot(RustedLaunchPadBlockEntity.SLOT_RELEASED_MISSILE)
                        .is(ModItems.MISSILE_DOOMSDAY_RUSTED.get()),
                "release supplies the dedicated non-launchable rusted doomsday missile item");

        IItemHandler externalInventory = launchPad.getCapability(ForgeCapabilities.ITEM_HANDLER, Direction.NORTH)
                .resolve()
                .orElseThrow(() -> new AssertionError("rusted launch pad exposes its legacy sided inventory facade"));
        assertEquals(1, externalInventory.getSlots(),
                "rusted launch pad exposes only legacy sided slot 0 to automation");
        assertTrue(externalInventory.getStackInSlot(0).is(ModItems.MISSILE_DOOMSDAY_RUSTED.get()),
                "rusted launch pad automation can observe the released missile in legacy slot 0");
        ItemStack rejectedCode = externalInventory.insertItem(0, new ItemStack(ModItems.LAUNCH_CODE.get()), false);
        assertTrue(rejectedCode.is(ModItems.LAUNCH_CODE.get()),
                "rusted launch pad automation rejects insertion just as TileEntityMachineBase did");
        assertTrue(externalInventory.extractItem(0, 1, false).isEmpty(),
                "rusted launch pad automation cannot extract its legacy sided slot");
        assertTrue(externalInventory.getStackInSlot(1).isEmpty(),
                "rusted launch pad code, key, and designator slots remain player-GUI-only");
        assertTrue(launchPad.getItems().getStackInSlot(RustedLaunchPadBlockEntity.SLOT_CODE).isEmpty(),
                "rejected automation insertion does not leak into the player-only launch-code slot");

        launchPad.getItems().setStackInSlot(RustedLaunchPadBlockEntity.SLOT_RELEASED_MISSILE, ItemStack.EMPTY);
        launchPad.setMissileLoaded(true);
        launchPad.getItems().setStackInSlot(RustedLaunchPadBlockEntity.SLOT_CODE,
                new ItemStack(ModItems.LAUNCH_CODE.get()));
        launchPad.getItems().setStackInSlot(RustedLaunchPadBlockEntity.SLOT_KEY,
                new ItemStack(ModItems.LAUNCH_KEY.get()));
        ItemStack designator = new ItemStack(ModItems.DESIGNATOR.get());
        MissileDesignatorItem.setTarget(designator, -53, 81);
        launchPad.getItems().setStackInSlot(RustedLaunchPadBlockEntity.SLOT_DESIGNATOR, designator);

        assertTrue(launchPad.launch(), "rusted launch pad fires when code, key, designator, and missile are ready");
        assertTrue(launchPad.getItems().getStackInSlot(RustedLaunchPadBlockEntity.SLOT_CODE).isEmpty(),
                "rusted launch consumes exactly one launch code");
        assertTrue(launchPad.getItems().getStackInSlot(RustedLaunchPadBlockEntity.SLOT_KEY)
                        .is(ModItems.LAUNCH_KEY.get()),
                "rusted launch retains its launch key");
        assertMissileEndpointTags(singleMissileAt(level, launchPos), launchPos.getX(), launchPos.getZ(), -53, 81,
                "rusted launch");
        helper.succeed();
    }

    /**
     * ItemCustomMissile exposes only the eight legacy assembly lines once its NBT
     * references every required part; untagged items intentionally remain silent.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileItems")
    public static void customMissileTooltipPreservesLegacyAssemblyContract(GameTestHelper helper) {
        ItemStack complete = completeSize10SolidCustomMissile();
        List<Component> completeTooltip = new ArrayList<>();
        complete.getItem().appendHoverText(complete, helper.getLevel(), completeTooltip, TooltipFlag.Default.NORMAL);
        assertEquals(8, completeTooltip.size(), "complete custom missile has eight legacy tooltip lines");
        assertTrue(completeTooltip.get(0).getString().contains("HE"),
                "complete custom missile exposes its source-backed warhead line");
        assertTrue(completeTooltip.get(5).getString().endsWith("100.0%"),
                "custom missile without fins keeps legacy 100 percent fin inaccuracy");
        assertTrue(completeTooltip.get(6).getString().endsWith("1.0m/1.0m"),
                "custom missile exposes the source-backed fuselage size pair");
        assertTrue(completeTooltip.get(7).getString().endsWith("45.0HP"),
                "custom missile tooltip sums legacy part health instead of entity health");

        ItemStack untagged = new ItemStack(ModItems.MISSILE_CUSTOM.get());
        List<Component> untaggedTooltip = new ArrayList<>();
        untagged.getItem().appendHoverText(untagged, helper.getLevel(), untaggedTooltip, TooltipFlag.Default.NORMAL);
        assertEquals(0, untaggedTooltip.size(), "untagged custom missile keeps legacy empty tooltip");

        ItemStack incomplete = new ItemStack(ModItems.MISSILE_CUSTOM.get());
        CustomMissileItem.setPart(incomplete, CustomMissileItem.TAG_CHIP, customMissilePart("mp_c_5"));
        List<Component> incompleteTooltip = new ArrayList<>();
        incomplete.getItem().appendHoverText(incomplete, helper.getLevel(), incompleteTooltip, TooltipFlag.Default.NORMAL);
        assertEquals(1, incompleteTooltip.size(), "incomplete custom missile reports one legacy generic error line");
        helper.succeed();
    }

