    /**
     * MissileTab injected nine source-authored, named custom-missile stacks in
     * addition to its ordinary creative-tab items. They must remain assembled
     * stacks rather than becoming new registry entries or unconfigured missiles.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileItems")
    public static void missileCreativeTabKeepsLegacyCustomPresets(GameTestHelper helper) {
        assertTrue(ModCreativeTabs.MISSILES.get().getIconItem().is(ModItems.MISSILE_NUCLEAR.get()),
                "legacy MissileTab uses the nuclear missile as its tab icon");
        // The tab's cached display collection is hydrated by the client-side
        // CreativeModeTabs rebuild path, which a dedicated GameTest server does
        // not execute. Exercise the same registered generator instead.
        List<ItemStack> displayedItems = new ArrayList<>();
        ModCreativeTabs.populateMissileTabContents((stack, visibility) -> displayedItems.add(stack.copy()));
        for (var part : ModItems.MISSILE_PART_ITEMS) {
            assertTrue(displayedItems.stream().anyMatch(stack -> stack.is(part.get())),
                    "legacy MissileTab keeps custom missile part " + part.getId() + " visible");
        }
        for (Item missileTabBlock : List.of(ModBlocks.MACHINE_RADAR.get().asItem(),
                ModBlocks.MACHINE_RADAR_LARGE.get().asItem(), ModBlocks.MACHINE_RADAR_SCREEN.get().asItem(),
                ModBlocks.MACHINE_FORCEFIELD.get().asItem())) {
            assertTrue(displayedItems.stream().anyMatch(stack -> stack.is(missileTabBlock)),
                    "legacy MissileTab keeps block item " + missileTabBlock + " visible");
        }
        List<ItemStack> presets = ModItems.legacyMissileCreativePresets();
        String[] names = {
                "Lil Bub", "Long Boy", "Uncle Kim", "Trotty's Toy Rocket", "Stealthy Shark",
                "Polite Lad", "NERV's Leftover Missile", "Auntie Blackjack", "Hightower Missile"
        };
        ChatFormatting[] colors = {
                ChatFormatting.DARK_PURPLE, ChatFormatting.DARK_PURPLE, ChatFormatting.DARK_PURPLE,
                ChatFormatting.GREEN, ChatFormatting.DARK_PURPLE, ChatFormatting.DARK_PURPLE,
                ChatFormatting.DARK_PURPLE, ChatFormatting.RED, ChatFormatting.GREEN
        };
        assertEquals(names.length, presets.size(), "legacy missile tab exposes every custom preset");
        for (int index = 0; index < names.length; index++) {
            ItemStack preset = presets.get(index);
            assertTrue(preset.is(ModItems.MISSILE_CUSTOM.get()),
                    "legacy missile-tab preset " + index + " is a custom missile stack");
            assertEquals(names[index], preset.getHoverName().getString(),
                    "legacy missile-tab preset " + index + " keeps its source name");
            assertEquals(colors[index].getColor(), preset.getHoverName().getStyle().getColor().getValue(),
                    "legacy missile-tab preset " + index + " keeps its source name colour");
            assertTrue(CustomMissileItem.getPartId(preset, CustomMissileItem.TAG_CHIP) != null
                            && CustomMissileItem.getPartId(preset, CustomMissileItem.TAG_WARHEAD) != null
                            && CustomMissileItem.getPartId(preset, CustomMissileItem.TAG_FUSELAGE) != null
                            && CustomMissileItem.getPartId(preset, CustomMissileItem.TAG_THRUSTER) != null,
                    "legacy missile-tab preset " + index + " retains its required part NBT");
        }
        assertTrue(CustomMissileItem.getPartId(presets.get(8), CustomMissileItem.TAG_STABILITY) == null,
                "Hightower Missile retains MissileTab's missing stability part");
        assertTrue(displayedItems.size() >= presets.size(),
                "legacy MissileTab display contains the manually appended custom presets");
        int firstPreset = displayedItems.size() - presets.size();
        for (int index = 0; index < presets.size(); index++) {
            ItemStack displayedPreset = displayedItems.get(firstPreset + index);
            assertTrue(displayedPreset.is(ModItems.MISSILE_CUSTOM.get()),
                    "legacy MissileTab appends custom preset " + index + " after all regular tab content");
            assertEquals(names[index], displayedPreset.getHoverName().getString(),
                    "legacy MissileTab preserves custom preset tail order " + index);
        }
        helper.succeed();
    }

