    /**
     * The legacy missile-assembly Container used ordinary input Slots while its
     * ISidedInventory rejected every automation insertion.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileItems")
    public static void missileAssemblyKeepsLegacyManualInputAndAutomationBoundary(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos assemblyPos = helper.absolutePos(new BlockPos(28, 7, 6));
        level.setBlock(assemblyPos, ModBlocks.MACHINE_MISSILE_ASSEMBLY.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(assemblyPos) instanceof MissileAssemblyBlockEntity assembly)) {
            throw new AssertionError("No missile assembly block entity for inventory-boundary test");
        }
        assertSame(LegacyMachineRenderBounds.INFINITE_EXTENT_AABB, assembly.getRenderBoundingBox(),
                "missile assembly keeps TileEntityMachineMissileAssembly's infinite render boundary");

        ItemStack dirt = new ItemStack(Blocks.DIRT);
        ItemStack validChip = customMissilePart("mp_c_5");
        assertFalse(assembly.getItems().isItemValid(MissileAssemblyBlockEntity.SLOT_CHIP, dirt),
                "legacy missile assembly rejects arbitrary automation insertion");
        assertFalse(assembly.getItems().isItemValid(MissileAssemblyBlockEntity.SLOT_CHIP, validChip),
                "legacy missile assembly also rejects valid-part automation insertion");
        assertSame(Blocks.DIRT.asItem(), assembly.getItems().insertItem(
                MissileAssemblyBlockEntity.SLOT_CHIP, dirt.copy(), false).getItem(),
                "rejected automation insertion returns its original stack");

        assembly.getItems().setStackInSlot(MissileAssemblyBlockEntity.SLOT_CHIP, validChip.copy());
        IItemHandler externalInventory = assembly.getCapability(ForgeCapabilities.ITEM_HANDLER, Direction.NORTH)
                .orElseThrow(() -> new AssertionError("legacy missile assembly exposes its sided slot 0"));
        assertEquals(1, externalInventory.getSlots(),
                "legacy missile assembly exposes only its sided chip slot to automation");
        assertSame(validChip.getItem(), externalInventory.getStackInSlot(0).getItem(),
                "legacy sided inventory maps its only visible slot to chip slot 0");
        assertSame(Blocks.DIRT.asItem(), externalInventory.insertItem(0, dirt.copy(), false).getItem(),
                "legacy sided inventory rejects automation insertion");
        assertTrue(externalInventory.extractItem(0, 1, false).isEmpty(),
                "legacy sided inventory rejects automation extraction");

        var player = gameTestPlayer(level);
        MissileAssemblyMenu menu = new MissileAssemblyMenu(0, player.getInventory(), assembly);
        for (int slot = MissileAssemblyBlockEntity.SLOT_CHIP; slot <= MissileAssemblyBlockEntity.SLOT_THRUSTER; slot++) {
            assertTrue(menu.getSlot(slot).mayPlace(dirt),
                    "legacy manual input slot " + slot + " remains unfiltered");
        }
        assertFalse(menu.getSlot(MissileAssemblyBlockEntity.SLOT_OUTPUT).mayPlace(dirt),
                "legacy missile assembly output remains take-only");
        helper.succeed();
    }

    /**
     * TileEntitySoyuzLauncher inherited an all-false automation inventory while
     * ContainerSoyuzLauncher exposed every one of its 27 machine slots as an
     * ordinary player Slot.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileItems")
    public static void soyuzLauncherKeepsLegacyManualSlotsAndRejectsAutomation(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos launcherPos = helper.absolutePos(new BlockPos(34, 7, 6));
        level.setBlock(launcherPos, ModBlocks.SOYUZ_LAUNCHER.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(launcherPos) instanceof SoyuzLauncherBlockEntity launcher)) {
            throw new AssertionError("No soyuz launcher block entity for inventory-boundary test");
        }

        assertFalse(launcher.getCapability(ForgeCapabilities.ITEM_HANDLER, Direction.NORTH).isPresent(),
                "legacy Soyuz launcher exposes no sided inventory automation capability");
        ItemStack dirt = new ItemStack(Blocks.DIRT);
        ItemStack soyuz = new ItemStack(ModItems.MISSILE_SOYUZ.get());
        assertFalse(launcher.getItems().isItemValid(SoyuzLauncherBlockEntity.SLOT_ROCKET, dirt),
                "legacy Soyuz launcher rejects arbitrary automation insertion");
        assertFalse(launcher.getItems().isItemValid(SoyuzLauncherBlockEntity.SLOT_ROCKET, soyuz),
                "legacy Soyuz launcher also rejects a valid rocket from automation");
        assertSame(Items.DIRT, launcher.getItems().insertItem(SoyuzLauncherBlockEntity.SLOT_ROCKET,
                dirt.copy(), false).getItem(), "rejected Soyuz automation insertion returns its stack");

        var player = gameTestPlayer(level);
        SoyuzLauncherMenu menu = new SoyuzLauncherMenu(0, player.getInventory(), launcher);
        for (int slot = SoyuzLauncherBlockEntity.SLOT_ROCKET; slot < SoyuzLauncherBlockEntity.SLOT_COUNT; slot++) {
            assertTrue(menu.getSlot(slot).mayPlace(dirt),
                    "legacy Soyuz player slot " + slot + " remains an ordinary unfiltered Slot");
        }

        player.getInventory().setItem(9, new ItemStack(Items.DIAMOND));
        assertSame(Items.DIAMOND, menu.quickMoveStack(player, SoyuzLauncherBlockEntity.SLOT_COUNT).getItem(),
                "Soyuz launcher's first player menu slot returns its legacy shift-click source stack");
        assertTrue(launcher.getItems().getStackInSlot(SoyuzLauncherBlockEntity.SLOT_ROCKET).isEmpty(),
                "Soyuz launcher's first player menu slot keeps ContainerSoyuzLauncher's overlapping <= 27 branch");
        assertEquals(1, player.getInventory().items.stream()
                        .filter(stack -> stack.is(Items.DIAMOND)).mapToInt(ItemStack::getCount).sum(),
                "Soyuz launcher's overlapping first-player shift-click stays within the legacy cargo/player range");

        player.getInventory().setItem(10, new ItemStack(Items.PAPER));
        assertSame(Items.PAPER, menu.quickMoveStack(player, SoyuzLauncherBlockEntity.SLOT_COUNT + 1).getItem(),
                "Soyuz launcher's second player menu slot returns its legacy shift-click source stack");
        assertSame(Items.PAPER, launcher.getItems().getStackInSlot(SoyuzLauncherBlockEntity.SLOT_ROCKET).getItem(),
                "Soyuz launcher shifts later player slots only into legacy rocket slot zero");
        launcher.getItems().setStackInSlot(SoyuzLauncherBlockEntity.SLOT_ROCKET, ItemStack.EMPTY);

        CompoundTag nameOnly = new CompoundTag();
        nameOnly.putString("name", "");
        launcher.load(nameOnly);
        CompoundTag saved = launcher.saveWithoutMetadata();
        assertTrue(saved.contains("name", Tag.TAG_STRING),
                "Soyuz launcher writes TileEntityMachineBase's non-null empty custom name");
        assertTrue(saved.contains("mode", Tag.TAG_BYTE),
                "Soyuz launcher writes TileEntitySoyuzLauncher's byte mode NBT");
        assertFalse(saved.contains("starting"),
                "Soyuz launcher does not persist TileEntitySoyuzLauncher's runtime starting flag");
        assertFalse(saved.contains("countdown"),
                "Soyuz launcher does not persist TileEntitySoyuzLauncher's runtime countdown");
        assertEquals(0, launcher.getCountdown(),
                "Soyuz launcher keeps TileEntitySoyuzLauncher's uninitialized runtime countdown after load");
        SoyuzLauncherBlockEntity.serverTick(level, launcherPos, level.getBlockState(launcherPos), launcher);
        assertEquals(SoyuzLauncherBlockEntity.MAX_COUNTDOWN, launcher.getCountdown(),
                "Soyuz launcher's first server tick resets its inactive legacy countdown");

        SoyuzLauncherBlockEntity reloaded = new SoyuzLauncherBlockEntity(launcherPos,
                ModBlocks.SOYUZ_LAUNCHER.get().defaultBlockState());
        reloaded.load(saved);
        assertFalse(reloaded.isStarting(),
                "Soyuz launcher reload resets TileEntitySoyuzLauncher's non-persistent starting flag");
        assertEquals(0, reloaded.getCountdown(),
                "Soyuz launcher reload keeps TileEntitySoyuzLauncher's uninitialized non-persistent countdown");

        player.setPos(launcherPos.getX() + 10.5D, launcherPos.getY() + 0.5D, launcherPos.getZ() + 0.5D);
        assertTrue(menu.stillValid(player),
                "Soyuz launcher menu keeps TileEntityMachineBase's 128-square interaction radius");
        helper.succeed();
    }

    /**
     * AuxButtonPacket handled the Soyuz controls by id only: mode was a raw
     * byte assignment and start ignored its value.  A mode packet did not
     * eagerly clear the old countdown; the next launcher tick owned that
     * readiness decision.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileSatellites")
    public static void soyuzLauncherButtonsKeepLegacyRawModeAndCountdownBoundary(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos launcherPos = helper.absolutePos(new BlockPos(34, 7, 8));
        level.setBlock(launcherPos, ModBlocks.SOYUZ_LAUNCHER.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(launcherPos) instanceof SoyuzLauncherBlockEntity launcher)) {
            throw new AssertionError("No soyuz launcher block entity for raw-button boundary test");
        }

        CompoundTag clientState = new CompoundTag();
        clientState.putBoolean("starting", true);
        clientState.putInt("countdown", 234);
        launcher.load(clientState);
        var player = gameTestPlayer(level);
        player.setPos(launcherPos.getX() + 0.5D, launcherPos.getY() + 0.5D, launcherPos.getZ() + 0.5D);

        assertTrue(launcher.canReceiveLegacyButton(player, 258, SoyuzLauncherBlockEntity.CONTROL_MODE),
                "Soyuz mode control preserves AuxButtonPacket's unfiltered raw value boundary");
        launcher.handleLegacyButton(player, 258, SoyuzLauncherBlockEntity.CONTROL_MODE);
        assertEquals(2, launcher.getMode(),
                "Soyuz mode control narrows the raw packet value through the legacy byte field");
        assertTrue(launcher.isStarting(),
                "changing Soyuz mode does not eagerly clear the legacy running flag");
        assertEquals(234, launcher.getCountdown(),
                "changing Soyuz mode does not eagerly reset the legacy countdown");

        CompoundTag idleState = new CompoundTag();
        idleState.putByte("mode", (byte) SoyuzLauncherBlockEntity.MODE_SATELLITE);
        idleState.putBoolean("starting", false);
        launcher.load(idleState);
        assertFalse(launcher.isStarting(), "Soyuz start fixture begins inactive");
        launcher.setPower(launcher.getMaxPower());
        launcher.getItems().setStackInSlot(SoyuzLauncherBlockEntity.SLOT_ROCKET,
                new ItemStack(ModItems.MISSILE_SOYUZ.get()));
        launcher.getItems().setStackInSlot(SoyuzLauncherBlockEntity.SLOT_SATELLITE,
                SatelliteItem.stack(ModItems.SATELLITE.get(), SatelliteItem.Variant.SPY));
        launcher.keroseneTank().setFill(launcher.getFuelRequired());
        assertTrue(launcher.canLaunch(), "Soyuz satellite fixture satisfies the old launch gate");
        assertTrue(launcher.canReceiveLegacyButton(player, -37, SoyuzLauncherBlockEntity.CONTROL_START),
                "Soyuz start control ignores AuxButtonPacket's raw value just like the old handler");
        launcher.handleLegacyButton(player, -37, SoyuzLauncherBlockEntity.CONTROL_START);
        assertTrue(launcher.isStarting(), "Soyuz start control still invokes startCountdown for any packet value");
        helper.succeed();
    }

    /**
     * TileEntitySoyuzLauncher transfers slots 9..26 directly to EntitySoyuz,
     * then clears only the launcher inventory references.  Do not copy cargo
     * stacks while crossing the launcher/entity boundary.
     */
    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "missileLaunchChain")
    public static void soyuzLauncherCargoLiftOffKeepsLegacyStackReferences(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos launcherPos = helper.absolutePos(new BlockPos(34, 7, 10));
        level.setBlock(launcherPos, ModBlocks.SOYUZ_LAUNCHER.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(launcherPos) instanceof SoyuzLauncherBlockEntity launcher)) {
            throw new AssertionError("No soyuz launcher block entity for cargo-reference launch test");
        }

        CompoundTag cargoMode = new CompoundTag();
        cargoMode.putByte("mode", (byte) SoyuzLauncherBlockEntity.MODE_CARGO);
        launcher.load(cargoMode);
        launcher.setPower(launcher.getMaxPower());
        launcher.getItems().setStackInSlot(SoyuzLauncherBlockEntity.SLOT_ROCKET,
                new ItemStack(ModItems.MISSILE_SOYUZ.get()));
        ItemStack designator = new ItemStack(ModItems.DESIGNATOR.get());
        MissileDesignatorItem.setTarget(designator, launcherPos.getX() + 8, launcherPos.getZ() - 5);
        launcher.getItems().setStackInSlot(SoyuzLauncherBlockEntity.SLOT_DESIGNATOR, designator);
        launcher.keroseneTank().setFill(launcher.getFuelRequired());
        launcher.oxygenTank().setFill(launcher.getFuelRequired());
        ItemStack cargo = new ItemStack(Items.EMERALD, 4);
        launcher.getItems().setStackInSlot(SoyuzLauncherBlockEntity.SLOT_CARGO_START, cargo);

        assertTrue(launcher.canLaunch(), "Soyuz launcher cargo fixture meets its legacy launch gate");
        launcher.startCountdown();
        for (int tick = 0; tick <= SoyuzLauncherBlockEntity.MAX_COUNTDOWN; tick++) {
            SoyuzLauncherBlockEntity.serverTick(level, launcherPos, level.getBlockState(launcherPos), launcher);
        }

        List<SoyuzEntity> launched = level.getEntitiesOfClass(SoyuzEntity.class,
                new AABB(launcherPos).inflate(2.0D, 4.0D, 2.0D));
        assertEquals(1, launched.size(), "Soyuz launcher completes its legacy cargo lift-off");
        assertTrue(launcher.getItems().getStackInSlot(SoyuzLauncherBlockEntity.SLOT_CARGO_START).isEmpty(),
                "Soyuz launcher clears the transferred cargo slot");
        cargo.setCount(2);
        CompoundTag launchedNbt = launched.get(0).saveWithoutId(new CompoundTag());
        assertEquals(2, launchedNbt.getList("items", Tag.TAG_COMPOUND).getCompound(0).getInt("Count"),
                "Soyuz launcher passes the source cargo stack directly to EntitySoyuz");

        SoyuzEntity launchedSoyuz = launched.get(0);
        launchedSoyuz.setPos(launcherPos.getX() + 0.5D, 601.0D, launcherPos.getZ() + 0.5D);
        launchedSoyuz.setDeltaMovement(Vec3.ZERO);
        launchedSoyuz.tick();
        BlockPos target = new BlockPos(launcherPos.getX() + 8, 600, launcherPos.getZ() - 5);
        List<SoyuzCapsuleEntity> deployed = level.getEntitiesOfClass(SoyuzCapsuleEntity.class,
                new AABB(target).inflate(1.0D, 1.0D, 1.0D));
        assertEquals(1, deployed.size(), "cargo Soyuz deploys exactly one legacy recovery capsule above Y=600");
        assertSame(cargo, deployed.get(0).payload[0],
                "cargo Soyuz transfers the legacy payload array's source stack directly to the recovery capsule");
        helper.succeed();
    }

