    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty")
    public static void fluidNetKeepsSingleSidedSubscriptionsUntilLegacyTransferPass(GameTestHelper helper) {
        HbmFluidNet net = new HbmFluidNet(HbmFluids.DIESEL);
        TestFluidProvider provider = new TestFluidProvider(HbmFluids.DIESEL, 100);
        net.addProvider(provider);
        forceFluidSubscriptionLastSeen(net, 0L);

        assertEquals(0L, net.update(), "single-sided legacy fluid net does not transfer");
        assertEquals(1, getFluidSubscriptionEntryCount(net, "providerEntries"),
                "FluidNetMK2 keeps a stale provider while its receiver set is empty");

        HbmFluidNet receiverOnlyNet = new HbmFluidNet(HbmFluids.DIESEL);
        TestFluidReceiver receiver = new TestFluidReceiver(HbmFluids.DIESEL, 100);
        receiverOnlyNet.addReceiver(receiver);
        forceFluidSubscriptionLastSeen(receiverOnlyNet, "receiverEntries", 0L);

        assertEquals(0L, receiverOnlyNet.update(), "provider-less legacy fluid net does not transfer");
        assertEquals(1, getFluidSubscriptionEntryCount(receiverOnlyNet, "receiverEntries"),
                "FluidNetMK2 keeps a stale receiver while its provider set is empty");
        helper.succeed();
    }

