    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty")
    public static void legacyVanillaMetaIngredientsKeepIdentityAcrossJsonAndNetwork(GameTestHelper helper) {
        ResourceLocation fish = new ResourceLocation("minecraft", "fish");
        assertTrue(LegacyMetaItemMappings.hasMapping(fish, 0), "legacy cod metadata is mapped");
        assertTrue(LegacyMetaItemMappings.hasMapping(fish, 1), "legacy salmon metadata is mapped");
        assertTrue(LegacyMetaItemMappings.hasMapping(fish, 2), "legacy tropical-fish metadata is mapped");
        assertTrue(LegacyMetaItemMappings.hasMapping(fish, 3), "legacy pufferfish metadata is mapped");
        assertEquals(4, LegacyMetaItemMappings.variantCount(fish), "legacy fish family reports every mapped meta");
        assertEquals(4, LegacyMetaItemMappings.stacksByMeta(fish, 1).size(),
                "carrier-neutral legacy fish mapping view exposes every meta");

        HbmIngredient pufferfish = HbmIngredient.legacyMeta(fish, 3, 2);
        assertTrue(pufferfish.test(new ItemStack(Items.PUFFERFISH, 2)),
                "legacy fish meta 3 ingredient matches pufferfish");
        assertTrue(!pufferfish.test(new ItemStack(Items.SALMON, 2)),
                "legacy fish meta 3 ingredient rejects a different split fish item");
        assertEquals("minecraft:fish", pufferfish.legacyId().toString(), "legacy fish ingredient keeps old ID");
        assertEquals(3, pufferfish.legacyMeta(), "legacy fish ingredient keeps old meta");

        HbmIngredient jsonRoundTrip = HbmIngredient.fromJson(pufferfish.toJson());
        assertTrue(jsonRoundTrip.test(new ItemStack(Items.PUFFERFISH, 2)),
                "legacy fish ingredient survives datapack JSON round trip");
        FriendlyByteBuf buffer = new FriendlyByteBuf(Unpooled.buffer());
        pufferfish.toNetwork(buffer);
        HbmIngredient networkRoundTrip = HbmIngredient.fromNetwork(buffer);
        assertTrue(networkRoundTrip.test(new ItemStack(Items.PUFFERFISH, 2)),
                "legacy fish ingredient survives recipe-network round trip");

        HbmIngredient wildcard = HbmIngredient.legacyMeta(fish, HbmIngredient.WILDCARD_META, 1);
        assertTrue(wildcard.legacyWildcard(), "legacy wildcard meta is normalized to the wildcard ingredient contract");
        assertTrue(wildcard.test(new ItemStack(Items.COD)), "legacy fish wildcard matches cod");
        assertTrue(wildcard.test(new ItemStack(Items.PUFFERFISH)), "legacy fish wildcard matches pufferfish");
        assertTrue(HbmIngredient.fromJson(wildcard.toJson()).legacyWildcard(),
                "legacy fish wildcard survives datapack JSON round trip");
        var oldStyleWildcard = wildcard.toJson();
        oldStyleWildcard.remove("legacy_wildcard");
        assertTrue(HbmIngredient.fromJson(oldStyleWildcard).legacyWildcard(),
                "legacy fish meta 32767 keeps wildcard semantics without the modern marker");

        var mismatched = pufferfish.toJson();
        mismatched.add("ingredient", Ingredient.of(Items.COD).toJson());
        boolean rejected = false;
        try {
            HbmIngredient.fromJson(mismatched);
        } catch (com.google.gson.JsonSyntaxException expected) {
            rejected = true;
        }
        assertTrue(rejected, "legacy meta provenance cannot claim a different modern ingredient");

        JsonArray legacyFishAStack = new JsonArray();
        legacyFishAStack.add("item");
        legacyFishAStack.add("minecraft:fish");
        legacyFishAStack.add(2);
        legacyFishAStack.add(3);
        AStack legacyFishInput = SerializableRecipe.readAStack(legacyFishAStack);
        assertTrue(legacyFishInput.matchesRecipe(new ItemStack(Items.PUFFERFISH, 2), false),
                "legacy SerializableRecipe input retains fish meta identity");
        assertTrue(!legacyFishInput.matchesRecipe(new ItemStack(Items.SALMON, 2), false),
                "legacy SerializableRecipe input rejects another split fish item");
        assertTrue(legacyFishAStack.equals(serializedLegacyAStack(legacyFishInput)),
                "legacy SerializableRecipe AStack round trip keeps fish ID and meta");
        JsonArray copiedFishAStack = serializedLegacyAStack(legacyFishInput.copy(4));
        assertEquals("minecraft:fish", copiedFishAStack.get(1).getAsString(),
                "legacy SerializableRecipe copied AStack keeps fish ID");
        assertEquals(4, copiedFishAStack.get(2).getAsInt(),
                "legacy SerializableRecipe copied AStack updates count without losing provenance");
        assertEquals(3, copiedFishAStack.get(3).getAsInt(),
                "legacy SerializableRecipe copied AStack keeps fish meta");
        JsonArray legacyFishOutput = serializedLegacyItemStack(new ItemStack(Items.PUFFERFISH, 2));
        assertEquals("minecraft:fish", legacyFishOutput.get(0).getAsString(),
                "legacy SerializableRecipe item output restores fish ID");
        assertEquals(2, legacyFishOutput.get(1).getAsInt(),
                "legacy SerializableRecipe item output keeps fish count");
        assertEquals(3, legacyFishOutput.get(2).getAsInt(),
                "legacy SerializableRecipe item output restores fish meta");
        helper.succeed();
    }

