    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "energyMk2NodespaceLifecycleTick")
    public static void energyNodespaceNodeCreationWaitsForServerStartBeforeBuildingNetwork(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        HbmEnergyNodespace.unloadLevel(level);
        try {
            BlockPos left = helper.absolutePos(new BlockPos(1, 2, 1));
            BlockPos right = left.east();
            level.setBlock(left, ModBlocks.RED_CABLE.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(right, ModBlocks.RED_CABLE.get().defaultBlockState(), Block.UPDATE_ALL);
            refreshEnergyNodeAt(level, left);
            refreshEnergyNodeAt(level, right);

            HbmEnergyNodespace.Diagnostics created = HbmEnergyNodespace.getDiagnostics(level);
            assertEquals(2, created.uniqueNodes(), "new real red_cable nodes are registered immediately");
            assertEquals(0, created.networks(), "new real red_cable nodes wait for the nodespace update to build a network");
            assertEquals(0, created.linkRefs(), "new real red_cable nodes have no links before the nodespace update");
            assertEquals(2, created.dirtyNodes(), "new real red_cable nodes stay marked changed until the nodespace update");
            assertEquals(2, created.orphanNodes(), "new real red_cable nodes have no valid network during their first tick");

            TestReceiver receiver = new TestReceiver(0L, 100L, 100L,
                    HbmEnergyReceiver.ConnectionPriority.NORMAL);
            assertTrue(!HbmEnergyUtil.subscribeReceiverToNetwork(level, left, Direction.WEST, receiver),
                    "receiver cannot subscribe while the newly created conductor has no network");

            CommonForgeEvents.onServerTick(new TickEvent.ServerTickEvent(
                    TickEvent.Phase.START, () -> true, level.getServer()));
            HbmEnergyNodespace.Diagnostics afterStart = HbmEnergyNodespace.getDiagnostics(level);
            assertEquals(1, afterStart.networks(), "server START nodespace update builds the real red_cable network");
            assertEquals(2, afterStart.linkRefs(), "server START nodespace update links both real red_cable nodes");
            assertEquals(0, afterStart.dirtyNodes(), "server START nodespace update clears node change markers");
            assertEquals(0, afterStart.orphanNodes(), "server START nodespace update gives both nodes a valid network");
            assertTrue(HbmEnergyUtil.subscribeReceiverToNetwork(level, left, Direction.WEST, receiver),
                    "receiver can subscribe after the server START nodespace update");
            assertEquals(1, HbmEnergyNodespace.getNetworkReceiverCount(level, left),
                    "post-update receiver subscription is stored on the established network");
        } finally {
            HbmEnergyNodespace.unloadLevel(level);
        }
        helper.succeed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosCoreLifecycle")
    public static void uninosCreatesNodesBeforeTheFollowingServerStartBuildsTheirNetworks(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        HbmEnergyNodespace.unloadLevel(level);
        try {
            BlockPos pos = helper.absolutePos(new BlockPos(12, 2, 12));
            HbmEnergyNode node = new HbmEnergyNode(pos, Set.of());

            HbmEnergyNodespace.createNode(level, node);
            assertSame(node, HbmEnergyNodespace.getNode(level, pos),
                    "legacy createNode registers the node mapping immediately");
            assertTrue(!node.hasValidNet() && !HbmEnergyNodespace.hasValidNetwork(level, pos),
                    "legacy createNode leaves the first node without a net until nodespace START processing");
            HbmEnergyNodespace.Diagnostics beforeStart = HbmEnergyNodespace.getDiagnostics(level);
            assertEquals(1, beforeStart.uniqueNodes(), "legacy first-creation fixture registers one node");
            assertEquals(0, beforeStart.networks(), "legacy first-creation fixture has no network before START");
            assertEquals(0, beforeStart.linkRefs(), "legacy first-creation fixture has no links before START");

            HbmEnergyNodespace.tick(level);
            assertTrue(node.hasValidNet(), "the following nodespace START builds the first node network");
            HbmEnergyNodespace.Diagnostics afterStart = HbmEnergyNodespace.getDiagnostics(level);
            assertEquals(1, afterStart.networks(), "the following nodespace START creates one network");
            assertEquals(1, afterStart.linkRefs(), "the following nodespace START links the created node");

            BlockPos expiredPos = pos.east();
            HbmEnergyNode expiredNode = new HbmEnergyNode(expiredPos, Set.of());
            expiredNode.setExpired(true);
            HbmEnergyNodespace.createNode(level, expiredNode);
            assertSame(expiredNode, HbmEnergyNodespace.getNode(level, expiredPos),
                    "legacy createNode still writes an expired node mapping");
            assertTrue(expiredNode.isExpired(),
                    "legacy createNode does not revive the caller's expired node object");

            BlockPos cleanPos = expiredPos.east();
            HbmEnergyNode cleanNode = new HbmEnergyNode(cleanPos, Set.of());
            cleanNode.clearRecentlyChanged();
            HbmEnergyNodespace.createNode(level, cleanNode);
            assertTrue(!cleanNode.isRecentlyChanged(),
                    "legacy createNode does not add a dirty flag to the caller's node object");
        } finally {
            HbmEnergyNodespace.unloadLevel(level);
        }
        helper.succeed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty")
    public static void nodeNetKeepsLegacyUnconditionalLeaveLinkContract(GameTestHelper helper) {
        BlockPos pos = helper.absolutePos(new BlockPos(1, 2, 1));
        HbmEnergyNode node = new HbmEnergyNode(pos, Set.of());
        HbmNodeNet<Object, Object, HbmEnergyNode> original = new HbmNodeNet<>();
        HbmNodeNet<Object, Object, HbmEnergyNode> replacement = new HbmNodeNet<>();

        original.forceJoinLink(node);
        replacement.forceJoinLink(node);
        assertSame(replacement, node.getNet(), "forceJoinLink retains the last legacy network assignment");
        assertTrue(original.containsLink(node), "forceJoinLink leaves the old legacy link set intact");

        original.leaveLink(node);
        assertTrue(node.getNet() == null,
                "legacy leaveLink clears the node network even when the caller is a stale old net");
        assertTrue(replacement.containsLink(node),
                "legacy leaveLink does not remove the stale node from the replacement link set");

        replacement.joinLink(node);
        assertSame(replacement, node.getNet(), "joinLink restores the replacement network after legacy leaveLink");
        helper.succeed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosCoreLifecycle")
    public static void nodeNetKeepsLegacyJoinNetworksEntryAndLifecycle(GameTestHelper helper) {
        BlockPos firstPos = helper.absolutePos(new BlockPos(1, 2, 1));
        BlockPos secondPos = firstPos.east();
        HbmEnergyNode firstNode = new HbmEnergyNode(firstPos, Set.of());
        HbmEnergyNode secondNode = new HbmEnergyNode(secondPos, Set.of());
        HbmNodeNet<Object, Object, HbmEnergyNode> receiving = new HbmNodeNet<>();
        HbmNodeNet<Object, Object, HbmEnergyNode> absorbed = new HbmNodeNet<>();
        Object absorbedReceiver = new Object();
        Object absorbedProvider = new Object();
        receiving.forceJoinLink(firstNode);
        absorbed.forceJoinLink(secondNode);
        absorbed.receiverEntries.put(absorbedReceiver, 0L);
        absorbed.providerEntries.put(absorbedProvider, 0L);

        receiving.joinNetworks(absorbed);

        assertTrue(receiving.containsLink(firstNode) && receiving.containsLink(secondNode),
                "legacy joinNetworks migrates every absorbed link into the receiving network");
        assertSame(receiving, firstNode.getNet(), "legacy joinNetworks retains the receiving node network");
        assertSame(receiving, secondNode.getNet(), "legacy joinNetworks reassigns each absorbed node network");
        assertTrue(receiving.isSubscribed(absorbedReceiver) && receiving.isProvider(absorbedProvider),
                "legacy base joinNetworks migrates generic receiver and provider entries");
        assertTrue(receiving.receiverEntries.get(absorbedReceiver) > 0L
                        && receiving.providerEntries.get(absorbedProvider) > 0L,
                "legacy base joinNetworks refreshes migrated generic subscription timestamps");
        assertTrue(!absorbed.isValid() && absorbed.linkCount() == 0,
                "legacy joinNetworks destroys and empties the absorbed network");
        assertTrue(absorbed.receiverEntries.isEmpty() && absorbed.providerEntries.isEmpty(),
                "legacy joinNetworks destroys the absorbed generic subscription maps");
        helper.succeed();
    }

