    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosCoreLifecycle")
    public static void pneumaticSlotMonitorRetainsLegacyNullEmptySlotContract(GameTestHelper helper) {
        PneumaticNetwork network = new PneumaticNetwork();
        PneumaticStackCache cache = new PneumaticStackCache(helper.absolutePos(new BlockPos(7, 2, 1)));
        ItemStack[] contents = {new ItemStack(Items.IRON_INGOT, 7)};
        PneumaticSlotMonitor[] monitors = new PneumaticSlotMonitor[1];
        PneumaticSlotMonitorProvider storage = new PneumaticSlotMonitorProvider() {
            @Override
            public PneumaticSlotMonitor[] getMonitors() {
                return monitors;
            }

            @Override
            public ItemStack getSlotAt(int index) {
                return contents[index];
            }

            @Override
            public long getAmountAt(int index) {
                return contents[index] == null ? 0L : contents[index].getCount();
            }

            @Override
            public boolean isAvailableToCache(PneumaticStackCache ignored) {
                return true;
            }

            @Override
            public PneumaticNetwork getRelevantNetwork() {
                return network;
            }
        };
        PneumaticSlotMonitor monitor = new PneumaticSlotMonitor(0, storage);
        monitors[0] = monitor;
        network.addStorage(storage);
        network.addStackCache(cache);

        monitor.checkUpdate();
        PneumaticStackCache.CacheSlot iron = cache.getCacheSlots().get(
                PneumaticStackCache.StackIdentity.of(new ItemStack(Items.IRON_INGOT)));
        assertTrue(iron != null && iron.getStackSize() == 7L,
                "legacy monitor initially publishes a non-empty provider slot into its cache");

        contents[0] = null;
        monitor.checkUpdate();
        assertTrue(monitor.getItem() == null,
                "legacy null inventory slots reset the monitor item identity instead of throwing");
        assertEquals(0L, iron.getStackSize(),
                "legacy null inventory slots detach their former typed cache aggregation");
        helper.succeed();
    }

