    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosCoreLifecycle")
    public static void specialisedNodeNetsKeepOneInheritedSubscriptionState(GameTestHelper helper) {
        HbmPowerNet powerNet = new HbmPowerNet(0L);
        HbmNodeNet<HbmEnergyReceiver, HbmEnergyProvider, HbmEnergyNode> powerBase = powerNet;
        TestProvider powerProvider = new TestProvider(20L, 20L);
        TestReceiver powerReceiver = new TestReceiver(0L, 20L, 20L, HbmEnergyReceiver.ConnectionPriority.NORMAL);
        powerBase.addProvider(powerProvider);
        powerBase.addReceiver(powerReceiver);
        assertSame(powerBase.providerEntries, powerNet.providerEntries,
                "PowerNet inherits the sole legacy provider subscription map");
        assertSame(powerBase.receiverEntries, powerNet.receiverEntries,
                "PowerNet inherits the sole legacy receiver subscription map");
        assertEquals(20L, powerNet.update(),
                "PowerNet transfer consumes subscriptions registered through its NodeNet base view");

        HbmFluidNet fluidNet = new HbmFluidNet(HbmFluids.DIESEL, 0L);
        com.hbm.ntm.uninos.HbmNodeNet<HbmFluidReceiver, HbmFluidProvider, HbmFluidNode> fluidBase = fluidNet;
        TestFluidProvider fluidProvider = new TestFluidProvider(HbmFluids.DIESEL, 20);
        TestFluidReceiver fluidReceiver = new TestFluidReceiver(HbmFluids.DIESEL, 20);
        fluidBase.addProvider(fluidProvider);
        fluidBase.addReceiver(fluidReceiver);
        assertSame(fluidBase.providerEntries, fluidNet.providerEntries,
                "FluidNet inherits the sole legacy provider subscription map");
        assertSame(fluidBase.receiverEntries, fluidNet.receiverEntries,
                "FluidNet inherits the sole legacy receiver subscription map");
        assertEquals(20L, fluidNet.update(),
                "FluidNet transfer consumes subscriptions registered through its NodeNet base view");

        PlasmaNetwork receiving = new PlasmaNetwork();
        PlasmaNetwork absorbed = new PlasmaNetwork();
        HbmNodeNet<Object, Object, PlasmaNode> receivingBase = receiving;
        HbmNodeNet<Object, Object, PlasmaNode> absorbedBase = absorbed;
        Object receiver = new Object();
        Object provider = new Object();
        absorbedBase.addReceiver(receiver);
        absorbedBase.addProvider(provider);
        receiving.joinNetworks(absorbed);
        assertSame(receivingBase.receiverEntries, receiving.receiverEntries,
                "subscribable specialised net does not hide the inherited receiver map");
        assertSame(receivingBase.providerEntries, receiving.providerEntries,
                "subscribable specialised net does not hide the inherited provider map");
        assertTrue(receiving.isSubscribed(receiver) && receiving.isProvider(provider),
                "base-view subscriptions survive a specialised joinNetworks call");
        assertTrue(absorbed.receiverEntries.isEmpty() && absorbed.providerEntries.isEmpty(),
                "specialised joinNetworks destroys the absorbed single map pair");
        receiving.destroy();
        assertTrue(receivingBase.receiverEntries.isEmpty() && receivingBase.providerEntries.isEmpty(),
                "specialised destroy clears the inherited single map pair");
        helper.succeed();
    }

