    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosCoreLifecycle")
    public static void pneumaticTransferCapsEachAutocrafterDestinationAtOneItem(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos sourcePos = helper.absolutePos(new BlockPos(1, 2, 1));
        BlockPos destinationPos = helper.absolutePos(new BlockPos(4, 2, 1));
        level.setBlock(destinationPos, ModBlocks.MACHINE_AUTOCRAFTER.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(destinationPos) instanceof AutocrafterBlockEntity autocrafter)) {
            throw new AssertionError("legacy pneumatic autocrafter fixture did not create its block entity");
        }
        // Legacy ContainerAutocrafter writes the template inventory slot before
        // refreshing its matcher/template grid. updatePatternSlot is the modern
        // equivalent of that refresh half, not a replacement for the slot write.
        autocrafter.getItems().setStackInSlot(AutocrafterBlockEntity.SLOT_TEMPLATE_START,
                new ItemStack(Items.IRON_INGOT));
        autocrafter.updatePatternSlot(AutocrafterBlockEntity.SLOT_TEMPLATE_START,
                autocrafter.getItems().getStackInSlot(AutocrafterBlockEntity.SLOT_TEMPLATE_START));
        PneumaticItemAccess destination = PneumaticUtil.itemAccess(level, destinationPos, Direction.WEST)
                .orElseThrow(() -> new AssertionError("legacy autocrafter exposes a sided item capability"));
        assertEquals(1, destination.itemHardCap(),
                "legacy pneumatic destination marks autocrafter as a one-item transfer target");

        PneumaticNetwork network = new PneumaticNetwork();
        net.minecraftforge.items.ItemStackHandler source = new net.minecraftforge.items.ItemStackHandler(1);
        source.setStackInSlot(0, new ItemStack(Items.IRON_INGOT, 16));
        network.addReceiver(new PneumaticReceiver(destination.handler(), Direction.EAST,
                pneumaticEndpoint(destinationPos.west()), destination));
        assertTrue(network.send(new PneumaticItemAccess(source, sourcePos), pneumaticEndpoint(sourcePos),
                        PneumaticNetwork.SEND_FIRST, PneumaticNetwork.RECEIVE_ROBIN, 32, 0),
                "legacy pneumatic network inserts into the real autocrafter capability");
        assertEquals(15, source.getStackInSlot(0).getCount(),
                "legacy pneumatic autocrafter target accepts exactly one item per transfer");
        assertEquals(1, autocrafter.getItems().getStackInSlot(AutocrafterBlockEntity.SLOT_INPUT_START).getCount(),
                "legacy pneumatic autocrafter target receives one input item");
        level.removeBlock(destinationPos, false);
        helper.succeed();
    }

