    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosCoreLifecycle")
    public static void pneumaticTubeUsesLegacyRemoteAirSubscriptionWithoutCoreFluidNode(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos tubePos = helper.absolutePos(new BlockPos(3, 2, 3));
        BlockPos airPipePos = tubePos.north();
        BlockPos sourcePos = tubePos.east();
        PneumaticTubeBlockEntity tube = placePneumaticTube(level, tubePos);
        placeChest(level, sourcePos);
        setTubeInsertion(tube, Direction.EAST, "pneumatic AIR subscription insertion");
        level.setBlock(airPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(airPipePos) instanceof FluidPipeBlockEntity airPipe)) {
            throw new AssertionError("legacy pneumatic AIR fixture did not create its fluid duct");
        }
        airPipe.setFluidType(HbmFluids.AIR);
        FluidPipeBlockEntity.serverTick(level, airPipePos, level.getBlockState(airPipePos), airPipe);
        HbmFluidNodespace.tick(level);

        AtomicBoolean sawLegacyTenTickSubscription = new AtomicBoolean();
        helper.onEachTick(() -> {
            assertTrue(HbmFluidNodespace.getNode(level, tubePos, HbmFluids.AIR) == null,
                    "legacy pneumatic tube has no ordinary AIR Fluid Mk2 core node");
            if (Math.floorMod(level.getGameTime(), PneumaticTubeBlockEntity.RECEIVER_INTERVAL_TICKS) == 0L) {
                assertTrue(HbmFluidNodespace.getNetworkReceiverCount(level, airPipePos, HbmFluids.AIR) >= 1,
                        "legacy pneumatic compressor refreshes its remote AIR receiver on each ten-tick boundary");
                sawLegacyTenTickSubscription.set(true);
            }
        });
        helper.runAfterDelay(20, () -> {
            assertTrue(sawLegacyTenTickSubscription.get(),
                    "legacy pneumatic fixture observed a ten-tick AIR receiver refresh");
            level.removeBlock(airPipePos, false);
            level.removeBlock(sourcePos, false);
            level.removeBlock(tubePos, false);
            helper.succeed();
        });
    }

