    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosCoreLifecycle")
    public static void nodespaceReapKeepsLegacyDetachedNetworkState(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos pos = helper.absolutePos(new BlockPos(9, 2, 1));
        HbmEnergyNode node = new HbmEnergyNode(pos, Set.of());
        com.hbm.ntm.uninos.HbmNodespace<BlockPos, HbmEnergyNode, HbmNodeNet<Object, Object, HbmEnergyNode>> nodespace =
                new com.hbm.ntm.uninos.HbmNodespace<BlockPos, HbmEnergyNode, HbmNodeNet<Object, Object, HbmEnergyNode>>(
                        HbmEnergyNode::getPositions,
                        (configuredNode, connection) -> connection.pos(),
                        configuredNode -> HbmNodeNet::new,
                        HbmNodeNet::resetTrackers,
                        HbmNodeNet::update,
                        BlockPos::immutable);

        try {
            nodespace.createNode(level, node);
            nodespace.tick(level);
            HbmNodeNet<?, ?, ?> network = node.getNet();
            assertTrue(network != null && network.isValid(), "initial node owns a valid legacy PowerNet");

            node.expired = true;
            for (int tick = 0; tick <= 5 * 60 * 20; tick++) {
                nodespace.tick(level);
            }

            assertTrue(network.isValid(), "legacy timed reap does not destroy the detached network");
            assertSame(network, node.getNet(), "legacy timed reap retains the node's network reference");
            assertEquals(0, network.linkCount(), "legacy timed reap removes only expired node links");
            assertEquals(0, nodespace.getNetworkCount(level),
                    "legacy timed reap removes the now-empty network from the active nodespace set");
        } finally {
            nodespace.unloadLevel(level);
        }
        helper.succeed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosCoreLifecycle")
    public static void nodeNetInvalidateImmediatelyLeavesLegacyActiveSet(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos pos = helper.absolutePos(new BlockPos(11, 2, 1));
        HbmEnergyNode node = new HbmEnergyNode(pos, Set.of());
        com.hbm.ntm.uninos.HbmNodespace<BlockPos, HbmEnergyNode, HbmNodeNet<Object, Object, HbmEnergyNode>> nodespace =
                new com.hbm.ntm.uninos.HbmNodespace<BlockPos, HbmEnergyNode, HbmNodeNet<Object, Object, HbmEnergyNode>>(
                        HbmEnergyNode::getPositions,
                        (configuredNode, connection) -> connection.pos(),
                        configuredNode -> HbmNodeNet::new,
                        HbmNodeNet::resetTrackers,
                        HbmNodeNet::update,
                        BlockPos::immutable);

        try {
            nodespace.createNode(level, node);
            nodespace.tick(level);
            HbmNodeNet<?, ?, ?> network = node.getNet();
            assertTrue(network != null && network.isValid(), "initial node owns a valid legacy PowerNet");
            assertEquals(1, nodespace.getNetworkCount(level), "created network is active before invalidation");

            network.invalidate();

            assertTrue(!network.isValid(), "legacy invalidate changes only the network valid flag");
            assertSame(network, node.getNet(), "legacy invalidate retains the node's network reference");
            assertEquals(1, network.linkCount(), "legacy invalidate retains network links");
            assertEquals(0, nodespace.getNetworkCount(level),
                    "legacy invalidate immediately removes the network from active nodespace bookkeeping");
        } finally {
            nodespace.unloadLevel(level);
        }
        helper.succeed();
    }

