    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosCoreLifecycle")
    public static void nodespaceCreatesNetworksThroughItsSelectedLegacyProvider(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        int[] providerSelections = {0};
        int[] networkCreations = {0};
        com.hbm.ntm.uninos.HbmNodespace<BlockPos, HbmEnergyNode, HbmNodeNet<Object, Object, HbmEnergyNode>> nodespace =
                new com.hbm.ntm.uninos.HbmNodespace<BlockPos, HbmEnergyNode, HbmNodeNet<Object, Object, HbmEnergyNode>>(
                        HbmEnergyNode::getPositions,
                        (node, connection) -> connection.pos(),
                        node -> {
                            providerSelections[0]++;
                            return (com.hbm.ntm.uninos.HbmNetworkProvider<HbmEnergyNode, HbmNodeNet<Object, Object, HbmEnergyNode>>) () -> {
                                networkCreations[0]++;
                                return new HbmNodeNet<>();
                            };
                        },
                        network -> {
                        },
                        network -> {
                        },
                        BlockPos::immutable);
        BlockPos pos = helper.absolutePos(new BlockPos(1, 2, 1));
        HbmEnergyNode node = new HbmEnergyNode(pos, Set.of());

        try {
            nodespace.createNode(level, node);
            assertEquals(0, networkCreations[0],
                    "legacy nodespace createNode only registers the node before its update pass");

            nodespace.tick(level);
            assertEquals(1, providerSelections[0],
                    "nodespace selects a provider for the node during its legacy update pass");
            assertEquals(1, networkCreations[0],
                    "nodespace calls the selected provider's zero-argument creation method exactly once");
            assertTrue(node.hasValidNet(), "provider-created network joins the registered node");
        } finally {
            nodespace.unloadLevel(level);
        }
        helper.succeed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosCoreLifecycle")
    public static void legacyPowerNodeStandardConnectionsKeepTheirExplicitOrigin(GameTestHelper helper) {
        BlockPos nodePos = helper.absolutePos(new BlockPos(1, 2, 1));
        BlockPos origin = helper.absolutePos(new BlockPos(9, 6, 11));
        com.hbm.ntm.energy.Nodespace.PowerNode node = new com.hbm.ntm.energy.Nodespace.PowerNode(nodePos);
        node.clearRecentlyChanged();

        assertSame(node, node.setStandardConnections(origin.getX(), origin.getY(), origin.getZ()),
                "legacy PowerNode#setStandardConnections remains chainable");
        assertTrue(node.isRecentlyChanged(), "changing legacy PowerNode connections marks the node dirty");
        assertEquals(6, node.getConnectionPoints().size(),
                "legacy standard connections retain all six cardinal endpoints");
        assertTrue(node.getConnectionPoints().contains(new HbmNetworkNode.NodeConnection(origin.east(), Direction.EAST))
                        && node.getConnectionPoints().contains(new HbmNetworkNode.NodeConnection(origin.west(), Direction.WEST))
                        && node.getConnectionPoints().contains(new HbmNetworkNode.NodeConnection(origin.above(), Direction.UP))
                        && node.getConnectionPoints().contains(new HbmNetworkNode.NodeConnection(origin.below(), Direction.DOWN))
                        && node.getConnectionPoints().contains(new HbmNetworkNode.NodeConnection(origin.south(), Direction.SOUTH))
                        && node.getConnectionPoints().contains(new HbmNetworkNode.NodeConnection(origin.north(), Direction.NORTH)),
                "legacy standard connections use their explicit origin instead of the node's mapped position");
        assertTrue(node.connects(Direction.EAST) && node.connects(Direction.WEST)
                        && node.connects(Direction.UP) && node.connects(Direction.DOWN)
                        && node.connects(Direction.SOUTH) && node.connects(Direction.NORTH),
                "legacy PowerNode direction matching reads its current fluent connection state");
        helper.succeed();
    }

