        assertEquals(2, node.getConnectionPoints().size(),
                "legacy FluidNode retains the supplied number of explicit endpoints");
        assertTrue(node.getConnectionPoints().contains(new HbmNetworkNode.NodeConnection(origin.east(), Direction.EAST))
                        && node.getConnectionPoints().contains(new HbmNetworkNode.NodeConnection(origin.above(), Direction.UP)),
                "legacy FluidNode preserves remote DirPos coordinates instead of collapsing them onto its mapped position");
        assertTrue(node.connectsTo(new HbmNetworkNode.NodeConnection(origin, Direction.WEST)),
                "legacy FluidNode explicit endpoints drive actual reciprocal nodespace matching");
