    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosElectricFurnaceEnergyCadence")
    public static void electricFurnaceRetriesAdjacentEnergyOnlyOnLegacyFortiethTick(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        int ticksToFortiethBoundary = Math.floorMod(40 - (int) (level.getGameTime() % 40L), 40);
        if (ticksToFortiethBoundary == 0) {
            ticksToFortiethBoundary = 40;
        }
        // This delayed cadence sequence overlaps the default GameTest grid for
        // several ticks. Keep its physical Energy Mk2 line out of the shared
        // low-offset fixture band without changing the source 40-tick timing.
        BlockPos furnacePos = helper.absolutePos(new BlockPos(4, 2, 3_800_004));
        BlockPos portCablePos = furnacePos.west();
        BlockPos batteryPos = portCablePos.west(4);
        BlockPos firstCablePos = batteryPos.east();

        helper.startSequence()
                // GameTest callbacks run before that tick's block-entity pass.
                // Place at the exact old updateConnections boundary so the
                // initial dirty subscription cannot mask the cadence check.
                .thenIdle(ticksToFortiethBoundary)
                .thenExecute(() -> {
                    assertEquals(0L, level.getGameTime() % 40L,
                            "electric furnace fixture reaches the legacy 40-tick receiver boundary");
                    clearBox(level, furnacePos.offset(-8, -2, -4), furnacePos.offset(4, 4, 4));
                    forceLoadedChunks(level, batteryPos, furnacePos);
                    level.setBlock(furnacePos, ModBlocks.MACHINE_ELECTRIC_FURNACE_OFF.get().defaultBlockState(),
                            Block.UPDATE_ALL);
                    if (!(level.getBlockEntity(furnacePos) instanceof ElectricFurnaceBlockEntity furnace)) {
                        throw new AssertionError("electric furnace cadence fixture did not create its block entity");
                    }
                    furnace.getEnergyStorage().setPower(0L);
                    prepareOutputBatteryAndCableLine(level, batteryPos, firstCablePos, portCablePos, 100_000L);
                    // A GameTest callback is not a block-entity tick ordering
                    // guarantee. Run the real production ticker at the exact
                    // legacy boundary so its initial dirty subscription is
                    // consumed here, rather than on the following non-boundary
                    // tick after the replacement fixture has been installed.
                    ElectricFurnaceBlockEntity.serverTick(level, furnacePos,
                            level.getBlockState(furnacePos), furnace);
                    assertEquals(1, HbmEnergyNodespace.getNetworkReceiverCount(level, portCablePos),
                            "electric furnace initially subscribes on its legacy 40-tick receiver boundary");
                })
                // On the following non-boundary tick, replace the physical
                // conductor after its old receiver entry has been invalidated.
                .thenIdle(1)
                .thenExecute(() -> {
                    assertTrue(level.getGameTime() % 40L != 0L,
                            "electric furnace cable replacement runs outside the legacy 40-tick boundary");
                    level.removeBlock(portCablePos, false);
                    HbmEnergyNodespace.tick(level);
                    level.setBlock(portCablePos, ModBlocks.RED_CABLE.get().defaultBlockState(), Block.UPDATE_ALL);
                    refreshEnergyNodeAt(level, portCablePos);
                    HbmEnergyNodespace.tick(level);
                })
                .thenIdle(1)
                .thenExecute(() -> assertEquals(0, HbmEnergyNodespace.getNetworkReceiverCount(level, portCablePos),
                        "electric furnace does not retry its replaced Energy Mk2 receiver off the legacy 40-tick boundary"))
                // The preceding callbacks are at boundary+1 and boundary+2;
                // wait exactly to the next old connection tick.  GameTest
                // callbacks are not ordered relative to the natural BE pass,
                // so invoke the same production ticker in that exact boundary
                // callback before inspecting the restored subscription.
                .thenIdle(38)
                .thenExecute(() -> {
                    assertEquals(0L, level.getGameTime() % 40L,
                            "electric furnace reaches its next legacy 40-tick receiver boundary");
                    ElectricFurnaceBlockEntity furnace = (ElectricFurnaceBlockEntity) level.getBlockEntity(furnacePos);
                    assertTrue(furnace != null, "electric furnace remains present for the restored receiver transfer");
                    ElectricFurnaceBlockEntity.serverTick(level, furnacePos, level.getBlockState(furnacePos), furnace);
                    assertEquals(1, HbmEnergyNodespace.getNetworkReceiverCount(level, portCablePos),
                            "electric furnace restores its replaced adjacent Energy Mk2 receiver on the next 40-tick boundary");
                    MachineBatteryBlockEntity battery = requireMachineBattery(level, batteryPos);
                    furnace.getEnergyStorage().setPower(0L);
                    battery.setPower(100_000L);
                    tickMachineBattery(level, batteryPos, battery);
                    HbmPowerNet powerNet = HbmEnergyUtil.getPowerNet(level, portCablePos);
                    assertTrue(powerNet != null && powerNet.isValid(),
                            "electric furnace replacement conductor has a valid Energy Mk2 network");
                    assertTrue(powerNet.update() > 0L,
                            "electric furnace restored receiver transfers HE on its legacy 40-tick boundary");
                    assertTrue(furnace.getEnergyStorage().getPower() > 0L,
                            "electric furnace receives HE through its restored 40-tick Energy Mk2 subscription");
                    level.removeBlock(furnacePos, false);
                    for (int x = batteryPos.getX(); x <= portCablePos.getX(); x++) {
                        level.removeBlock(new BlockPos(x, portCablePos.getY(), portCablePos.getZ()), false);
                    }
                })
                .thenSucceed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosTwentyTickEnergyCadence")
    public static void compressorRetriesRemoteEnergyOnlyOnLegacyTwentiethTick(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        int ticksToBoundary = Math.floorMod(20 - (int) (level.getGameTime() % 20L), 20);
        if (ticksToBoundary == 0) {
            ticksToBoundary = 20;
        }
        BlockPos compressorPos = helper.absolutePos(new BlockPos(8, 2, 8));
        BlockPos portCablePos = compressorPos.west(2);
        BlockPos batteryPos = portCablePos.west(4);

        helper.startSequence()
                .thenIdle(ticksToBoundary - 1)
                .thenExecute(() -> {
                    assertEquals(19L, level.getGameTime() % 20L,
                            "compressor cadence fixture installs one tick before the legacy receiver boundary");
                    clearBox(level, compressorPos.offset(-8, -2, -4), compressorPos.offset(4, 4, 4));
                    forceLoadedChunks(level, batteryPos, compressorPos);
                    level.setBlock(compressorPos, ModBlocks.MACHINE_COMPRESSOR.get().defaultBlockState(),
                            Block.UPDATE_ALL);
                    CompressorBlockEntity compressor = requireBlockEntity(level, compressorPos,
                            CompressorBlockEntity.class, "compressor cadence fixture creates its machine core");
                    compressor.setPower(0L);
                    prepareOutputBatteryAndCableLine(level, batteryPos, batteryPos.east(), portCablePos, 100_000L);
                })
                .thenIdle(1)
                .thenExecute(() -> {
                    assertEquals(0L, level.getGameTime() % 20L,
                            "compressor cadence fixture reaches the initial legacy receiver boundary");
                    assertEquals(1, HbmEnergyNodespace.getNetworkReceiverCount(level, portCablePos),
                            "compressor subscribes its remote Energy Mk2 receiver on the legacy boundary");
                    level.removeBlock(portCablePos, false);
                    HbmEnergyNodespace.tick(level);
                    level.setBlock(portCablePos, ModBlocks.RED_CABLE.get().defaultBlockState(), Block.UPDATE_ALL);
                    refreshEnergyNodeAt(level, portCablePos);
                    HbmEnergyNodespace.tick(level);
                })
                .thenIdle(1)
                .thenExecute(() -> assertEquals(0, HbmEnergyNodespace.getNetworkReceiverCount(level, portCablePos),
                        "compressor does not retry its replaced receiver off the legacy twenty-tick boundary"))
                .thenIdle(19)
                .thenExecute(() -> {
                    assertEquals(0L, level.getGameTime() % 20L,
                            "compressor cadence fixture reaches the next legacy receiver boundary");
                    assertEquals(1, HbmEnergyNodespace.getNetworkReceiverCount(level, portCablePos),
                            "compressor restores its replaced remote Energy Mk2 receiver on the next boundary");
                    CompressorBlockEntity compressor = requireBlockEntity(level, compressorPos,
                            CompressorBlockEntity.class, "compressor remains present for the restored transfer");
                    MachineBatteryBlockEntity battery = requireMachineBattery(level, batteryPos);
                    compressor.setPower(0L);
                    battery.setPower(100_000L);
                    tickMachineBattery(level, batteryPos, battery);
                    HbmPowerNet powerNet = HbmEnergyUtil.getPowerNet(level, portCablePos);
                    assertTrue(powerNet != null && powerNet.isValid(),
                            "compressor replacement conductor has a valid Energy Mk2 network");
                    assertTrue(powerNet.update() > 0L,
                            "compressor restored receiver transfers HE on its legacy twenty-tick boundary");
                    assertTrue(compressor.getPower() > 0L,
                            "compressor receives HE through its restored twenty-tick subscription");
                    clearBox(level, compressorPos.offset(-8, -2, -4), compressorPos.offset(4, 4, 4));
                })
                .thenSucceed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosTwentyTickEnergyCadence")
    public static void electricHeaterAndExposureChamberRetryRemoteEnergyOnlyOnLegacyTwentiethTick(
            GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        int ticksToTwentiethBoundary = Math.floorMod(20 - (int) (level.getGameTime() % 20L), 20);
        if (ticksToTwentiethBoundary == 0) {
            ticksToTwentiethBoundary = 20;
        }
        BlockPos heaterPos = helper.absolutePos(new BlockPos(4, 2, 4));
        // Keep the east-growing battery/cable helper outside the core.  An
        // east-facing heater would put that helper's first conductor at the
        // core position itself; the legacy-facing contract is symmetric, so
        // exercise the west port instead.
        BlockPos heaterPortCablePos = heaterPos.west(3);
        BlockPos heaterBatteryPos = heaterPortCablePos.west(4);
        BlockPos chamberPos = helper.absolutePos(new BlockPos(36, 2, 4));
        BlockPos chamberPortCablePos = chamberPos.east(7).south(2);
        BlockPos chamberBatteryPos = chamberPortCablePos.west(4);

        helper.startSequence()
                // GameTest sequence callbacks run after the level's block-entity
                // ticker.  Install the real hosts and conductors one tick before
                // the legacy boundary so that the natural production ticker, not
                // a direct test invocation, owns the initial subscription.
                .thenIdle(ticksToTwentiethBoundary - 1)
                .thenExecute(() -> {
                    assertEquals(19L, level.getGameTime() % 20L,
                            "twenty-tick Energy Mk2 fixture installs hosts one tick before the legacy receiver boundary");
                    clearBox(level, heaterPos.offset(-8, -2, -4), chamberPos.offset(12, 4, 8));
                    forceLoadedChunks(level, heaterBatteryPos, chamberPos.offset(10, 0, 4));
                    level.setBlock(heaterPos, ModBlocks.HEATER_ELECTRIC.get().defaultBlockState()
                            .setValue(LegacyVisibleMultiblockMachineBlock.FACING, Direction.WEST), Block.UPDATE_ALL);
                    level.setBlock(chamberPos, ModBlocks.MACHINE_EXPOSURE_CHAMBER.get().defaultBlockState()
                            .setValue(HorizontalMachineBlock.FACING, Direction.SOUTH), Block.UPDATE_ALL);
                    ElectricHeaterBlockEntity heater = requireBlockEntity(level, heaterPos, ElectricHeaterBlockEntity.class,
                            "electric heater cadence fixture creates its machine core");
                    ExposureChamberBlockEntity chamber = requireBlockEntity(level, chamberPos,
                            ExposureChamberBlockEntity.class, "exposure chamber cadence fixture creates its machine core");
                    heater.toggleSetting();
                    heater.getEnergyStorage().setPower(0L);
                    chamber.getEnergyStorage().setPower(0L);
                    prepareOutputBatteryAndCableLine(level, heaterBatteryPos, heaterBatteryPos.east(), heaterPortCablePos,
                            100_000L);
                    prepareOutputBatteryAndCableLine(level, chamberBatteryPos, chamberBatteryPos.east(), chamberPortCablePos,
                            100_000L);
                })
                .thenIdle(1)
                .thenExecute(() -> {
                    assertEquals(0L, level.getGameTime() % 20L,
                            "twenty-tick Energy Mk2 fixture reaches the legacy receiver boundary after its natural ticker");
                    assertEquals(1, HbmEnergyNodespace.getNetworkReceiverCount(level, heaterPortCablePos),
                            "electric heater subscribes at its legacy twenty-tick boundary");
                    assertEquals(1, HbmEnergyNodespace.getNetworkReceiverCount(level, chamberPortCablePos),
                            "exposure chamber subscribes at its legacy twenty-tick boundary");
                    for (BlockPos portCablePos : List.of(heaterPortCablePos, chamberPortCablePos)) {
                        level.removeBlock(portCablePos, false);
                        HbmEnergyNodespace.tick(level);
                        level.setBlock(portCablePos, ModBlocks.RED_CABLE.get().defaultBlockState(), Block.UPDATE_ALL);
                        refreshEnergyNodeAt(level, portCablePos);
                        HbmEnergyNodespace.tick(level);
                    }
                })
                .thenIdle(1)
                .thenExecute(() -> {
                    assertEquals(0, HbmEnergyNodespace.getNetworkReceiverCount(level, heaterPortCablePos),
                            "electric heater does not retry its replaced receiver outside the legacy twenty-tick boundary");
                    assertEquals(0, HbmEnergyNodespace.getNetworkReceiverCount(level, chamberPortCablePos),
                            "exposure chamber does not retry its replaced receiver outside the legacy twenty-tick boundary");
                })
                .thenIdle(19)
                .thenExecute(() -> assertEquals(0L, level.getGameTime() % 20L,
                        "twenty-tick Energy Mk2 fixture reaches the next legacy receiver boundary after its natural ticker"))
                .thenExecute(() -> {
                    assertTwentyTickEnergyReceiverRestores(level, heaterPos, heaterBatteryPos, heaterPortCablePos,
                            "electric heater");
                    assertTwentyTickEnergyReceiverRestores(level, chamberPos, chamberBatteryPos, chamberPortCablePos,
                            "exposure chamber");
                })
                .thenSucceed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosEveryTickEnergyCadence")
    public static void legacyEveryTickMachinesRetryAdjacentEnergyOnNextTick(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos[] machinePositions = {
                helper.absolutePos(new BlockPos(4, 2, 4)),
                helper.absolutePos(new BlockPos(28, 2, 4)),
                helper.absolutePos(new BlockPos(52, 2, 4))
        };
        BlockPos[] portCablePositions = {
                machinePositions[0].west(), machinePositions[1].west(), machinePositions[2].west()
        };
        BlockPos[] batteryPositions = {
                portCablePositions[0].west(4), portCablePositions[1].west(4), portCablePositions[2].west(4)
        };
        Block[] machineBlocks = {
                ModBlocks.MACHINE_EPRESS.get(), ModBlocks.MACHINE_AUTOCRAFTER.get(), ModBlocks.MACHINE_SHREDDER.get()
        };
        String[] machineNames = { "electric press", "autocrafter", "shredder" };

        helper.startSequence()
                .thenExecute(() -> {
                    for (int index = 0; index < machinePositions.length; index++) {
                        BlockPos machinePos = machinePositions[index];
                        BlockPos batteryPos = batteryPositions[index];
                        BlockPos portCablePos = portCablePositions[index];
                        clearBox(level, machinePos.offset(-8, -2, -4), machinePos.offset(4, 4, 4));
                        forceLoadedChunks(level, batteryPos, machinePos);
                        level.setBlock(machinePos, machineBlocks[index].defaultBlockState(), Block.UPDATE_ALL);
                        if (!(level.getBlockEntity(machinePos) instanceof HbmEnergyBlockEntity machine)) {
                            throw new AssertionError(machineNames[index] + " cadence fixture did not create an energy block entity");
                        }
                        machine.getEnergyStorage().setPower(0L);
                        prepareOutputBatteryAndCableLine(level, batteryPos, batteryPos.east(), portCablePos, 100_000L);
                    }
                })
                .thenIdle(1)
                .thenExecute(() -> {
                    for (int index = 0; index < portCablePositions.length; index++) {
                        BlockPos portCablePos = portCablePositions[index];
                        level.removeBlock(portCablePos, false);
                        HbmEnergyNodespace.tick(level);
                        level.setBlock(portCablePos, ModBlocks.RED_CABLE.get().defaultBlockState(), Block.UPDATE_ALL);
                        refreshEnergyNodeAt(level, portCablePos);
                        HbmEnergyNodespace.tick(level);
                    }
                })
                .thenIdle(1)
                .thenExecute(() -> {
                    for (int index = 0; index < machinePositions.length; index++) {
                        BlockPos machinePos = machinePositions[index];
                        BlockPos portCablePos = portCablePositions[index];
                        assertEquals(1, HbmEnergyNodespace.getNetworkReceiverCount(level, portCablePos),
                                machineNames[index] + " retries its replaced adjacent Energy Mk2 receiver on the next legacy tick");
                        HbmEnergyBlockEntity machine = (HbmEnergyBlockEntity) level.getBlockEntity(machinePos);
                        MachineBatteryBlockEntity battery = requireMachineBattery(level, batteryPositions[index]);
                        assertTrue(machine != null, machineNames[index] + " remains present for the restored receiver transfer");
                        machine.getEnergyStorage().setPower(0L);
                        battery.setPower(100_000L);
                        tickMachineBattery(level, batteryPositions[index], battery);
                        HbmPowerNet powerNet = HbmEnergyUtil.getPowerNet(level, portCablePos);
                        assertTrue(powerNet != null && powerNet.isValid(),
                                machineNames[index] + " replacement conductor has a valid Energy Mk2 network");
                        assertTrue(powerNet.update() > 0L,
                                machineNames[index] + " restored receiver transfers HE on the next legacy tick");
                        assertTrue(machine.getEnergyStorage().getPower() > 0L,
                                machineNames[index] + " receives HE through its restored every-tick Energy Mk2 subscription");
                    }
                })
                .thenSucceed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosEveryTickEnergyCadence")
    public static void legacyUtilityMachinesRetryAdjacentEnergyOnNextTick(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos[] machinePositions = {
                helper.absolutePos(new BlockPos(4, 2, 12)),
                helper.absolutePos(new BlockPos(28, 2, 12)),
                helper.absolutePos(new BlockPos(52, 2, 12)),
                helper.absolutePos(new BlockPos(76, 2, 12)),
                helper.absolutePos(new BlockPos(100, 2, 12))
        };
        BlockPos[] portCablePositions = {
                machinePositions[0].west(), machinePositions[1].west(), machinePositions[2].west(),
                machinePositions[3].west(), machinePositions[4].west()
        };
        BlockPos[] batteryPositions = {
                portCablePositions[0].west(4), portCablePositions[1].west(4), portCablePositions[2].west(4),
                portCablePositions[3].west(4), portCablePositions[4].west(4)
        };
        Block[] machineBlocks = {
                ModBlocks.TESLA.get(), ModBlocks.MACHINE_TELEPORTER.get(), ModBlocks.RADIOBOX.get(),
                ModBlocks.DFC_STABILIZER.get(), ModBlocks.MACHINE_FORCEFIELD.get()
        };
        String[] machineNames = { "tesla", "teleporter", "radiobox", "dfc stabilizer", "force field" };

        helper.startSequence()
                .thenExecute(() -> {
                    for (int index = 0; index < machinePositions.length; index++) {
                        BlockPos machinePos = machinePositions[index];
                        BlockPos batteryPos = batteryPositions[index];
                        BlockPos portCablePos = portCablePositions[index];
                        clearBox(level, machinePos.offset(-8, -2, -4), machinePos.offset(4, 4, 4));
                        forceLoadedChunks(level, batteryPos, machinePos);
                        level.setBlock(machinePos, machineBlocks[index].defaultBlockState(), Block.UPDATE_ALL);
                        if (!(level.getBlockEntity(machinePos) instanceof HbmEnergyBlockEntity machine)) {
                            throw new AssertionError(machineNames[index] + " cadence fixture did not create an energy block entity");
                        }
                        machine.getEnergyStorage().setPower(0L);
                        prepareOutputBatteryAndCableLine(level, batteryPos, batteryPos.east(), portCablePos, 100_000L);
                    }
                })
                .thenIdle(1)
                .thenExecute(() -> {
                    for (BlockPos portCablePos : portCablePositions) {
                        level.removeBlock(portCablePos, false);
                        HbmEnergyNodespace.tick(level);
                        level.setBlock(portCablePos, ModBlocks.RED_CABLE.get().defaultBlockState(), Block.UPDATE_ALL);
                        refreshEnergyNodeAt(level, portCablePos);
                        HbmEnergyNodespace.tick(level);
                    }
                })
                .thenIdle(1)
                .thenExecute(() -> {
                    for (int index = 0; index < machinePositions.length; index++) {
                        BlockPos machinePos = machinePositions[index];
                        BlockPos portCablePos = portCablePositions[index];
                        assertEquals(1, HbmEnergyNodespace.getNetworkReceiverCount(level, portCablePos),
                                machineNames[index] + " retries its replaced adjacent Energy Mk2 receiver on the next legacy tick");
                        HbmEnergyBlockEntity machine = (HbmEnergyBlockEntity) level.getBlockEntity(machinePos);
                        MachineBatteryBlockEntity battery = requireMachineBattery(level, batteryPositions[index]);
                        assertTrue(machine != null, machineNames[index] + " remains present for the restored receiver transfer");
                        machine.getEnergyStorage().setPower(0L);
                        battery.setPower(100_000L);
                        tickMachineBattery(level, batteryPositions[index], battery);
                        HbmPowerNet powerNet = HbmEnergyUtil.getPowerNet(level, portCablePos);
                        assertTrue(powerNet != null && powerNet.isValid(),
                                machineNames[index] + " replacement conductor has a valid Energy Mk2 network");
                        assertTrue(powerNet.update() > 0L,
                                machineNames[index] + " restored receiver transfers HE on the next legacy tick");
                        assertTrue(machine.getEnergyStorage().getPower() > 0L,
                                machineNames[index] + " receives HE through its restored every-tick Energy Mk2 subscription");
                    }
                    ForceFieldBlockEntity forceField = (ForceFieldBlockEntity) level.getBlockEntity(machinePositions[4]);
                    assertTrue(forceField != null && !forceField.canConnectEnergy(Direction.UP),
                            "force field retains the legacy no-top Energy Mk2 side while retrying every tick");
                })
                .thenSucceed();
    }

