    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosEveryTickEnergyCadence")
    public static void assemblyAndChemicalHostsRetryRemoteEnergyEveryLegacyTick(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos anchor = helper.absolutePos(new BlockPos(4, 2, 96));
        BlockPos assemblyPos = anchor;
        BlockPos plantPos = anchor.east(32);
        BlockPos assemblyFactoryPos = anchor.east(64);
        BlockPos chemicalFactoryPos = anchor.east(96);
        clearBox(level, anchor.offset(-12, -2, -12), chemicalFactoryPos.offset(12, 6, 12));

        level.setBlock(assemblyPos, ModBlocks.MACHINE_ASSEMBLY_MACHINE.get().defaultBlockState(), Block.UPDATE_ALL);
        level.setBlock(plantPos, ModBlocks.MACHINE_CHEMICAL_PLANT.get().defaultBlockState(), Block.UPDATE_ALL);
        level.setBlock(assemblyFactoryPos, ModBlocks.MACHINE_ASSEMBLY_FACTORY.get().defaultBlockState(), Block.UPDATE_ALL);
        level.setBlock(chemicalFactoryPos, ModBlocks.MACHINE_CHEMICAL_FACTORY.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(assemblyPos) instanceof AssemblyMachineBlockEntity assembly)
                || !(level.getBlockEntity(plantPos) instanceof ChemicalPlantBlockEntity plant)
                || !(level.getBlockEntity(assemblyFactoryPos) instanceof AssemblyFactoryBlockEntity assemblyFactory)
                || !(level.getBlockEntity(chemicalFactoryPos) instanceof ChemicalFactoryBlockEntity chemicalFactory)) {
            throw new AssertionError("every-tick Energy Mk2 cadence fixture did not create every source-backed host");
        }

        HbmEnergyUtil.EnergyPort floorRingPort = LegacyMultiblockPorts.xrFloorRingEnergyPorts(2).get(0);
        Direction assemblyFactoryFacing = level.getBlockState(assemblyFactoryPos)
                .getValue(LegacyVisibleMultiblockMachineBlock.FACING);
        Direction chemicalFactoryFacing = level.getBlockState(chemicalFactoryPos)
                .getValue(LegacyVisibleMultiblockMachineBlock.FACING);
        HbmEnergyUtil.EnergyPort assemblyFactoryPort = LegacyMultiblockPorts.combineEnergyPorts(
                LegacyMultiblockPorts.factoryRecipeEnergyPorts(assemblyFactoryFacing, false),
                LegacyMultiblockPorts.factoryCoolingEnergyPorts(assemblyFactoryFacing)).get(0);
        HbmEnergyUtil.EnergyPort chemicalFactoryPort = LegacyMultiblockPorts.combineEnergyPorts(
                LegacyMultiblockPorts.factoryRecipeEnergyPorts(chemicalFactoryFacing, true),
                LegacyMultiblockPorts.factoryCoolingEnergyPorts(chemicalFactoryFacing)).get(0);

        assertEveryTickRemoteEnergyReceiverRestores(level, assemblyPos, floorRingPort.conductorPos(assemblyPos), assembly,
                () -> AssemblyMachineBlockEntity.serverTick(level, assemblyPos, level.getBlockState(assemblyPos), assembly),
                "assembly machine");
        assertEveryTickRemoteEnergyReceiverRestores(level, plantPos, floorRingPort.conductorPos(plantPos), plant,
                () -> ChemicalPlantBlockEntity.serverTick(level, plantPos, level.getBlockState(plantPos), plant),
                "chemical plant");
        assertEveryTickRemoteEnergyReceiverRestores(level, assemblyFactoryPos,
                assemblyFactoryPort.conductorPos(assemblyFactoryPos), assemblyFactory,
                () -> AssemblyFactoryBlockEntity.serverTick(level, assemblyFactoryPos,
                        level.getBlockState(assemblyFactoryPos), assemblyFactory),
                "assembly factory");
        assertEveryTickRemoteEnergyReceiverRestores(level, chemicalFactoryPos,
                chemicalFactoryPort.conductorPos(chemicalFactoryPos), chemicalFactory,
                () -> ChemicalFactoryBlockEntity.serverTick(level, chemicalFactoryPos,
                        level.getBlockState(chemicalFactoryPos), chemicalFactory),
                "chemical factory");
        helper.succeed();
    }

