    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "energyMk2RemotePortsTurretFritz")
    public static void fritzTurretFluidPortReceivesDieselAcrossFluidDuct(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos anchor = helper.absolutePos(new BlockPos(1, 2, 1));
        int chunkStartX = anchor.getX() & ~15;
        int chunkStartZ = anchor.getZ() & ~15;
        BlockPos sourcePipePos = new BlockPos(chunkStartX + 13, anchor.getY(), chunkStartZ + 140);
        BlockPos portPipePos = new BlockPos(chunkStartX + 17, anchor.getY(), chunkStartZ + 140);
        BlockPos turretPos = portPipePos.east(2);
        forceLoadedChunks(level, sourcePipePos, turretPos);
        BlockState turretState = ModBlocks.TURRET_FRITZ.get()
                .defaultBlockState()
                .setValue(HorizontalMachineBlock.FACING, Direction.SOUTH);
        level.removeBlock(turretPos, false);
        level.setBlock(turretPos, turretState, Block.UPDATE_ALL);
        if (!(level.getBlockEntity(turretPos) instanceof TurretFritzBlockEntity turret)) {
            throw new AssertionError("No turret_fritz block entity at " + turretPos);
        }

        prepareDieselFluidPipeLine(level, sourcePipePos, portPipePos);
        List<HbmFluidUtil.FluidPort> ports = fritzFluidPorts(turret);
        HbmFluidUtil.PortSetSnapshot portSnapshot =
                HbmFluidUtil.inspectPorts(level, turretPos, ports, HbmFluids.DIESEL);
        assertEquals(8, portSnapshot.totalPorts(),
                "turret_fritz exposes legacy remote fluid receiver ports");
        assertTrue(portSnapshot.networkedPorts() >= 1,
                "turret_fritz remote fluid port sees the diesel fluid_duct_neo network: " + portSnapshot);

        assertTrue(turret.getCapability(ForgeCapabilities.FLUID_HANDLER, Direction.EAST).resolve().isPresent(),
                "turret_fritz accepts Forge fluid capability from horizontal sides");
        assertTrue(turret.getCapability(ForgeCapabilities.FLUID_HANDLER, Direction.UP).resolve().isEmpty(),
                "turret_fritz rejects Forge fluid capability from the top like legacy canConnect");
        assertTrue(turret.getCapability(ForgeCapabilities.FLUID_HANDLER, Direction.DOWN).resolve().isEmpty(),
                "turret_fritz rejects Forge fluid capability from the bottom like legacy canConnect");

        TurretBlockEntityBase.serverTick(level, turretPos, turretState, turret);
        assertTrue(HbmFluidNodespace.getNode(level, turretPos, HbmFluids.DIESEL) == null,
                "turret_fritz keeps legacy remote diesel ports without an ordinary Fluid Mk2 core node");
        HbmFluidUtil.PortSnapshot receiverPort =
                requireSubscribedFluidPort(level, turretPos, ports, HbmFluids.DIESEL);

        level.removeBlock(portPipePos, false);
        level.setBlock(portPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(portPipePos) instanceof FluidPipeBlockEntity replacementPipe)) {
            throw new AssertionError("turret_fritz diesel-port replacement did not create fluid_duct_neo");
        }
        replacementPipe.setFluidType(HbmFluids.DIESEL);
        refreshFluidNodeAt(level, portPipePos);
        HbmFluidNodespace.forceRebuild(level);
        HbmFluidNodespace.tick(level);
        TurretBlockEntityBase.serverTick(level, turretPos, turretState, turret);
        receiverPort = requireSubscribedFluidPort(level, turretPos, ports, HbmFluids.DIESEL);

        TestFluidProvider provider = new TestFluidProvider(HbmFluids.DIESEL, 1_000);
        assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, receiverPort.connectorPos(),
                receiverPort.connectorSide(),
                HbmFluids.DIESEL, provider),
                "test diesel provider subscribed to the fluid_duct_neo port network");

        assertTrue(HbmFluidNodespace.getNetworkReceiverCount(level, receiverPort.connectorPos(),
                HbmFluids.DIESEL) >= 1,
                "diesel network has turret_fritz receiver entry");
        assertTrue(HbmFluidNodespace.getNetworkProviderCount(level, receiverPort.connectorPos(),
                HbmFluids.DIESEL) >= 1,
                "diesel network has provider entry");
        HbmFluidNet fluidNet = HbmFluidNodespace.getNode(level, receiverPort.connectorPos(),
                HbmFluids.DIESEL).getFluidNet();
        HbmFluidNet.DebugSnapshot beforeUpdate = fluidNet.createDebugSnapshot();
        long transferred = fluidNet.update();
        HbmFluidNet.DebugSnapshot afterUpdate = fluidNet.createDebugSnapshot();

        assertTrue(transferred > 0L,
                "diesel fluid net transferred mB; before=" + beforeUpdate + ", after=" + afterUpdate);
        int received = turret.getTank().getFill();
        assertTrue(received > 0,
                "turret_fritz received diesel across the real fluid_duct_neo network");
        assertTrue(provider.getStoredFluid() < 1_000,
                "test diesel provider drained into the fluid_duct_neo network");
        assertTrue(HbmFluidNodespace.getNetworkFluidTracker(level, receiverPort.connectorPos(),
                HbmFluids.DIESEL) >= transferred,
                "diesel network tracked the remote-port transfer");
        helper.succeed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "energyMk2CommandDiagnostics")
    public static void energyCommandsObserveRemotePortNetworks(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos anchor = helper.absolutePos(new BlockPos(1, 2, 1));
        int chunkStartX = anchor.getX() & ~15;
        int chunkStartZ = anchor.getZ() & ~15;
        BlockPos batteryPos = new BlockPos(chunkStartX + 13, anchor.getY(), chunkStartZ + 180);
        BlockPos firstCablePos = batteryPos.east();
        BlockPos portCablePos = new BlockPos(chunkStartX + 17, anchor.getY(), chunkStartZ + 180);
        BlockPos launchPadPos = portCablePos.west(2).south();
        long startingPower = 100_000L;
        forceLoadedChunks(level, batteryPos, launchPadPos);
        level.removeBlock(launchPadPos, false);
        level.setBlock(launchPadPos, ModBlocks.LAUNCH_PAD.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(launchPadPos) instanceof LaunchPadBlockEntity launchPad)) {
            throw new AssertionError("No launch_pad block entity at " + launchPadPos);
        }

        prepareOutputBatteryAndCableLine(level, batteryPos, firstCablePos, portCablePos, startingPower);
        assertEnergyAndFluidRemoteReceiverReceivesPower(level, batteryPos, portCablePos,
                launchPad, "launch_pad command diagnostics", 8, startingPower);

        HbmEnergyNodespace.Diagnostics diagnostics = HbmEnergyNodespace.getDiagnostics(level);
        assertTrue(diagnostics.uniqueNodes() > 0, "command diagnostic fixture has energy nodes");
        assertTrue(diagnostics.networks() > 0, "command diagnostic fixture has energy networks");

        HbmEnergyNodespace.NetworkDebugSnapshot networkSnapshot =
                HbmEnergyNodespace.getNetworkDebugSnapshot(level, portCablePos);
        assertTrue(networkSnapshot.nodePresent(), "command diagnostic port cable has a node");
        assertTrue(networkSnapshot.networkPresent(), "command diagnostic port cable has a network");
        int expectedLinks = networkSnapshot.network().links();
        int expectedChunkNodes = HbmEnergyNodespace
                .getChunkDiagnostics(level, new ChunkPos(portCablePos))
                .uniqueNodes();

        assertCommandResult(level, anchor, "hbm energy nodespace", diagnostics.uniqueNodes());
        assertCommandResult(level, anchor, "hbm energy network " + commandPos(portCablePos), expectedLinks);
        assertCommandResult(level, anchor, "hbm energy node " + commandPos(portCablePos), expectedLinks);
        assertCommandResult(level, anchor, "hbm energy chunk " + commandPos(portCablePos), expectedChunkNodes);
        assertCommandResult(level, anchor,
                "hbm energy port " + commandPos(launchPadPos) + " 2 0 -1 east", expectedLinks);
        assertCommandResult(level, anchor, "hbm energy ports " + commandPos(launchPadPos), 1);

        assertCommandVisibleMessage(level, anchor, "hbm energy nodespace", diagnostics.uniqueNodes(),
                "Energy nodespace:", "nodes=", "debugParticles=");
        assertCommandVisibleMessage(level, anchor, "hbm energy network " + commandPos(portCablePos), expectedLinks,
                "Energy network at " + portCablePos.toShortString(), "providers=", "lastTransfer=");
        assertCommandVisibleMessage(level, anchor, "hbm energy node " + commandPos(portCablePos), expectedLinks,
                "Energy network at " + portCablePos.toShortString(), "nodeConnections=", "receivers=");
        assertCommandVisibleMessage(level, anchor, "hbm energy chunk " + commandPos(portCablePos), expectedChunkNodes,
                "Energy chunk [" + new ChunkPos(portCablePos).x + ", " + new ChunkPos(portCablePos).z + "]",
                "positions=", "receivers=");
        assertCommandVisibleMessage(level, anchor,
                "hbm energy port " + commandPos(launchPadPos) + " 2 0 -1 east", expectedLinks,
                "Energy port from " + launchPadPos.toShortString(), "conductor=", "lastTransfer=");
        assertCommandVisibleMessage(level, anchor, "hbm energy ports " + commandPos(launchPadPos), 1,
                "Energy ports at " + launchPadPos.toShortString(), "total=8", "networked=");
        BlockPos missingNodePos = anchor.above(4);
        assertCommandVisibleMessage(level, anchor, "hbm energy network " + commandPos(missingNodePos), 0,
                "No HBM energy node at " + missingNodePos.toShortString());
        helper.succeed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "energyMk2CommandDiagnostics")
    public static void legacyReapNetworksCommandClearsEveryModernNodespace(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        HbmEnergyNodespace.unloadLevel(level);
        HbmFluidNodespace.unloadLevel(level);
        HbmUninosNodespaces.unloadLevel(level);
        try {
            BlockPos anchor = helper.absolutePos(new BlockPos(1, 2, 1));
            HbmEnergyNode energyNode = new HbmEnergyNode(anchor, Set.of());
            HbmFluidNode fluidNode = new HbmFluidNode(anchor.east(), HbmFluids.DIESEL, Set.of());
            PlasmaNode plasmaNode = new PlasmaNode(anchor.south());
            KlystronNode klystronNode = new KlystronNode(anchor.west());
            FoundryNode foundryNode = new FoundryNode(anchor.north());
            RebarNode rebarNode = new RebarNode(anchor.above());
            PneumaticNode pneumaticNode = new PneumaticNode(anchor.below());
            BlockPos pipePos = anchor.above(2);
            level.setBlock(pipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(pipePos) instanceof FluidPipeBlockEntity pipe)) {
                throw new AssertionError("legacy reap fixture did not create its real Fluid Pipe host");
            }
            pipe.setFluidType(HbmFluids.DIESEL);
            HbmFluidNode pipeNode = pipe.getFluidNode();
            assertTrue(pipeNode != null && !pipeNode.isExpired(),
                    "real Fluid Pipe creates its typed node before legacy reap");

            HbmEnergyNodespace.createNode(level, energyNode);
            HbmFluidNodespace.createNode(level, fluidNode);
            PlasmaNodespace.createNode(level, plasmaNode);
            KlystronNodespace.createNode(level, klystronNode);
            FoundryNodespace.createNode(level, foundryNode);
            RebarNodespace.createNode(level, rebarNode);
            PneumaticNodespace.createNode(level, pneumaticNode);

            // Reap observes established legacy networks; freshly created nodes are
            // intentionally netless until the next server START update.
            HbmEnergyNodespace.tick(level);
            HbmFluidNodespace.tick(level);
            HbmUninosNodespaces.tick(level);

            assertEquals(1, HbmEnergyNodespace.getDiagnostics(level).uniqueNodes(),
                    "legacy reap fixture has an energy node");
            assertEquals(2, HbmFluidNodespace.getDiagnostics(level).uniqueNodes(),
                    "legacy reap fixture has its direct and real-pipe fluid nodes");
            assertEquals(5, HbmUninosDiagnostics.totals(level).uniqueNodes(),
                    "legacy reap fixture has every aggregate UNINOS node type");

            // The four legacy specialised NodeNet implementations all have an
            // empty update(). Their subscriber timestamps therefore remain until
            // explicit removal, a merge, or network destruction.
            long staleSubscriptionTime = System.currentTimeMillis() - 5_000L;
            Object plasmaReceiver = new Object();
            Object plasmaProvider = new Object();
            PlasmaNetwork plasmaNetwork = plasmaNode.getPlasmaNet();
            assertTrue(plasmaNetwork != null, "legacy reap fixture establishes the Plasma network");
            plasmaNetwork.addReceiver(plasmaReceiver);
            plasmaNetwork.addProvider(plasmaProvider);
            plasmaNetwork.receiverEntries.replaceAll((subscriber, lastSeen) -> staleSubscriptionTime);
            plasmaNetwork.providerEntries.replaceAll((subscriber, lastSeen) -> staleSubscriptionTime);

            Object klystronReceiver = new Object();
            Object klystronProvider = new Object();
            KlystronNetwork klystronNetwork = klystronNode.getKlystronNet();
            assertTrue(klystronNetwork != null, "legacy reap fixture establishes the Klystron network");
            klystronNetwork.addReceiver(klystronReceiver);
            klystronNetwork.addProvider(klystronProvider);
            klystronNetwork.receiverEntries.replaceAll((subscriber, lastSeen) -> staleSubscriptionTime);
            klystronNetwork.providerEntries.replaceAll((subscriber, lastSeen) -> staleSubscriptionTime);

            Object foundryReceiver = new Object();
            Object foundryProvider = new Object();
            FoundryNetwork foundryNetwork = foundryNode.getFoundryNet();
            assertTrue(foundryNetwork != null, "legacy reap fixture establishes the Foundry network");
            foundryNetwork.addReceiver(foundryReceiver);
            foundryNetwork.addProvider(foundryProvider);
            foundryNetwork.receiverEntries.replaceAll((subscriber, lastSeen) -> staleSubscriptionTime);
            foundryNetwork.providerEntries.replaceAll((subscriber, lastSeen) -> staleSubscriptionTime);

            Object rebarReceiver = new Object();
            Object rebarProvider = new Object();
            RebarNetwork rebarNetwork = rebarNode.getRebarNet();
            assertTrue(rebarNetwork != null, "legacy reap fixture establishes the Rebar network");
            rebarNetwork.addReceiver(rebarReceiver);
            rebarNetwork.addProvider(rebarProvider);
            rebarNetwork.receiverEntries.replaceAll((subscriber, lastSeen) -> staleSubscriptionTime);
            rebarNetwork.providerEntries.replaceAll((subscriber, lastSeen) -> staleSubscriptionTime);

            HbmUninosNodespaces.tick(level);
            assertTrue(plasmaNetwork.isSubscribed(plasmaReceiver) && plasmaNetwork.isProvider(plasmaProvider),
                    "PlasmaNetwork keeps stale subscriptions because legacy update is empty");
            assertTrue(klystronNetwork.isSubscribed(klystronReceiver) && klystronNetwork.isProvider(klystronProvider),
                    "KlystronNetwork keeps stale subscriptions because legacy update is empty");
            assertTrue(foundryNetwork.isSubscribed(foundryReceiver) && foundryNetwork.isProvider(foundryProvider),
                    "FoundryNetwork keeps stale subscriptions because legacy update is empty");
            assertTrue(rebarNetwork.isSubscribed(rebarReceiver) && rebarNetwork.isProvider(rebarProvider),
                    "RebarNetwork keeps stale subscriptions because legacy update is empty");

            assertCommandVisibleMessage(level, anchor, "ntmreapnetworks", 8,
                    "UNINOS nodespaces cleared: nodes=8 networks=8");

            assertTrue(energyNode.isExpired(), "legacy reap expires the energy node");
            assertTrue(fluidNode.isExpired(), "legacy reap expires the fluid node");
            assertTrue(plasmaNode.isExpired(), "legacy reap expires the plasma node");
            assertTrue(klystronNode.isExpired(), "legacy reap expires the klystron node");
            assertTrue(foundryNode.isExpired(), "legacy reap expires the foundry node");
            assertTrue(rebarNode.isExpired(), "legacy reap expires the rebar node");
            assertTrue(pneumaticNode.isExpired(), "legacy reap expires the pneumatic node");
            assertTrue(pipeNode.isExpired(), "legacy reap expires the real Fluid Pipe node");
            assertEquals(0, HbmEnergyNodespace.getDiagnostics(level).uniqueNodes(),
                    "legacy reap clears energy nodes");
            assertEquals(0, HbmFluidNodespace.getDiagnostics(level).uniqueNodes(),
                    "legacy reap clears fluid nodes");
            assertEquals(0, HbmUninosDiagnostics.totals(level).uniqueNodes(),
                    "legacy reap clears every aggregate UNINOS nodespace");

            BlockState pipeState = level.getBlockState(pipePos);
            var pipeTicker = ((FluidPipeBlock) pipeState.getBlock()).getTicker(level, pipeState,
                    ModBlockEntities.FLUID_PIPE.get());
            assertTrue(pipeTicker != null, "real Fluid Pipe registers its legacy server-tick recovery hook");
            pipeTicker.tick(level, pipePos, pipeState, pipe);
            HbmFluidNode restoredPipeNode = pipe.getFluidNode();
            assertTrue(restoredPipeNode != null && !restoredPipeNode.isExpired() && restoredPipeNode != pipeNode,
                    "real Fluid Pipe recreates a new typed node on its next server tick after legacy reap");
            assertSame(restoredPipeNode, HbmFluidNodespace.getNode(level, pipePos, HbmFluids.DIESEL),
                    "real Fluid Pipe restores its typed nodespace mapping after legacy reap");
            HbmFluidNodespace.tick(level);
            assertTrue(restoredPipeNode.getFluidNet() != null,
                    "restored Fluid Pipe node joins its network on the following legacy START update");

            HbmEnergyNodespace.createNode(level, new HbmEnergyNode(anchor, Set.of()));
            assertEquals(1, HbmEnergyNodespace.getDiagnostics(level).uniqueNodes(),
                    "energy nodespace accepts a fresh node after legacy reap");
        } finally {
            level.removeBlock(helper.absolutePos(new BlockPos(1, 4, 1)), false);
            HbmEnergyNodespace.unloadLevel(level);
            HbmFluidNodespace.unloadLevel(level);
            HbmUninosNodespaces.unloadLevel(level);
        }
        helper.succeed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosReapRecovery")
    public static void legacyReapMakesLoadedSpecialisedNodeHostsRecoverOnTheirNextTick(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos rebarPos = helper.absolutePos(new BlockPos(2, 2, 2));
        BlockPos foundryPos = rebarPos.east(3);
        BlockPos pneumaticPos = foundryPos.east(3);
        BlockPos pneumaticAccessPos = pneumaticPos.east(3);
        BlockPos pneumaticClutterPos = pneumaticAccessPos.east(3);
        BlockPos exhaustPos = pneumaticClutterPos.east(3);
        BlockPos paintableExhaustPos = exhaustPos.east(3);
        BlockPos pipeAnchorPos = paintableExhaustPos.east(3);
        BlockPos paintableDuctPos = pipeAnchorPos.east(3);
        BlockPos gaugePos = paintableDuctPos.east(3);
        BlockPos boxDuctPos = gaugePos.east(3);
        BlockPos valvePos = boxDuctPos.east(3);
        BlockPos switchPos = valvePos.east(3);
        BlockPos counterValvePos = switchPos.east(3);
        HbmUninosNodespaces.unloadLevel(level);
        HbmFluidNodespace.unloadLevel(level);
        try {
            level.setBlock(rebarPos, ModBlocks.legacyBlock("rebar").get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(foundryPos, ModBlocks.FOUNDRY_CHANNEL.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(pneumaticPos, ModBlocks.PNEUMATIC_TUBE.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(pneumaticAccessPos, ModBlocks.PNEUMATIC_STORAGE_ACCESS.get().defaultBlockState(),
                    Block.UPDATE_ALL);
            level.setBlock(pneumaticClutterPos, ModBlocks.PNEUMATIC_STORAGE_CLUTTER.get().defaultBlockState(),
                    Block.UPDATE_ALL);
            level.setBlock(exhaustPos, ModBlocks.FLUID_DUCT_EXHAUST.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(paintableExhaustPos, ModBlocks.FLUID_DUCT_PAINTABLE_BLOCK_EXHAUST.get().defaultBlockState(),
                    Block.UPDATE_ALL);
            level.setBlock(pipeAnchorPos, ModBlocks.PIPE_ANCHOR.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(paintableDuctPos, ModBlocks.FLUID_DUCT_PAINTABLE.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(gaugePos, ModBlocks.FLUID_DUCT_GAUGE.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(boxDuctPos, ModBlocks.FLUID_DUCT_BOX.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(valvePos, ModBlocks.FLUID_VALVE.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(switchPos, ModBlocks.FLUID_SWITCH.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(counterValvePos, ModBlocks.FLUID_COUNTER_VALVE.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(rebarPos) instanceof RebarBlockEntity rebar)
                    || !(level.getBlockEntity(foundryPos) instanceof FoundryChannelBlockEntity foundry)
                    || !(level.getBlockEntity(pneumaticPos) instanceof PneumaticTubeBlockEntity pneumatic)
                    || !(level.getBlockEntity(pneumaticAccessPos) instanceof PneumaticStorageAccessBlockEntity pneumaticAccess)
                    || !(level.getBlockEntity(pneumaticClutterPos) instanceof PneumaticStorageClutterBlockEntity pneumaticClutter)
                    || !(level.getBlockEntity(exhaustPos) instanceof FluidDuctExhaustBlockEntity exhaust)
                    || !(level.getBlockEntity(paintableExhaustPos) instanceof FluidDuctPaintableExhaustBlockEntity paintableExhaust)
                    || !(level.getBlockEntity(pipeAnchorPos) instanceof FluidPipeAnchorBlockEntity pipeAnchor)
                    || !(level.getBlockEntity(paintableDuctPos) instanceof FluidDuctPaintableBlockEntity paintableDuct)
                    || !(level.getBlockEntity(gaugePos) instanceof FluidDuctGaugeBlockEntity gauge)
                    || !(level.getBlockEntity(boxDuctPos) instanceof FluidDuctBoxBlockEntity boxDuct)
                    || !(level.getBlockEntity(valvePos) instanceof FluidValveBlockEntity valve)
                    || !(level.getBlockEntity(switchPos) instanceof FluidValveBlockEntity fluidSwitch)
                    || !(level.getBlockEntity(counterValvePos) instanceof FluidCounterValveBlockEntity counterValve)) {
                throw new AssertionError("specialised reap fixture did not create all real node hosts");
            }

            BlockState valveState = level.getBlockState(valvePos);
            BlockState switchState = level.getBlockState(switchPos);
            BlockState counterValveState = level.getBlockState(counterValvePos);
            ((FluidValveBlock) valveState.getBlock()).setOpen(level, valvePos, valveState, true, false);
            ((FluidValveBlock) switchState.getBlock()).setOpen(level, switchPos, switchState, true, false);
            ((FluidValveBlock) counterValveState.getBlock()).setOpen(level, counterValvePos, counterValveState, true, false);
            pipeAnchor.setFluidType(HbmFluids.DIESEL);
            paintableDuct.setFluidType(HbmFluids.DIESEL);
            gauge.setFluidType(HbmFluids.DIESEL);
            boxDuct.setFluidType(HbmFluids.DIESEL);
            valve.setFluidType(HbmFluids.DIESEL);
            fluidSwitch.setFluidType(HbmFluids.DIESEL);
            counterValve.setFluidType(HbmFluids.DIESEL);
            BlockState pipeAnchorState = level.getBlockState(pipeAnchorPos);
            var pipeAnchorTicker = ((FluidPipeBlock) pipeAnchorState.getBlock()).getTicker(level, pipeAnchorState,
                    ModBlockEntities.FLUID_PIPE_ANCHOR.get());
            assertTrue(pipeAnchorTicker != null, "real Pipe Anchor registers the inherited legacy recovery ticker");
            BlockState paintableDuctState = level.getBlockState(paintableDuctPos);
            var paintableDuctTicker = ((FluidPipeBlock) paintableDuctState.getBlock()).getTicker(level,
                    paintableDuctState, ModBlockEntities.FLUID_DUCT_PAINTABLE.get());
            assertTrue(paintableDuctTicker != null,
                    "real paintable Fluid Duct registers the inherited legacy recovery ticker");
            BlockState gaugeState = level.getBlockState(gaugePos);
            var gaugeTicker = ((FluidDuctGaugeBlock) gaugeState.getBlock()).getTicker(level, gaugeState,
                    ModBlockEntities.FLUID_DUCT_GAUGE.get());
            assertTrue(gaugeTicker != null, "real Fluid Duct Gauge registers its legacy recovery ticker");
            BlockState boxDuctState = level.getBlockState(boxDuctPos);
            var boxDuctTicker = ((FluidPipeBlock) boxDuctState.getBlock()).getTicker(level, boxDuctState,
                    ModBlockEntities.FLUID_DUCT_BOX.get());
            assertTrue(boxDuctTicker != null, "real Fluid Duct Box registers the inherited legacy recovery ticker");
            valveState = level.getBlockState(valvePos);
            var valveTicker = ((FluidValveBlock) valveState.getBlock()).getTicker(level, valveState,
                    ModBlockEntities.FLUID_VALVE.get());
            assertTrue(valveTicker != null, "real Fluid Valve registers its legacy recovery ticker");
            switchState = level.getBlockState(switchPos);
            var switchTicker = ((FluidValveBlock) switchState.getBlock()).getTicker(level, switchState,
                    ModBlockEntities.FLUID_VALVE.get());
            assertTrue(switchTicker != null, "real Fluid Switch registers the shared Valve recovery ticker");
            counterValveState = level.getBlockState(counterValvePos);
            var counterValveTicker = ((FluidValveBlock) counterValveState.getBlock()).getTicker(level, counterValveState,
                    ModBlockEntities.FLUID_COUNTER_VALVE.get());
            assertTrue(counterValveTicker != null, "real Fluid Counter Valve registers its legacy recovery ticker");

            RebarBlockEntity.serverTick(level, rebarPos, level.getBlockState(rebarPos), rebar);
            FoundryChannelBlockEntity.serverTick(level, foundryPos, level.getBlockState(foundryPos), foundry);
            PneumaticTubeBlockEntity.serverTick(level, pneumaticPos, level.getBlockState(pneumaticPos), pneumatic);
            PneumaticStorageAccessBlockEntity.serverTick(level, pneumaticAccessPos,
                    level.getBlockState(pneumaticAccessPos), pneumaticAccess);
            PneumaticStorageClutterBlockEntity.serverTick(level, pneumaticClutterPos,
                    level.getBlockState(pneumaticClutterPos), pneumaticClutter);
            FluidDuctExhaustBlockEntity.serverTick(level, exhaustPos, level.getBlockState(exhaustPos), exhaust);
            FluidDuctPaintableExhaustBlockEntity.serverTick(level, paintableExhaustPos,
                    level.getBlockState(paintableExhaustPos), paintableExhaust);
            pipeAnchorTicker.tick(level, pipeAnchorPos, pipeAnchorState, pipeAnchor);
            paintableDuctTicker.tick(level, paintableDuctPos, paintableDuctState, paintableDuct);
            gaugeTicker.tick(level, gaugePos, gaugeState, gauge);
            boxDuctTicker.tick(level, boxDuctPos, boxDuctState, boxDuct);
            valveTicker.tick(level, valvePos, valveState, valve);
            switchTicker.tick(level, switchPos, switchState, fluidSwitch);
            counterValveTicker.tick(level, counterValvePos, counterValveState, counterValve);
            HbmUninosNodespaces.tick(level);
            HbmFluidNodespace.tick(level);

            RebarNode oldRebarNode = RebarNodespace.getNode(level, rebarPos);
            FoundryNode oldFoundryNode = FoundryNodespace.getNode(level, foundryPos);
            PneumaticNode oldPneumaticNode = PneumaticNodespace.getNode(level, pneumaticPos);
            PneumaticNode oldPneumaticAccessNode = PneumaticNodespace.getNode(level, pneumaticAccessPos);
            PneumaticNode oldPneumaticClutterNode = PneumaticNodespace.getNode(level, pneumaticClutterPos);
            HbmFluidNode oldSmokeNode = HbmFluidNodespace.getNode(level, exhaustPos, HbmFluids.SMOKE);
            HbmFluidNode oldLeadedSmokeNode = HbmFluidNodespace.getNode(level, exhaustPos, HbmFluids.SMOKE_LEADED);
            HbmFluidNode oldPoisonSmokeNode = HbmFluidNodespace.getNode(level, exhaustPos, HbmFluids.SMOKE_POISON);
            HbmFluidNode oldPaintableSmokeNode = HbmFluidNodespace.getNode(level, paintableExhaustPos, HbmFluids.SMOKE);
            HbmFluidNode oldPaintableLeadedSmokeNode = HbmFluidNodespace.getNode(level, paintableExhaustPos, HbmFluids.SMOKE_LEADED);
            HbmFluidNode oldPaintablePoisonSmokeNode = HbmFluidNodespace.getNode(level, paintableExhaustPos, HbmFluids.SMOKE_POISON);
            HbmFluidNode oldPipeAnchorNode = pipeAnchor.getFluidNode();
            HbmFluidNode oldPaintableDuctNode = paintableDuct.getFluidNode();
            HbmFluidNode oldGaugeNode = gauge.getFluidNode();
            HbmFluidNode oldBoxDuctNode = boxDuct.getFluidNode();
            HbmFluidNode oldValveNode = valve.getFluidNode();
            HbmFluidNode oldSwitchNode = fluidSwitch.getFluidNode();
            HbmFluidNode oldCounterValveNode = counterValve.getFluidNode();
            assertTrue(oldRebarNode != null && !oldRebarNode.isExpired() && oldRebarNode.getRebarNet() != null,
                    "real Rebar establishes its specialised node before legacy reap");
            assertTrue(oldFoundryNode != null && !oldFoundryNode.isExpired()
                    && oldFoundryNode.getFoundryNet() != null,
                    "real Foundry Channel establishes its specialised node before legacy reap");
            assertTrue(oldPneumaticNode != null && !oldPneumaticNode.isExpired()
                    && oldPneumaticNode.getPneumaticNet() != null,
                    "real Pneumatic Tube establishes its specialised node before legacy reap");
            assertTrue(oldPneumaticAccessNode != null && !oldPneumaticAccessNode.isExpired()
                    && oldPneumaticAccessNode.getPneumaticNet() != null,
                    "real Pneumatic Storage Access establishes its specialised node before legacy reap");
            assertTrue(oldPneumaticClutterNode != null && !oldPneumaticClutterNode.isExpired()
                    && oldPneumaticClutterNode.getPneumaticNet() != null,
                    "real Pneumatic Storage Clutter establishes its specialised node before legacy reap");
            assertTrue(oldSmokeNode != null && !oldSmokeNode.isExpired() && oldSmokeNode.getFluidNet() != null
                    && oldLeadedSmokeNode != null && !oldLeadedSmokeNode.isExpired()
                    && oldLeadedSmokeNode.getFluidNet() != null && oldPoisonSmokeNode != null
                    && !oldPoisonSmokeNode.isExpired() && oldPoisonSmokeNode.getFluidNet() != null,
                    "real Exhaust establishes all three source-backed smoke nodes before legacy reap");
            assertTrue(oldPaintableSmokeNode != null && oldPaintableLeadedSmokeNode != null
                    && oldPaintablePoisonSmokeNode != null, "real paintable Exhaust establishes all three smoke nodes");
            assertTrue(oldPipeAnchorNode != null && !oldPipeAnchorNode.isExpired()
                    && oldPipeAnchorNode.getFluidNet() != null,
                    "real Pipe Anchor establishes its inherited typed node before legacy reap");
            assertTrue(oldPaintableDuctNode != null && !oldPaintableDuctNode.isExpired()
                    && oldPaintableDuctNode.getFluidNet() != null,
                    "real paintable Fluid Duct establishes its inherited typed node before legacy reap");
            assertTrue(oldGaugeNode != null && !oldGaugeNode.isExpired() && oldGaugeNode.getFluidNet() != null,
                    "real Fluid Duct Gauge establishes its inherited typed node before legacy reap");
            assertTrue(oldBoxDuctNode != null && !oldBoxDuctNode.isExpired() && oldBoxDuctNode.getFluidNet() != null
                    && oldValveNode != null && !oldValveNode.isExpired() && oldValveNode.getFluidNet() != null
                    && oldSwitchNode != null && !oldSwitchNode.isExpired() && oldSwitchNode.getFluidNet() != null
                    && oldCounterValveNode != null && !oldCounterValveNode.isExpired()
                    && oldCounterValveNode.getFluidNet() != null,
                    "real Box Duct, Valve, Switch, and Counter Valve establish typed nodes before legacy reap");
            assertLegacyFluidPipeStandardConnections(exhaustPos, oldSmokeNode, "Exhaust smoke");
            assertLegacyFluidPipeStandardConnections(exhaustPos, oldLeadedSmokeNode, "Exhaust leaded smoke");
            assertLegacyFluidPipeStandardConnections(exhaustPos, oldPoisonSmokeNode, "Exhaust poison smoke");
            assertLegacyFluidPipeStandardConnections(paintableExhaustPos, oldPaintableSmokeNode,
                    "paintable Exhaust smoke");
            assertLegacyFluidPipeStandardConnections(paintableExhaustPos, oldPaintableLeadedSmokeNode,
                    "paintable Exhaust leaded smoke");
            assertLegacyFluidPipeStandardConnections(paintableExhaustPos, oldPaintablePoisonSmokeNode,
                    "paintable Exhaust poison smoke");
            assertLegacyFluidPipeStandardConnections(paintableDuctPos, oldPaintableDuctNode, "paintable Fluid Duct");
            assertLegacyFluidPipeStandardConnections(gaugePos, oldGaugeNode, "Fluid Duct Gauge");
            assertLegacyFluidPipeStandardConnections(boxDuctPos, oldBoxDuctNode, "Box Duct");
            assertLegacyFluidPipeStandardConnections(valvePos, oldValveNode, "Fluid Valve");
            assertLegacyFluidPipeStandardConnections(switchPos, oldSwitchNode, "Fluid Switch");
            assertLegacyFluidPipeStandardConnections(counterValvePos, oldCounterValveNode, "Fluid Counter Valve");
            assertTrue(oldPipeAnchorNode.getConnectionPoints().contains(HbmNetworkNode.NodeConnection.point(pipeAnchorPos))
                    && oldPipeAnchorNode.getConnectionPoints().contains(new HbmNetworkNode.NodeConnection(
                            pipeAnchorPos.relative(FluidPipeAnchorBlock.attachedSide(pipeAnchorState)),
                            FluidPipeAnchorBlock.attachedSide(pipeAnchorState))),
                    "Pipe Anchor keeps its legacy UNKNOWN core and metadata-facing physical endpoints");

            // CommandReapNetworks intentionally clears every ServerLevel.  Other
            // GameTest batches may already have nodes in another level, so mirror
            // its source-backed all-level accounting instead of treating this
            // fixture's three nodes as the whole server state.
            int expectedNodes = 0;
            int expectedNetworks = 0;
            for (ServerLevel serverLevel : level.getServer().getAllLevels()) {
                HbmUninosDiagnostics.Totals totals = HbmUninosDiagnostics.totals(serverLevel);
                HbmEnergyNodespace.Diagnostics energyDiagnostics = HbmEnergyNodespace.getDiagnostics(serverLevel);
                HbmFluidNodespace.Diagnostics fluidDiagnostics = HbmFluidNodespace.getDiagnostics(serverLevel);
                expectedNodes += totals.uniqueNodes() + energyDiagnostics.uniqueNodes() + fluidDiagnostics.uniqueNodes();
                expectedNetworks += totals.networks() + energyDiagnostics.networks() + fluidDiagnostics.networks();
            }
            assertCommandVisibleMessage(level, rebarPos, "ntmreapnetworks", expectedNodes,
                    "UNINOS nodespaces cleared: nodes=" + expectedNodes + " networks=" + expectedNetworks);

            assertTrue(oldRebarNode.isExpired() && oldFoundryNode.isExpired() && oldPneumaticNode.isExpired()
                    && oldPneumaticAccessNode.isExpired() && oldPneumaticClutterNode.isExpired()
                    && oldSmokeNode.isExpired() && oldLeadedSmokeNode.isExpired() && oldPoisonSmokeNode.isExpired(),
                    "legacy reap expires every real specialised node host");
            assertTrue(RebarNodespace.getNode(level, rebarPos) == null
                    && FoundryNodespace.getNode(level, foundryPos) == null
                    && PneumaticNodespace.getNode(level, pneumaticPos) == null
                    && PneumaticNodespace.getNode(level, pneumaticAccessPos) == null
                    && PneumaticNodespace.getNode(level, pneumaticClutterPos) == null
                    && HbmFluidNodespace.getNode(level, exhaustPos, HbmFluids.SMOKE) == null
                    && HbmFluidNodespace.getNode(level, exhaustPos, HbmFluids.SMOKE_LEADED) == null
                    && HbmFluidNodespace.getNode(level, exhaustPos, HbmFluids.SMOKE_POISON) == null,
                    "legacy reap clears every specialised nodespace mapping");
            assertTrue(oldPipeAnchorNode.isExpired()
                    && HbmFluidNodespace.getNode(level, pipeAnchorPos, HbmFluids.DIESEL) == null,
                    "legacy reap expires and clears the real Pipe Anchor typed node");
            assertTrue(oldPaintableDuctNode.isExpired()
                    && HbmFluidNodespace.getNode(level, paintableDuctPos, HbmFluids.DIESEL) == null
                    && oldGaugeNode.isExpired()
                    && HbmFluidNodespace.getNode(level, gaugePos, HbmFluids.DIESEL) == null,
                    "legacy reap expires and clears paintable Duct and Gauge typed nodes");
            assertTrue(oldBoxDuctNode.isExpired()
                    && HbmFluidNodespace.getNode(level, boxDuctPos, HbmFluids.DIESEL) == null
                    && oldValveNode.isExpired() && HbmFluidNodespace.getNode(level, valvePos, HbmFluids.DIESEL) == null
                    && oldSwitchNode.isExpired() && HbmFluidNodespace.getNode(level, switchPos, HbmFluids.DIESEL) == null
                    && oldCounterValveNode.isExpired()
                    && HbmFluidNodespace.getNode(level, counterValvePos, HbmFluids.DIESEL) == null,
                    "legacy reap expires and clears Box Duct, Valve, Switch, and Counter Valve typed nodes");
            assertTrue(oldPaintableSmokeNode.isExpired() && oldPaintableLeadedSmokeNode.isExpired()
                    && oldPaintablePoisonSmokeNode.isExpired()
                    && HbmFluidNodespace.getNode(level, paintableExhaustPos, HbmFluids.SMOKE) == null
                    && HbmFluidNodespace.getNode(level, paintableExhaustPos, HbmFluids.SMOKE_LEADED) == null
                    && HbmFluidNodespace.getNode(level, paintableExhaustPos, HbmFluids.SMOKE_POISON) == null,
                    "legacy reap expires and clears every paintable Exhaust smoke node");

            RebarBlockEntity.serverTick(level, rebarPos, level.getBlockState(rebarPos), rebar);
            FoundryChannelBlockEntity.serverTick(level, foundryPos, level.getBlockState(foundryPos), foundry);
            PneumaticTubeBlockEntity.serverTick(level, pneumaticPos, level.getBlockState(pneumaticPos), pneumatic);
            PneumaticStorageAccessBlockEntity.serverTick(level, pneumaticAccessPos,
                    level.getBlockState(pneumaticAccessPos), pneumaticAccess);
            PneumaticStorageClutterBlockEntity.serverTick(level, pneumaticClutterPos,
                    level.getBlockState(pneumaticClutterPos), pneumaticClutter);
            FluidDuctExhaustBlockEntity.serverTick(level, exhaustPos, level.getBlockState(exhaustPos), exhaust);
            FluidDuctPaintableExhaustBlockEntity.serverTick(level, paintableExhaustPos,
                    level.getBlockState(paintableExhaustPos), paintableExhaust);
            pipeAnchorTicker.tick(level, pipeAnchorPos, pipeAnchorState, pipeAnchor);
            paintableDuctTicker.tick(level, paintableDuctPos, paintableDuctState, paintableDuct);
            gaugeTicker.tick(level, gaugePos, gaugeState, gauge);
            boxDuctTicker.tick(level, boxDuctPos, boxDuctState, boxDuct);
            valveTicker.tick(level, valvePos, valveState, valve);
            switchTicker.tick(level, switchPos, switchState, fluidSwitch);
            counterValveTicker.tick(level, counterValvePos, counterValveState, counterValve);
            RebarNode restoredRebarNode = RebarNodespace.getNode(level, rebarPos);
            FoundryNode restoredFoundryNode = FoundryNodespace.getNode(level, foundryPos);
            PneumaticNode restoredPneumaticNode = PneumaticNodespace.getNode(level, pneumaticPos);
            PneumaticNode restoredPneumaticAccessNode = PneumaticNodespace.getNode(level, pneumaticAccessPos);
            PneumaticNode restoredPneumaticClutterNode = PneumaticNodespace.getNode(level, pneumaticClutterPos);
            HbmFluidNode restoredSmokeNode = HbmFluidNodespace.getNode(level, exhaustPos, HbmFluids.SMOKE);
            HbmFluidNode restoredLeadedSmokeNode = HbmFluidNodespace.getNode(level, exhaustPos, HbmFluids.SMOKE_LEADED);
            HbmFluidNode restoredPoisonSmokeNode = HbmFluidNodespace.getNode(level, exhaustPos, HbmFluids.SMOKE_POISON);
            HbmFluidNode restoredPaintableSmokeNode = HbmFluidNodespace.getNode(level, paintableExhaustPos, HbmFluids.SMOKE);
            HbmFluidNode restoredPaintableLeadedSmokeNode = HbmFluidNodespace.getNode(level, paintableExhaustPos, HbmFluids.SMOKE_LEADED);
            HbmFluidNode restoredPaintablePoisonSmokeNode = HbmFluidNodespace.getNode(level, paintableExhaustPos, HbmFluids.SMOKE_POISON);
            HbmFluidNode restoredPipeAnchorNode = pipeAnchor.getFluidNode();
            HbmFluidNode restoredPaintableDuctNode = paintableDuct.getFluidNode();
            HbmFluidNode restoredGaugeNode = gauge.getFluidNode();
            HbmFluidNode restoredBoxDuctNode = boxDuct.getFluidNode();
            HbmFluidNode restoredValveNode = valve.getFluidNode();
            HbmFluidNode restoredSwitchNode = fluidSwitch.getFluidNode();
            HbmFluidNode restoredCounterValveNode = counterValve.getFluidNode();
            assertTrue(restoredRebarNode != null && restoredRebarNode != oldRebarNode
                    && !restoredRebarNode.isExpired(),
                    "real Rebar recreates its specialised node on the next server tick");
            assertTrue(restoredFoundryNode != null && restoredFoundryNode != oldFoundryNode
                    && !restoredFoundryNode.isExpired(),
                    "real Foundry Channel recreates its specialised node on the next server tick");
            assertTrue(restoredPneumaticNode != null && restoredPneumaticNode != oldPneumaticNode
                    && !restoredPneumaticNode.isExpired(),
                    "real Pneumatic Tube recreates its specialised node on the next server tick");
            assertTrue(restoredPneumaticAccessNode != null && restoredPneumaticAccessNode != oldPneumaticAccessNode
                    && !restoredPneumaticAccessNode.isExpired(),
                    "real Pneumatic Storage Access recreates its specialised node on the next server tick");
            assertTrue(restoredPneumaticClutterNode != null && restoredPneumaticClutterNode != oldPneumaticClutterNode
                    && !restoredPneumaticClutterNode.isExpired(),
                    "real Pneumatic Storage Clutter recreates its specialised node on the next server tick");
            assertTrue(restoredSmokeNode != null && restoredSmokeNode != oldSmokeNode && !restoredSmokeNode.isExpired()
                    && restoredLeadedSmokeNode != null && restoredLeadedSmokeNode != oldLeadedSmokeNode
                    && !restoredLeadedSmokeNode.isExpired() && restoredPoisonSmokeNode != null
                    && restoredPoisonSmokeNode != oldPoisonSmokeNode && !restoredPoisonSmokeNode.isExpired(),
                    "real Exhaust recreates all three typed smoke nodes on the next server tick");
            assertTrue(restoredPaintableSmokeNode != null && restoredPaintableSmokeNode != oldPaintableSmokeNode
                    && restoredPaintableLeadedSmokeNode != null
                    && restoredPaintableLeadedSmokeNode != oldPaintableLeadedSmokeNode
                    && restoredPaintablePoisonSmokeNode != null
                    && restoredPaintablePoisonSmokeNode != oldPaintablePoisonSmokeNode,
                    "real paintable Exhaust recreates every typed smoke node on the next server tick");
            assertTrue(restoredPipeAnchorNode != null && restoredPipeAnchorNode != oldPipeAnchorNode
                    && !restoredPipeAnchorNode.isExpired()
                    && HbmFluidNodespace.getNode(level, pipeAnchorPos, HbmFluids.DIESEL) == restoredPipeAnchorNode,
                    "real Pipe Anchor recreates its typed node through the inherited ticker after legacy reap");
            assertTrue(restoredPaintableDuctNode != null && restoredPaintableDuctNode != oldPaintableDuctNode
                    && !restoredPaintableDuctNode.isExpired()
                    && HbmFluidNodespace.getNode(level, paintableDuctPos, HbmFluids.DIESEL) == restoredPaintableDuctNode,
                    "real paintable Fluid Duct recreates its typed node through the inherited ticker after legacy reap");
            assertTrue(restoredGaugeNode != null && restoredGaugeNode != oldGaugeNode && !restoredGaugeNode.isExpired()
                    && HbmFluidNodespace.getNode(level, gaugePos, HbmFluids.DIESEL) == restoredGaugeNode,
                    "real Fluid Duct Gauge recreates its typed node before its gauge sampling after legacy reap");
            assertTrue(restoredBoxDuctNode != null && restoredBoxDuctNode != oldBoxDuctNode
                    && !restoredBoxDuctNode.isExpired()
                    && restoredValveNode != null && restoredValveNode != oldValveNode && !restoredValveNode.isExpired()
                    && restoredSwitchNode != null && restoredSwitchNode != oldSwitchNode
                    && !restoredSwitchNode.isExpired()
                    && restoredCounterValveNode != null && restoredCounterValveNode != oldCounterValveNode
                    && !restoredCounterValveNode.isExpired(),
                    "Box Duct, Valve, Switch, and Counter Valve recreate typed nodes through their actual tickers");

            HbmUninosNodespaces.tick(level);
            HbmFluidNodespace.tick(level);
            assertTrue(restoredRebarNode.getRebarNet() != null && restoredFoundryNode.getFoundryNet() != null
                    && restoredPneumaticNode.getPneumaticNet() != null
                    && restoredPneumaticAccessNode.getPneumaticNet() != null
                    && restoredPneumaticClutterNode.getPneumaticNet() != null,
                    "recovered specialised nodes join their networks on the following legacy START update");
            assertTrue(restoredSmokeNode.getFluidNet() != null && restoredLeadedSmokeNode.getFluidNet() != null
                    && restoredPoisonSmokeNode.getFluidNet() != null,
                    "recovered Exhaust smoke nodes join their networks on the following legacy START update");
            assertTrue(restoredPaintableSmokeNode.getFluidNet() != null
                    && restoredPaintableLeadedSmokeNode.getFluidNet() != null
                    && restoredPaintablePoisonSmokeNode.getFluidNet() != null,
                    "recovered paintable Exhaust smoke nodes join their networks on the following legacy START update");
            assertTrue(restoredPipeAnchorNode.getFluidNet() != null,
                    "recovered Pipe Anchor joins its inherited fluid network on the following legacy START update");
            assertTrue(restoredPaintableDuctNode.getFluidNet() != null && restoredGaugeNode.getFluidNet() != null,
                    "recovered paintable Fluid Duct and Gauge join their networks on the following legacy START update");
            assertTrue(restoredBoxDuctNode.getFluidNet() != null && restoredValveNode.getFluidNet() != null
                    && restoredSwitchNode.getFluidNet() != null && restoredCounterValveNode.getFluidNet() != null,
                    "recovered Box Duct, Valve, Switch, and Counter Valve join networks on the following START update");
        } finally {
            level.removeBlock(rebarPos, false);
            level.removeBlock(foundryPos, false);
            level.removeBlock(pneumaticPos, false);
            level.removeBlock(pneumaticAccessPos, false);
            level.removeBlock(pneumaticClutterPos, false);
            level.removeBlock(exhaustPos, false);
            level.removeBlock(paintableExhaustPos, false);
            level.removeBlock(pipeAnchorPos, false);
            level.removeBlock(paintableDuctPos, false);
            level.removeBlock(gaugePos, false);
            level.removeBlock(boxDuctPos, false);
            level.removeBlock(valvePos, false);
            level.removeBlock(switchPos, false);
            level.removeBlock(counterValvePos, false);
            HbmUninosNodespaces.unloadLevel(level);
            HbmFluidNodespace.unloadLevel(level);
        }
        helper.succeed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosReapStorage")
    public static void legacyReapMakesLoadedBufferStorageHostsRecoverOnTheirNextTick(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos tankPos = helper.absolutePos(new BlockPos(2, 2, 2));
        BlockPos barrelPos = tankPos.east(3);
        BlockPos batteryPos = barrelPos.east(3);
        BlockPos fensuPos = batteryPos.east(3);
        BlockPos socketPos = fensuPos.east(5);
        HbmEnergyNodespace.unloadLevel(level);
        HbmFluidNodespace.unloadLevel(level);
        try {
            level.setBlock(tankPos, ModBlocks.MACHINE_FLUIDTANK.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(barrelPos, ModBlocks.BARREL_PLASTIC.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(batteryPos, ModBlocks.MACHINE_BATTERY.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(fensuPos, ModBlocks.MACHINE_FENSU.get().defaultBlockState(), Block.UPDATE_ALL);
            BlockState socketState = ModBlocks.MACHINE_BATTERY_SOCKET.get().defaultBlockState()
                    .setValue(MachineBatterySocketBlock.FACING, Direction.SOUTH);
            level.setBlock(socketPos, socketState, Block.UPDATE_ALL);
            socketState.getBlock().setPlacedBy(level, socketPos, socketState, null, ItemStack.EMPTY);
            if (!(level.getBlockEntity(tankPos) instanceof FluidTankBlockEntity tank)
                    || !(level.getBlockEntity(barrelPos) instanceof FluidBarrelBlockEntity barrel)
                    || !(level.getBlockEntity(batteryPos) instanceof MachineBatteryBlockEntity battery)
                    || !(level.getBlockEntity(fensuPos) instanceof FensuBlockEntity fensu)
                    || !(level.getBlockEntity(socketPos) instanceof MachineBatterySocketBlockEntity socket)) {
                throw new AssertionError("buffer-storage reap fixture did not create all real node hosts");
            }

            tank.getTank().setTankType(HbmFluids.DIESEL);
            tank.setMode(FluidTankBlockEntity.MODE_BUFFER);
            barrel.getTank().setTankType(HbmFluids.DIESEL);
            barrel.setMode(FluidTankBlockEntity.MODE_BUFFER);
            while (battery.getRedLow() != MachineBatteryBlockEntity.MODE_BUFFER) {
                battery.cycleRedLowMode();
            }
            while (fensu.getRedLow() != MachineBatteryBlockEntity.MODE_BUFFER) {
                fensu.cycleRedLowMode();
            }

            BlockState tankState = level.getBlockState(tankPos);
            BlockState barrelState = level.getBlockState(barrelPos);
            BlockState batteryState = level.getBlockState(batteryPos);
            BlockState fensuState = level.getBlockState(fensuPos);
            socketState = level.getBlockState(socketPos);
            var tankTicker = ((FluidTankBlock) tankState.getBlock()).getTicker(level, tankState,
                    ModBlockEntities.FLUID_TANK.get());
            var barrelTicker = ((FluidBarrelBlock) barrelState.getBlock()).getTicker(level, barrelState,
                    ModBlockEntities.FLUID_BARREL.get());
            var batteryTicker = ((MachineBatteryBlock) batteryState.getBlock()).getTicker(level, batteryState,
                    ModBlockEntities.MACHINE_BATTERY.get());
            var fensuTicker = ((FensuBlock) fensuState.getBlock()).getTicker(level, fensuState,
                    ModBlockEntities.MACHINE_FENSU.get());
            var socketTicker = ((MachineBatterySocketBlock) socketState.getBlock()).getTicker(level, socketState,
                    ModBlockEntities.MACHINE_BATTERY_SOCKET.get());
            assertTrue(tankTicker != null && barrelTicker != null && batteryTicker != null && fensuTicker != null
                    && socketTicker != null,
                    "real Fluid Tank, Barrel, Machine Battery, FEnSU, and Battery Socket register server tickers");

            tankTicker.tick(level, tankPos, tankState, tank);
            barrelTicker.tick(level, barrelPos, barrelState, barrel);
            batteryTicker.tick(level, batteryPos, batteryState, battery);
            fensuTicker.tick(level, fensuPos, fensuState, fensu);
            socketTicker.tick(level, socketPos, socketState, socket);
            HbmEnergyNodespace.tick(level);
            HbmFluidNodespace.tick(level);

            HbmFluidNode oldTankNode = tank.getFluidNode();
            HbmFluidNode oldBarrelNode = barrel.getFluidNode();
            HbmEnergyNode oldBatteryNode = battery.getEnergyNode();
            HbmEnergyNode oldFensuNode = fensu.getEnergyNode();
            HbmEnergyNode oldSocketNode = socket.getEnergyNode();
            assertTrue(oldTankNode != null && oldTankNode.getFluidNet() != null
                    && oldBarrelNode != null && oldBarrelNode.getFluidNet() != null
                    && oldBatteryNode != null && oldBatteryNode.getPowerNet() != null
                    && oldFensuNode != null && oldFensuNode.getPowerNet() != null
                    && oldSocketNode != null && oldSocketNode.getPowerNet() != null,
                    "real buffer storage hosts establish their source-backed local nodes before legacy reap");

            int expectedNodes = 0;
            int expectedNetworks = 0;
            for (ServerLevel serverLevel : level.getServer().getAllLevels()) {
                HbmUninosDiagnostics.Totals totals = HbmUninosDiagnostics.totals(serverLevel);
                HbmEnergyNodespace.Diagnostics energyDiagnostics = HbmEnergyNodespace.getDiagnostics(serverLevel);
                HbmFluidNodespace.Diagnostics fluidDiagnostics = HbmFluidNodespace.getDiagnostics(serverLevel);
                expectedNodes += totals.uniqueNodes() + energyDiagnostics.uniqueNodes() + fluidDiagnostics.uniqueNodes();
                expectedNetworks += totals.networks() + energyDiagnostics.networks() + fluidDiagnostics.networks();
            }
            assertCommandVisibleMessage(level, tankPos, "ntmreapnetworks", expectedNodes,
                    "UNINOS nodespaces cleared: nodes=" + expectedNodes + " networks=" + expectedNetworks);

            assertTrue(oldTankNode.isExpired() && oldBarrelNode.isExpired()
                    && oldBatteryNode.isExpired() && oldFensuNode.isExpired() && oldSocketNode.isExpired(),
                    "legacy reap expires all source-backed buffer storage nodes");
            assertTrue(HbmFluidNodespace.getNode(level, tankPos, HbmFluids.DIESEL) == null
                    && HbmFluidNodespace.getNode(level, barrelPos, HbmFluids.DIESEL) == null
                    && HbmEnergyNodespace.getNode(level, batteryPos) == null
                    && HbmEnergyNodespace.getNode(level, fensuPos) == null
                    && HbmEnergyNodespace.getNode(level, socketPos) == null,
                    "legacy reap clears every buffer-storage node mapping");

            tankTicker.tick(level, tankPos, tankState, tank);
            barrelTicker.tick(level, barrelPos, barrelState, barrel);
            batteryTicker.tick(level, batteryPos, batteryState, battery);
            fensuTicker.tick(level, fensuPos, fensuState, fensu);
            socketTicker.tick(level, socketPos, socketState, socket);
            HbmFluidNode restoredTankNode = tank.getFluidNode();
            HbmFluidNode restoredBarrelNode = barrel.getFluidNode();
            HbmEnergyNode restoredBatteryNode = battery.getEnergyNode();
            HbmEnergyNode restoredFensuNode = fensu.getEnergyNode();
            HbmEnergyNode restoredSocketNode = socket.getEnergyNode();
            assertTrue(restoredTankNode != null && restoredTankNode != oldTankNode && !restoredTankNode.isExpired()
                    && restoredBarrelNode != null && restoredBarrelNode != oldBarrelNode && !restoredBarrelNode.isExpired()
                    && restoredBatteryNode != null && restoredBatteryNode != oldBatteryNode && !restoredBatteryNode.isExpired()
                    && restoredFensuNode != null && restoredFensuNode != oldFensuNode && !restoredFensuNode.isExpired()
                    && restoredSocketNode != null && restoredSocketNode != oldSocketNode && !restoredSocketNode.isExpired(),
                    "real buffer storage tickers recreate their local nodes after legacy reap");

            HbmEnergyNodespace.tick(level);
            HbmFluidNodespace.tick(level);
            assertTrue(restoredTankNode.getFluidNet() != null && restoredBarrelNode.getFluidNet() != null
                    && restoredBatteryNode.getPowerNet() != null && restoredFensuNode.getPowerNet() != null
                    && restoredSocketNode.getPowerNet() != null,
                    "recovered buffer storage nodes join networks on the following legacy START update");
        } finally {
            level.removeBlock(tankPos, false);
            level.removeBlock(barrelPos, false);
            level.removeBlock(batteryPos, false);
            level.removeBlock(fensuPos, false);
            level.removeBlock(socketPos, false);
            HbmEnergyNodespace.unloadLevel(level);
            HbmFluidNodespace.unloadLevel(level);
        }
        helper.succeed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosReapCables")
    public static void legacyReapMakesLoadedCableHostsRecoverOnTheirNextTick(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos cablePos = helper.absolutePos(new BlockPos(2, 2, 2));
        BlockPos coatedPos = cablePos.east(3);
        BlockPos boxPos = coatedPos.east(3);
        BlockPos gaugePos = boxPos.east(3);
        BlockPos switchPos = gaugePos.east(3);
        BlockPos detectorPos = switchPos.east(3);
        BlockPos paintablePos = cablePos.south(3);
        HbmEnergyNodespace.unloadLevel(level);
        try {
            level.setBlock(cablePos, ModBlocks.RED_CABLE.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(coatedPos, ModBlocks.RED_WIRE_COATED.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(boxPos, ModBlocks.RED_CABLE_BOX.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(gaugePos, ModBlocks.RED_CABLE_GAUGE.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(switchPos, ModBlocks.CABLE_SWITCH.get().defaultBlockState()
                    .setValue(PoweredRedCableBlock.ACTIVE, true), Block.UPDATE_ALL);
            level.setBlock(detectorPos, ModBlocks.CABLE_DETECTOR.get().defaultBlockState()
                    .setValue(PoweredRedCableBlock.ACTIVE, true), Block.UPDATE_ALL);
            level.setBlock(paintablePos, ModBlocks.RED_CABLE_PAINTABLE.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(cablePos) instanceof RedCableBlockEntity cable)
                    || !(level.getBlockEntity(coatedPos) instanceof RedCableBlockEntity coated)
                    || !(level.getBlockEntity(boxPos) instanceof RedCableBlockEntity box)
                    || !(level.getBlockEntity(gaugePos) instanceof RedCableGaugeBlockEntity gauge)
                    || !(level.getBlockEntity(switchPos) instanceof PoweredRedCableBlockEntity cableSwitch)
                    || !(level.getBlockEntity(detectorPos) instanceof PoweredRedCableBlockEntity detector)
                    || !(level.getBlockEntity(paintablePos) instanceof RedCablePaintableBlockEntity paintable)) {
                throw new AssertionError("cable reap fixture did not create all real Energy MK2 node hosts");
            }

            BlockState cableState = level.getBlockState(cablePos);
            BlockState coatedState = level.getBlockState(coatedPos);
            BlockState boxState = level.getBlockState(boxPos);
            BlockState gaugeState = level.getBlockState(gaugePos);
            BlockState switchState = level.getBlockState(switchPos);
            BlockState detectorState = level.getBlockState(detectorPos);
            BlockState paintableState = level.getBlockState(paintablePos);
            var cableTicker = ((RedCableBlock) cableState.getBlock()).getTicker(level, cableState,
                    ModBlockEntities.RED_CABLE.get());
            var coatedTicker = ((RedWireCoatedBlock) coatedState.getBlock()).getTicker(level, coatedState,
                    ModBlockEntities.RED_CABLE.get());
            var boxTicker = ((RedCableBoxBlock) boxState.getBlock()).getTicker(level, boxState,
                    ModBlockEntities.RED_CABLE.get());
            var gaugeTicker = ((RedCableGaugeBlock) gaugeState.getBlock()).getTicker(level, gaugeState,
                    ModBlockEntities.RED_CABLE_GAUGE.get());
            var switchTicker = ((PoweredRedCableBlock) switchState.getBlock()).getTicker(level, switchState,
                    ModBlockEntities.CABLE_SWITCH.get());
            var detectorTicker = ((PoweredRedCableBlock) detectorState.getBlock()).getTicker(level, detectorState,
                    ModBlockEntities.CABLE_DETECTOR.get());
            var paintableTicker = ((RedCablePaintableBlock) paintableState.getBlock()).getTicker(level, paintableState,
                    ModBlockEntities.RED_CABLE_PAINTABLE.get());
            assertTrue(cableTicker != null && coatedTicker != null && boxTicker != null && gaugeTicker != null
                    && switchTicker != null && detectorTicker != null && paintableTicker != null,
                    "real cable hosts register their source-backed server-tick recovery hooks");

            cableTicker.tick(level, cablePos, cableState, cable);
            coatedTicker.tick(level, coatedPos, coatedState, coated);
            boxTicker.tick(level, boxPos, boxState, box);
            gaugeTicker.tick(level, gaugePos, gaugeState, gauge);
            switchTicker.tick(level, switchPos, switchState, cableSwitch);
            detectorTicker.tick(level, detectorPos, detectorState, detector);
            paintableTicker.tick(level, paintablePos, paintableState, paintable);
            HbmEnergyNodespace.tick(level);

            HbmEnergyNode oldCableNode = cable.getEnergyNode();
            HbmEnergyNode oldCoatedNode = coated.getEnergyNode();
            HbmEnergyNode oldBoxNode = box.getEnergyNode();
            HbmEnergyNode oldGaugeNode = gauge.getEnergyNode();
            HbmEnergyNode oldSwitchNode = cableSwitch.getEnergyNode();
            HbmEnergyNode oldDetectorNode = detector.getEnergyNode();
            HbmEnergyNode oldPaintableNode = paintable.getEnergyNode();
            assertTrue(oldCableNode != null && oldCableNode.getPowerNet() != null
                    && oldCoatedNode != null && oldCoatedNode.getPowerNet() != null
                    && oldBoxNode != null && oldBoxNode.getPowerNet() != null
                    && oldGaugeNode != null && oldGaugeNode.getPowerNet() != null
                    && oldSwitchNode != null && oldSwitchNode.getPowerNet() != null
                    && oldDetectorNode != null && oldDetectorNode.getPowerNet() != null
                    && oldPaintableNode != null && oldPaintableNode.getPowerNet() != null,
                    "real active cable hosts establish their source-backed nodes before legacy reap");
            assertLegacyCableBaseStandardConnections(cablePos, oldCableNode, "normal cable");
            assertLegacyCableBaseStandardConnections(coatedPos, oldCoatedNode, "coated cable");
            assertLegacyCableBaseStandardConnections(boxPos, oldBoxNode, "box cable");
            assertLegacyCableBaseStandardConnections(gaugePos, oldGaugeNode, "Gauge");
            assertLegacyCableBaseStandardConnections(switchPos, oldSwitchNode, "active cable switch");
            assertLegacyCableBaseStandardConnections(detectorPos, oldDetectorNode, "active cable detector");
            assertLegacyCableBaseStandardConnections(paintablePos, oldPaintableNode, "paintable cable");

            int expectedNodes = 0;
            int expectedNetworks = 0;
            for (ServerLevel serverLevel : level.getServer().getAllLevels()) {
                HbmUninosDiagnostics.Totals totals = HbmUninosDiagnostics.totals(serverLevel);
                HbmEnergyNodespace.Diagnostics energyDiagnostics = HbmEnergyNodespace.getDiagnostics(serverLevel);
                HbmFluidNodespace.Diagnostics fluidDiagnostics = HbmFluidNodespace.getDiagnostics(serverLevel);
                expectedNodes += totals.uniqueNodes() + energyDiagnostics.uniqueNodes() + fluidDiagnostics.uniqueNodes();
                expectedNetworks += totals.networks() + energyDiagnostics.networks() + fluidDiagnostics.networks();
            }
            assertCommandVisibleMessage(level, cablePos, "ntmreapnetworks", expectedNodes,
                    "UNINOS nodespaces cleared: nodes=" + expectedNodes + " networks=" + expectedNetworks);

            assertTrue(oldCableNode.isExpired() && oldCoatedNode.isExpired() && oldBoxNode.isExpired()
                    && oldGaugeNode.isExpired()
                    && oldSwitchNode.isExpired() && oldDetectorNode.isExpired() && oldPaintableNode.isExpired(),
                    "legacy reap expires every real cable node");
            assertTrue(HbmEnergyNodespace.getNode(level, cablePos) == null
                    && HbmEnergyNodespace.getNode(level, coatedPos) == null
                    && HbmEnergyNodespace.getNode(level, boxPos) == null
                    && HbmEnergyNodespace.getNode(level, gaugePos) == null
                    && HbmEnergyNodespace.getNode(level, switchPos) == null
                    && HbmEnergyNodespace.getNode(level, detectorPos) == null
                    && HbmEnergyNodespace.getNode(level, paintablePos) == null,
                    "legacy reap clears every cable nodespace mapping");

            cableTicker.tick(level, cablePos, cableState, cable);
            coatedTicker.tick(level, coatedPos, coatedState, coated);
            boxTicker.tick(level, boxPos, boxState, box);
            gaugeTicker.tick(level, gaugePos, gaugeState, gauge);
            switchTicker.tick(level, switchPos, switchState, cableSwitch);
            detectorTicker.tick(level, detectorPos, detectorState, detector);
            paintableTicker.tick(level, paintablePos, paintableState, paintable);
            HbmEnergyNode restoredCableNode = cable.getEnergyNode();
            HbmEnergyNode restoredCoatedNode = coated.getEnergyNode();
            HbmEnergyNode restoredBoxNode = box.getEnergyNode();
            HbmEnergyNode restoredGaugeNode = gauge.getEnergyNode();
            HbmEnergyNode restoredSwitchNode = cableSwitch.getEnergyNode();
            HbmEnergyNode restoredDetectorNode = detector.getEnergyNode();
            HbmEnergyNode restoredPaintableNode = paintable.getEnergyNode();
            assertTrue(restoredCableNode != null && restoredCableNode != oldCableNode && !restoredCableNode.isExpired()
                    && restoredCoatedNode != null && restoredCoatedNode != oldCoatedNode && !restoredCoatedNode.isExpired()
                    && restoredBoxNode != null && restoredBoxNode != oldBoxNode && !restoredBoxNode.isExpired()
                    && restoredGaugeNode != null && restoredGaugeNode != oldGaugeNode && !restoredGaugeNode.isExpired()
                    && restoredSwitchNode != null && restoredSwitchNode != oldSwitchNode && !restoredSwitchNode.isExpired()
                    && restoredDetectorNode != null && restoredDetectorNode != oldDetectorNode
                    && !restoredDetectorNode.isExpired()
                    && restoredPaintableNode != null && restoredPaintableNode != oldPaintableNode
                    && !restoredPaintableNode.isExpired(),
                    "real cable tickers recreate their nodes after legacy reap");
            assertSame(restoredCableNode, HbmEnergyNodespace.getNode(level, cablePos),
                    "normal cable restores its nodespace mapping");
            assertSame(restoredCoatedNode, HbmEnergyNodespace.getNode(level, coatedPos),
                    "coated cable restores its nodespace mapping");
            assertSame(restoredBoxNode, HbmEnergyNodespace.getNode(level, boxPos),
                    "box cable restores its nodespace mapping");
            assertSame(restoredGaugeNode, HbmEnergyNodespace.getNode(level, gaugePos),
                    "Gauge restores its node before sampling its power tracker");
            assertSame(restoredSwitchNode, HbmEnergyNodespace.getNode(level, switchPos),
                    "active cable switch restores its nodespace mapping");
            assertSame(restoredDetectorNode, HbmEnergyNodespace.getNode(level, detectorPos),
                    "active cable detector restores its nodespace mapping");
            assertSame(restoredPaintableNode, HbmEnergyNodespace.getNode(level, paintablePos),
                    "paintable cable restores its nodespace mapping through the legacy CableBase ticker");

            HbmEnergyNodespace.tick(level);
            assertTrue(restoredCableNode.getPowerNet() != null && restoredCoatedNode.getPowerNet() != null
                    && restoredBoxNode.getPowerNet() != null && restoredGaugeNode.getPowerNet() != null
                    && restoredSwitchNode.getPowerNet() != null
                    && restoredDetectorNode.getPowerNet() != null && restoredPaintableNode.getPowerNet() != null,
                    "recovered cable nodes join networks on the following legacy START update");
        } finally {
            level.removeBlock(cablePos, false);
            level.removeBlock(coatedPos, false);
            level.removeBlock(boxPos, false);
            level.removeBlock(gaugePos, false);
            level.removeBlock(switchPos, false);
            level.removeBlock(detectorPos, false);
            level.removeBlock(paintablePos, false);
            HbmEnergyNodespace.unloadLevel(level);
        }
        helper.succeed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosReapWireHosts")
    public static void legacyReapMakesLoadedWireHostsRecoverOnTheirNextTick(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos connectorPos = helper.absolutePos(new BlockPos(2, 2, 2));
        BlockPos smallPylonPos = connectorPos.east(4);
        BlockPos mediumPylonPos = smallPylonPos.east(4);
        BlockPos largePylonPos = mediumPylonPos.east(4);
        BlockPos substationPos = connectorPos.south(4);
        List<BlockPos> positions = List.of(connectorPos, smallPylonPos, mediumPylonPos, largePylonPos, substationPos);
        HbmEnergyNodespace.unloadLevel(level);
        try {
            level.setBlock(connectorPos, ModBlocks.RED_CONNECTOR.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(smallPylonPos, ModBlocks.RED_PYLON.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(mediumPylonPos, ModBlocks.RED_PYLON_MEDIUM_WOOD.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(largePylonPos, ModBlocks.RED_PYLON_LARGE.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(substationPos, ModBlocks.SUBSTATION.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(connectorPos) instanceof HbmLegacyWireNodeBlockEntity connector)
                    || !(level.getBlockEntity(smallPylonPos) instanceof HbmLegacyWireNodeBlockEntity smallPylon)
                    || !(level.getBlockEntity(mediumPylonPos) instanceof HbmLegacyWireNodeBlockEntity mediumPylon)
                    || !(level.getBlockEntity(largePylonPos) instanceof HbmLegacyWireNodeBlockEntity largePylon)
                    || !(level.getBlockEntity(substationPos) instanceof HbmLegacyWireNodeBlockEntity substation)) {
                throw new AssertionError("wire-host reap fixture did not create every real legacy wire node host");
            }

            tickLegacyWireHost(level, connectorPos, connector, ModBlockEntities.RED_CONNECTOR.get());
            tickLegacyWireHost(level, smallPylonPos, smallPylon, ModBlockEntities.RED_PYLON.get());
            tickLegacyWireHost(level, mediumPylonPos, mediumPylon, ModBlockEntities.RED_PYLON_MEDIUM.get());
            tickLegacyWireHost(level, largePylonPos, largePylon, ModBlockEntities.RED_PYLON_LARGE.get());
            tickLegacyWireHost(level, substationPos, substation, ModBlockEntities.SUBSTATION.get());
            HbmEnergyNodespace.tick(level);

            List<HbmLegacyWireNodeBlockEntity> hosts = List.of(connector, smallPylon, mediumPylon, largePylon, substation);
            List<HbmEnergyNode> oldNodes = hosts.stream().map(HbmLegacyWireNodeBlockEntity::getEnergyNode).toList();
            assertTrue(oldNodes.stream().allMatch(node -> node != null && node.getPowerNet() != null),
                    "real connector, pylon and substation hosts establish their source-backed nodes before legacy reap");

            int expectedNodes = 0;
            int expectedNetworks = 0;
            for (ServerLevel serverLevel : level.getServer().getAllLevels()) {
                HbmUninosDiagnostics.Totals totals = HbmUninosDiagnostics.totals(serverLevel);
                HbmEnergyNodespace.Diagnostics energyDiagnostics = HbmEnergyNodespace.getDiagnostics(serverLevel);
                HbmFluidNodespace.Diagnostics fluidDiagnostics = HbmFluidNodespace.getDiagnostics(serverLevel);
                expectedNodes += totals.uniqueNodes() + energyDiagnostics.uniqueNodes() + fluidDiagnostics.uniqueNodes();
                expectedNetworks += totals.networks() + energyDiagnostics.networks() + fluidDiagnostics.networks();
            }
            assertCommandVisibleMessage(level, connectorPos, "ntmreapnetworks", expectedNodes,
                    "UNINOS nodespaces cleared: nodes=" + expectedNodes + " networks=" + expectedNetworks);

            assertTrue(oldNodes.stream().allMatch(HbmEnergyNode::isExpired),
                    "legacy reap expires every real connector, pylon and substation node");
            assertTrue(positions.stream().allMatch(pos -> HbmEnergyNodespace.getNode(level, pos) == null),
                    "legacy reap clears every real wire-host nodespace mapping");

            tickLegacyWireHost(level, connectorPos, connector, ModBlockEntities.RED_CONNECTOR.get());
            tickLegacyWireHost(level, smallPylonPos, smallPylon, ModBlockEntities.RED_PYLON.get());
            tickLegacyWireHost(level, mediumPylonPos, mediumPylon, ModBlockEntities.RED_PYLON_MEDIUM.get());
            tickLegacyWireHost(level, largePylonPos, largePylon, ModBlockEntities.RED_PYLON_LARGE.get());
            tickLegacyWireHost(level, substationPos, substation, ModBlockEntities.SUBSTATION.get());
            List<HbmEnergyNode> restoredNodes = hosts.stream().map(HbmLegacyWireNodeBlockEntity::getEnergyNode).toList();
            assertTrue(restoredNodes.stream().allMatch(node -> node != null && !node.isExpired())
                    && restoredNodes.stream().noneMatch(oldNodes::contains),
                    "real wire-host tickers recreate distinct nodes after legacy reap");
            assertTrue(positions.stream().allMatch(pos -> HbmEnergyNodespace.getNode(level, pos) != null),
                    "real wire-host tickers restore every nodespace mapping");

            HbmEnergyNodespace.tick(level);
            assertTrue(restoredNodes.stream().allMatch(node -> node.getPowerNet() != null),
                    "recovered connector, pylon and substation nodes join networks on the following legacy START update");
        } finally {
            for (BlockPos pos : positions) {
                level.removeBlock(pos, false);
            }
            HbmEnergyNodespace.unloadLevel(level);
        }
        helper.succeed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosFoundry")
    public static void foundryChannelUsesSharedUninosMaterialState(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        HbmUninosNodespaces.unloadLevel(level);
        try {
            BlockPos leftPos = helper.absolutePos(new BlockPos(1, 2, 1));
            BlockPos rightPos = leftPos.east();
            BlockState channelState = ModBlocks.FOUNDRY_CHANNEL.get().defaultBlockState();
            level.setBlock(leftPos, channelState, Block.UPDATE_ALL);
            level.setBlock(rightPos, channelState, Block.UPDATE_ALL);
            if (!(level.getBlockEntity(leftPos) instanceof FoundryChannelBlockEntity left)
                    || !(level.getBlockEntity(rightPos) instanceof FoundryChannelBlockEntity right)) {
                throw new AssertionError("Foundry channel fixture did not create both block entities");
            }

            FoundryChannelBlockEntity.serverTick(level, leftPos, level.getBlockState(leftPos), left);
            FoundryChannelBlockEntity.serverTick(level, rightPos, level.getBlockState(rightPos), right);
            FoundryNodespace.tick(level);
            assertEquals(2, FoundryNodespace.diagnostics(level).core().uniqueNodes(),
                    "adjacent foundry channels create two real UNINOS nodes");
            assertEquals(1, FoundryNodespace.diagnostics(level).core().networks(),
                    "adjacent foundry channels join one Foundry UNINOS network");

            MaterialStack copper = new MaterialStack(Mats.MAT_COPPER, 120);
            assertTrue(left.canAcceptPartialPour(level, leftPos, Vec3.atCenterOf(leftPos), Direction.UP, copper),
                    "empty foundry channel accepts a source-backed top pour");
            assertTrue(left.pour(level, leftPos, Vec3.atCenterOf(leftPos), Direction.UP, copper) == null,
                    "foundry channel accepts the complete copper pour");
            assertSame(Mats.MAT_COPPER, left.getMaterialType(),
                    "poured channel stores the poured material");
            assertFalse(right.canAcceptPartialPour(level, rightPos, Vec3.atCenterOf(rightPos), Direction.UP,
                    new MaterialStack(Mats.MAT_IRON, 1)),
                    "joined foundry network rejects a different material while copper is present");

            for (int tick = 0; tick < 5; tick++) {
                FoundryChannelBlockEntity.serverTick(level, leftPos, level.getBlockState(leftPos), left);
            }
            assertTrue(right.getAmount() > 0,
                    "foundry channel transfers or swaps molten material after the legacy five-tick interval");
            assertEquals(120, left.getAmount() + right.getAmount(),
                    "foundry channel transfer preserves the total molten amount");
            assertSame(Mats.MAT_COPPER, FoundryNodespace.getNode(level, rightPos).getMaterial(),
                    "destination Foundry UNINOS node tracks its received material");

            level.removeBlock(rightPos, false);
            FoundryNodespace.tick(level);
            assertEquals(1, FoundryNodespace.diagnostics(level).core().uniqueNodes(),
                    "removing a channel releases its Foundry UNINOS node");
            assertEquals(1, FoundryNodespace.diagnostics(level).core().networks(),
                    "surviving channel rebuilds as a one-node Foundry network");
        } finally {
            HbmUninosNodespaces.unloadLevel(level);
        }
        helper.succeed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosRebar")
    public static void rebarUsesUninosLowestLayerTransferContract(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        HbmFluidNodespace.unloadLevel(level);
        HbmUninosNodespaces.unloadLevel(level);
        try {
            BlockPos lowerPos = helper.absolutePos(new BlockPos(1, 2, 1));
            BlockPos upperPos = lowerPos.above();
            BlockState rebarState = ModBlocks.legacyBlock("rebar").get().defaultBlockState();
            level.setBlock(lowerPos, rebarState, Block.UPDATE_ALL);
            level.setBlock(upperPos, rebarState, Block.UPDATE_ALL);
            if (!(level.getBlockEntity(lowerPos) instanceof RebarBlockEntity lower)
                    || !(level.getBlockEntity(upperPos) instanceof RebarBlockEntity upper)) {
                throw new AssertionError("Rebar fixture did not create both block entities");
            }
            BlockPos concretePipePos = lowerPos.north();
            level.setBlock(concretePipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(concretePipePos) instanceof FluidPipeBlockEntity concretePipe)) {
                throw new AssertionError("Rebar fixture did not create its concrete pipe");
            }
            concretePipe.setFluidType(HbmFluids.CONCRETE);
            refreshFluidNodeAt(level, concretePipePos);

            RebarBlockEntity.serverTick(level, lowerPos, level.getBlockState(lowerPos), lower);
            RebarBlockEntity.serverTick(level, upperPos, level.getBlockState(upperPos), upper);
            RebarNodespace.tick(level);
            HbmFluidNodespace.tick(level);
            assertTrue(HbmFluidNodespace.getNode(level, lowerPos, HbmFluids.CONCRETE) == null,
                    "rebar keeps its Rebar UNINOS node without creating a separate core fluid node");
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, concretePipePos, HbmFluids.CONCRETE),
                    "rebar subscribes to the legacy adjacent concrete pipe");
            assertEquals(2, RebarNodespace.diagnostics(level).core().uniqueNodes(),
                    "stacked rebar creates two real UNINOS nodes");
            assertEquals(1, RebarNodespace.diagnostics(level).core().networks(),
                    "stacked rebar joins one Rebar UNINOS network");

            assertEquals(50L, upper.transferFluid(HbmFluids.CONCRETE, 0, 100L),
                    "rebar accepts only the legacy 50-unit cap for one lowest-layer link");
            assertEquals(50, lower.getProgress(),
                    "rebar sends concrete to the lowest linked rebar first");
            assertEquals(0, upper.getProgress(),
                    "higher rebar remains untouched while a lower rebar needs concrete");
            assertEquals(0L, upper.transferFluid(HbmFluids.CONCRETE, 0, 50L),
                    "second capped transfer fills the same lowest rebar without loss");
            assertEquals(100, lower.getProgress(),
                    "lowest rebar receives both capped transfers");
            TestFluidProvider concreteSource = new TestFluidProvider(HbmFluids.CONCRETE, 50);
            assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, concretePipePos, Direction.SOUTH,
                    HbmFluids.CONCRETE, concreteSource), "test source subscribes to the rebar concrete pipe");
            assertTrue(HbmFluidNodespace.getNode(level, concretePipePos, HbmFluids.CONCRETE).getFluidNet().update() > 0L,
                    "rebar adjacent concrete network transfers into its lowest Rebar UNINOS link");
            assertTrue(lower.getProgress() > 100,
                    "rebar accepts concrete through the source-backed adjacent Fluid Mk2 port");

            level.removeBlock(lowerPos, false);
            RebarNodespace.tick(level);
            assertEquals(1, RebarNodespace.diagnostics(level).core().uniqueNodes(),
                    "removing lower rebar releases its Rebar UNINOS node");
            assertEquals(0L, upper.transferFluid(HbmFluids.CONCRETE, 0, 50L),
                    "remaining rebar rebuilds and accepts concrete after topology removal");
            assertEquals(50, upper.getProgress(),
                    "remaining rebar becomes the new lowest transfer target");
        } finally {
            HbmFluidNodespace.unloadLevel(level);
            HbmUninosNodespaces.unloadLevel(level);
        }
        helper.succeed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosFluidTank")
    public static void fluidTankModesUseLegacyUninosNodeAndPortContracts(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        HbmFluidNodespace.unloadLevel(level);
        BlockPos tankPos = helper.absolutePos(new BlockPos(5, 2, 5));
        BlockPos pipePos = tankPos.offset(2, 0, -1);
        List<BlockPos> nodeProxyPositions = List.of(
                tankPos.offset(1, 0, -1),
                tankPos.offset(1, 0, 1),
                tankPos.offset(-1, 0, -1),
                tankPos.offset(-1, 0, 1));
        clearBox(level, tankPos.offset(-3, -1, -3), tankPos.offset(3, 3, 3));
        try {
            level.setBlock(tankPos, ModBlocks.MACHINE_FLUIDTANK.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(tankPos) instanceof FluidTankBlockEntity tank)) {
                throw new AssertionError("No machine_fluidtank block entity at " + tankPos);
            }
            level.setBlock(pipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(pipePos) instanceof FluidPipeBlockEntity pipe)) {
                throw new AssertionError("No fluid_duct_neo block entity at " + pipePos);
            }
            pipe.setFluidType(HbmFluids.DIESEL);
            refreshFluidNodeAt(level, pipePos);
            HbmFluidUtil.FluidPort pipePort = legacyRemoteFluidPorts(tank).stream()
                    .filter(port -> port.connectorPos(tankPos).equals(pipePos))
                    .findFirst()
                    .orElseThrow(() -> new AssertionError("fluid tank did not expose the selected legacy remote port"));

            assertTrue(tank.setIdentifiedType(HbmFluids.DIESEL),
                    "fluid tank accepts the legacy-selected diesel type");
            tank.setMode(FluidTankBlockEntity.MODE_BUFFER);
            FluidTankBlockEntity.serverTick(level, tankPos, level.getBlockState(tankPos), tank);
            HbmFluidNodespace.tick(level);
            HbmFluidNode bufferNode = tank.getFluidNode();
            assertTrue(bufferNode != null && !bufferNode.isExpired(),
                    "buffer-mode fluid tank creates a live local UNINOS node");
            assertSame(bufferNode, HbmFluidNodespace.getNode(level, tankPos, HbmFluids.DIESEL),
                    "buffer-mode tank registers its node at the real machine core");
            for (BlockPos proxyPos : nodeProxyPositions) {
                assertSame(bufferNode, HbmFluidNodespace.getNode(level, proxyPos, HbmFluids.DIESEL),
                        "buffer-mode tank registers the source-backed FluidNode at each internal proxy position");
            }
            assertSame(bufferNode.getFluidNet(), HbmFluidNodespace.getNode(level, pipePos, HbmFluids.DIESEL).getFluidNet(),
                    "buffer-mode tank joins its configured legacy remote pipe port");
            assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, pipePos, HbmFluids.DIESEL),
                    "buffer-mode tank subscribes as a diesel provider");
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, pipePos, HbmFluids.DIESEL),
                    "buffer-mode tank subscribes as a diesel receiver");

            tank.setMode(FluidTankBlockEntity.MODE_INPUT);
            FluidTankBlockEntity.serverTick(level, tankPos, level.getBlockState(tankPos), tank);
            HbmFluidNodespace.tick(level);
            assertTrue(tank.getFluidNode() == null,
                    "input-mode tank releases its local buffer node");
            assertTrue(bufferNode.isExpired(),
                    "input-mode tank expires the tracked multi-position FluidNode instance");
            assertTrue(HbmFluidNodespace.getNode(level, tankPos, HbmFluids.DIESEL) == null,
                    "input-mode tank clears the FluidNode core mapping");
            for (BlockPos proxyPos : nodeProxyPositions) {
                assertTrue(HbmFluidNodespace.getNode(level, proxyPos, HbmFluids.DIESEL) == null,
                        "input-mode tank clears every internal FluidNode proxy mapping");
            }
            assertEquals(0, HbmFluidNodespace.getNetworkProviderCount(level, pipePos, HbmFluids.DIESEL),
                    "input-mode tank removes its provider subscription");
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, pipePos, HbmFluids.DIESEL),
                    "input-mode tank keeps only its remote receiver subscription");
            TestFluidProvider inputSource = new TestFluidProvider(HbmFluids.DIESEL, 500, tank.getTank().getPressure());
            assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, pipePos, pipePort.connectorSide(), HbmFluids.DIESEL,
                    inputSource), "test source subscribes to the fluid-tank input duct");
            assertTrue(HbmFluidNodespace.getNode(level, pipePos, HbmFluids.DIESEL).getFluidNet().update() > 0L,
                    "input-mode tank receives diesel through its legacy remote port");
            assertTrue(tank.getTank().getFill() > 0, "input-mode tank stores diesel received through Fluid Mk2");
            assertTrue(HbmFluidUtil.unsubscribeProviderFromNetwork(level, pipePos, pipePort.connectorSide(),
                    HbmFluids.DIESEL, inputSource),
                    "input test source detaches before its duct is replaced");

            // Old input mode re-added its remote receiver on every tick.  A
            // same-position duct replacement must therefore recover through
            // the real block-entity ticker, rather than a test-only helper.
            level.removeBlock(pipePos, false);
            level.setBlock(pipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(pipePos) instanceof FluidPipeBlockEntity replacementInputPipe)) {
                throw new AssertionError("fluid-tank input fixture did not recreate its remote duct");
            }
            replacementInputPipe.setFluidType(HbmFluids.DIESEL);
            refreshFluidNodeAt(level, pipePos);
            HbmFluidNodespace.tick(level);
            FluidTankBlockEntity.serverTick(level, tankPos, level.getBlockState(tankPos), tank);
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, pipePos, HbmFluids.DIESEL),
                    "input-mode tank restores its replaced remote receiver on the next legacy tick");
            TestFluidProvider replacementInputSource = new TestFluidProvider(HbmFluids.DIESEL, 500,
                    tank.getTank().getPressure());
            assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, pipePos, pipePort.connectorSide(),
                    HbmFluids.DIESEL, replacementInputSource),
                    "test source subscribes to the replacement fluid-tank input duct");
            assertTrue(HbmFluidNodespace.getNode(level, pipePos, HbmFluids.DIESEL).getFluidNet().update() > 0L,
                    "replacement input duct transfers diesel on the next legacy tick");
            assertTrue(HbmFluidUtil.unsubscribeProviderFromNetwork(level, pipePos, pipePort.connectorSide(),
                    HbmFluids.DIESEL, replacementInputSource),
                    "replacement input test source detaches before output-mode verification");

            tank.setMode(FluidTankBlockEntity.MODE_OUTPUT);
            FluidTankBlockEntity.serverTick(level, tankPos, level.getBlockState(tankPos), tank);
            HbmFluidNodespace.tick(level);
            assertTrue(tank.getFluidNode() == null,
                    "output-mode tank remains a remote-port consumer without a local node");
            assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, pipePos, HbmFluids.DIESEL),
                    "output-mode tank subscribes as a remote diesel provider");
            assertEquals(0, HbmFluidNodespace.getNetworkReceiverCount(level, pipePos, HbmFluids.DIESEL),
                    "output-mode tank removes the receiver subscription");
            TestFluidReceiver outputSink = new TestFluidReceiver(HbmFluids.DIESEL, 500);
            assertTrue(HbmFluidUtil.subscribeReceiverToNetwork(level, pipePos, pipePort.connectorSide(),
                    HbmFluids.DIESEL, outputSink), "test sink subscribes to the fluid-tank output duct");
            assertTrue(HbmFluidNodespace.getNode(level, pipePos, HbmFluids.DIESEL).getFluidNet().update() > 0L,
                    "output-mode tank delivers diesel through its legacy remote port");
            assertTrue(outputSink.getStoredFluid() > 0, "output-mode tank transfers diesel through Fluid Mk2");
            assertTrue(HbmFluidUtil.unsubscribeReceiverFromNetwork(level, pipePos, pipePort.connectorSide(),
                    HbmFluids.DIESEL, outputSink),
                    "output test sink detaches before its duct is replaced");

            // Mode 2 was likewise a per-tick old provider pass.  Keep the
            // mode-1 local-node contract separate while proving remote output
            // recovers immediately after the duct is replaced.
            level.removeBlock(pipePos, false);
            level.setBlock(pipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(pipePos) instanceof FluidPipeBlockEntity replacementOutputPipe)) {
                throw new AssertionError("fluid-tank output fixture did not recreate its remote duct");
            }
            replacementOutputPipe.setFluidType(HbmFluids.DIESEL);
            refreshFluidNodeAt(level, pipePos);
            HbmFluidNodespace.tick(level);
            tank.getTank().setFill(500);
            FluidTankBlockEntity.serverTick(level, tankPos, level.getBlockState(tankPos), tank);
            assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, pipePos, HbmFluids.DIESEL),
                    "output-mode tank restores its replaced remote provider on the next legacy tick");
            TestFluidReceiver replacementOutputSink = new TestFluidReceiver(HbmFluids.DIESEL, 500);
            assertTrue(HbmFluidUtil.subscribeReceiverToNetwork(level, pipePos, pipePort.connectorSide(),
                    HbmFluids.DIESEL, replacementOutputSink),
                    "test sink subscribes to the replacement fluid-tank output duct");
            assertTrue(HbmFluidNodespace.getNode(level, pipePos, HbmFluids.DIESEL).getFluidNet().update() > 0L,
                    "replacement output duct transfers diesel on the next legacy tick");
            assertTrue(replacementOutputSink.getStoredFluid() > 0,
                    "output-mode tank delivers diesel through its restored remote port");
            assertTrue(HbmFluidUtil.unsubscribeReceiverFromNetwork(level, pipePos, pipePort.connectorSide(),
                    HbmFluids.DIESEL, replacementOutputSink),
                    "replacement output test sink detaches before buffer-mode verification");

            tank.setMode(FluidTankBlockEntity.MODE_BUFFER);
            FluidTankBlockEntity.serverTick(level, tankPos, level.getBlockState(tankPos), tank);
            HbmFluidNodespace.tick(level);
            assertTrue(tank.getFluidNode() != null && !tank.getFluidNode().isExpired(),
                    "returning to buffer mode recreates the local UNINOS node");
            assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, pipePos, HbmFluids.DIESEL),
                    "recreated buffer node restores the provider subscription");
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, pipePos, HbmFluids.DIESEL),
                    "recreated buffer node restores the receiver subscription");
        } finally {
            clearBox(level, tankPos.offset(-3, -1, -3), tankPos.offset(3, 3, 3));
            HbmFluidNodespace.unloadLevel(level);
        }
        helper.succeed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosFluidBarrel")
    public static void fluidBarrelUsesLegacyAdjacentUninosPortContracts(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos barrelPos = helper.absolutePos(new BlockPos(12, 2, 5));
        clearBox(level, barrelPos, barrelPos.offset(2, 0, 1));
        try {
            BlockPos eastPipePos = barrelPos.east();
            BlockPos southPipePos = barrelPos.south();
            BlockPos tankOnlyPortPos = barrelPos.offset(2, 0, -1);
            level.setBlock(barrelPos, ModBlocks.BARREL_PLASTIC.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(eastPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(southPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(tankOnlyPortPos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(barrelPos) instanceof FluidBarrelBlockEntity barrel)
                    || !(level.getBlockEntity(eastPipePos) instanceof FluidPipeBlockEntity eastPipe)
                    || !(level.getBlockEntity(southPipePos) instanceof FluidPipeBlockEntity southPipe)
                    || !(level.getBlockEntity(tankOnlyPortPos) instanceof FluidPipeBlockEntity tankOnlyPipe)) {
                throw new AssertionError("Fluid barrel fixture did not create its required block entities");
            }
            eastPipe.setFluidType(HbmFluids.DIESEL);
            southPipe.setFluidType(HbmFluids.DIESEL);
            tankOnlyPipe.setFluidType(HbmFluids.DIESEL);
            refreshFluidNodeAt(level, eastPipePos);
            refreshFluidNodeAt(level, southPipePos);
            refreshFluidNodeAt(level, tankOnlyPortPos);

            assertTrue(barrel.setIdentifiedType(HbmFluids.DIESEL),
                    "fluid barrel accepts the legacy-selected diesel type");
            barrel.setMode(FluidTankBlockEntity.MODE_BUFFER);
            FluidBarrelBlockEntity.serverTick(level, barrelPos, level.getBlockState(barrelPos), barrel);
            HbmFluidNodespace.tick(level);
            HbmFluidNode barrelNode = barrel.getFluidNode();
            assertTrue(barrelNode != null && !barrelNode.isExpired(),
                    "buffer-mode fluid barrel creates its source-backed local UNINOS node");
            assertSame(barrelNode.getFluidNet(), HbmFluidNodespace.getNode(level, eastPipePos, HbmFluids.DIESEL).getFluidNet(),
                    "fluid barrel joins its adjacent east diesel port");
            assertSame(barrelNode.getFluidNet(), HbmFluidNodespace.getNode(level, southPipePos, HbmFluids.DIESEL).getFluidNet(),
                    "fluid barrel joins its adjacent south diesel port");
            assertTrue(barrelNode.getFluidNet() != HbmFluidNodespace.getNode(level, tankOnlyPortPos, HbmFluids.DIESEL).getFluidNet(),
                    "fluid barrel does not invent machine_fluidtank's distant legacy port layout");

            barrel.setMode(FluidTankBlockEntity.MODE_INPUT);
            FluidBarrelBlockEntity.serverTick(level, barrelPos, level.getBlockState(barrelPos), barrel);
            HbmFluidNodespace.tick(level);
            assertTrue(barrel.getFluidNode() == null,
                    "input-mode fluid barrel releases its local buffer node");
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, eastPipePos, HbmFluids.DIESEL),
                    "input-mode fluid barrel subscribes to its adjacent east port");
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, southPipePos, HbmFluids.DIESEL),
                    "input-mode fluid barrel subscribes to its adjacent south port");
            assertEquals(0, HbmFluidNodespace.getNetworkReceiverCount(level, tankOnlyPortPos, HbmFluids.DIESEL),
                    "input-mode fluid barrel does not subscribe to machine_fluidtank-only ports");
            HbmFluidUtil.FluidPort eastPort = legacyRemoteFluidPorts(barrel).stream()
                    .filter(port -> port.connectorPos(barrelPos).equals(eastPipePos))
                    .findFirst()
                    .orElseThrow(() -> new AssertionError("fluid barrel did not expose its east legacy port"));
            TestFluidProvider inputSource = new TestFluidProvider(HbmFluids.DIESEL, 500,
                    barrel.getTank().getPressure());
            assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, eastPipePos, eastPort.connectorSide(),
                    HbmFluids.DIESEL, inputSource),
                    "test source subscribes to the fluid-barrel input duct");
            assertTrue(HbmFluidNodespace.getNode(level, eastPipePos, HbmFluids.DIESEL).getFluidNet().update() > 0L,
                    "input-mode fluid barrel receives diesel through its adjacent legacy port");
            assertTrue(barrel.getTank().getFill() > 0,
                    "input-mode fluid barrel stores diesel received through Fluid Mk2");
            assertTrue(HbmFluidUtil.unsubscribeProviderFromNetwork(level, eastPipePos, eastPort.connectorSide(),
                    HbmFluids.DIESEL, inputSource),
                    "fluid-barrel input test source detaches before its duct is replaced");

            level.removeBlock(eastPipePos, false);
            level.setBlock(eastPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(eastPipePos) instanceof FluidPipeBlockEntity replacementInputPipe)) {
                throw new AssertionError("fluid-barrel input fixture did not recreate its adjacent duct");
            }
            replacementInputPipe.setFluidType(HbmFluids.DIESEL);
            refreshFluidNodeAt(level, eastPipePos);
            HbmFluidNodespace.tick(level);
            FluidBarrelBlockEntity.serverTick(level, barrelPos, level.getBlockState(barrelPos), barrel);
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, eastPipePos, HbmFluids.DIESEL),
                    "input-mode fluid barrel restores its replaced receiver on the next legacy tick");
            TestFluidProvider replacementInputSource = new TestFluidProvider(HbmFluids.DIESEL, 500,
                    barrel.getTank().getPressure());
            assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, eastPipePos, eastPort.connectorSide(),
                    HbmFluids.DIESEL, replacementInputSource),
                    "test source subscribes to the replacement fluid-barrel input duct");
            assertTrue(HbmFluidNodespace.getNode(level, eastPipePos, HbmFluids.DIESEL).getFluidNet().update() > 0L,
                    "replacement barrel input duct transfers diesel on the next legacy tick");
            assertTrue(HbmFluidUtil.unsubscribeProviderFromNetwork(level, eastPipePos, eastPort.connectorSide(),
                    HbmFluids.DIESEL, replacementInputSource),
                    "replacement input test source detaches before barrel output verification");

            barrel.setMode(FluidTankBlockEntity.MODE_OUTPUT);
            FluidBarrelBlockEntity.serverTick(level, barrelPos, level.getBlockState(barrelPos), barrel);
            HbmFluidNodespace.tick(level);
            assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, eastPipePos, HbmFluids.DIESEL),
                    "output-mode fluid barrel subscribes to its adjacent east port");
            assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, southPipePos, HbmFluids.DIESEL),
                    "output-mode fluid barrel subscribes to its adjacent south port");
            assertEquals(0, HbmFluidNodespace.getNetworkProviderCount(level, tankOnlyPortPos, HbmFluids.DIESEL),
                    "output-mode fluid barrel keeps machine_fluidtank-only ports disconnected");
            HbmFluidUtil.FluidPort southPort = legacyRemoteFluidPorts(barrel).stream()
                    .filter(port -> port.connectorPos(barrelPos).equals(southPipePos))
                    .findFirst()
                    .orElseThrow(() -> new AssertionError("fluid barrel did not expose its south legacy port"));
            TestFluidReceiver outputSink = new TestFluidReceiver(HbmFluids.DIESEL, 500);
            assertTrue(HbmFluidUtil.subscribeReceiverToNetwork(level, southPipePos, southPort.connectorSide(),
                    HbmFluids.DIESEL, outputSink),
                    "test sink subscribes to the fluid-barrel output duct");
            assertTrue(HbmFluidNodespace.getNode(level, southPipePos, HbmFluids.DIESEL).getFluidNet().update() > 0L,
                    "output-mode fluid barrel delivers diesel through its adjacent legacy port");
            assertTrue(outputSink.getStoredFluid() > 0,
                    "output-mode fluid barrel transfers diesel through Fluid Mk2");
            assertTrue(HbmFluidUtil.unsubscribeReceiverFromNetwork(level, southPipePos, southPort.connectorSide(),
                    HbmFluids.DIESEL, outputSink),
                    "fluid-barrel output test sink detaches before its duct is replaced");

            level.removeBlock(southPipePos, false);
            level.setBlock(southPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(southPipePos) instanceof FluidPipeBlockEntity replacementOutputPipe)) {
                throw new AssertionError("fluid-barrel output fixture did not recreate its adjacent duct");
            }
            replacementOutputPipe.setFluidType(HbmFluids.DIESEL);
            refreshFluidNodeAt(level, southPipePos);
            HbmFluidNodespace.tick(level);
            barrel.getTank().setFill(500);
            FluidBarrelBlockEntity.serverTick(level, barrelPos, level.getBlockState(barrelPos), barrel);
            assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, southPipePos, HbmFluids.DIESEL),
                    "output-mode fluid barrel restores its replaced provider on the next legacy tick");
            TestFluidReceiver replacementOutputSink = new TestFluidReceiver(HbmFluids.DIESEL, 500);
            assertTrue(HbmFluidUtil.subscribeReceiverToNetwork(level, southPipePos, southPort.connectorSide(),
                    HbmFluids.DIESEL, replacementOutputSink),
                    "test sink subscribes to the replacement fluid-barrel output duct");
            assertTrue(HbmFluidNodespace.getNode(level, southPipePos, HbmFluids.DIESEL).getFluidNet().update() > 0L,
                    "replacement barrel output duct transfers diesel on the next legacy tick");
            assertTrue(replacementOutputSink.getStoredFluid() > 0,
                    "output-mode fluid barrel delivers diesel through its restored adjacent port");
        } finally {
            clearBox(level, barrelPos, barrelPos.offset(2, 0, 1));
        }
        helper.succeed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosNodeUnloadLifecycle")
    public static void networkBlockEntitiesKeepNodesOnChunkUnloadAndDestroyThemOnRemoval(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        HbmEnergyNodespace.unloadLevel(level);
        HbmFluidNodespace.unloadLevel(level);
        PneumaticNodespace.unloadLevel(level);
        BlockPos energyPos = helper.absolutePos(new BlockPos(2, 2, 2));
        BlockPos fluidPos = energyPos.east(3);
        BlockPos pneumaticPos = fluidPos.east(3);
        try {
            clearBox(level, energyPos, pneumaticPos);
            level.setBlock(energyPos, ModBlocks.RED_CABLE.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(fluidPos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(pneumaticPos, ModBlocks.PNEUMATIC_TUBE.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(energyPos) instanceof HbmEnergyNodeBlockEntity energy)
                    || !(level.getBlockEntity(fluidPos) instanceof FluidPipeBlockEntity fluid)
                    || !(level.getBlockEntity(pneumaticPos) instanceof PneumaticTubeBlockEntity pneumatic)) {
                throw new AssertionError("node-unload fixture did not create Energy, Fluid, and Pneumatic node hosts");
            }

            fluid.setFluidType(HbmFluids.WATER);
            refreshEnergyNodeAt(level, energyPos);
            refreshFluidNodeAt(level, fluidPos);
            pneumatic.refreshPneumaticNode();
            HbmEnergyNode energyNode = requireEnergyNodeAt(level, energyPos);
            assertTrue(HbmFluidNodespace.getNode(level, fluidPos, HbmFluids.WATER) != null,
                    "real Fluid node host creates its typed UNINOS node before chunk unload");
            assertTrue(PneumaticNodespace.getNode(level, pneumaticPos) != null,
                    "real Pneumatic node host creates its UNINOS node before chunk unload");

            energy.onChunkUnloaded();
            fluid.onChunkUnloaded();
            pneumatic.onChunkUnloaded();
            assertTrue(!energyNode.isExpired() && HbmEnergyNodespace.getNode(level, energyPos) == energyNode,
                    "Energy node host chunk unload retains its existing UNINOS node");
            assertTrue(HbmFluidNodespace.getNode(level, fluidPos, HbmFluids.WATER) != null,
                    "Fluid node host chunk unload retains its typed UNINOS node");
            assertTrue(PneumaticNodespace.getNode(level, pneumaticPos) != null,
                    "Pneumatic tube chunk unload retains its UNINOS node");

            level.removeBlock(energyPos, false);
            level.removeBlock(fluidPos, false);
            level.removeBlock(pneumaticPos, false);
            assertTrue(HbmEnergyNodespace.getNode(level, energyPos) == null,
                    "removing the Energy host remains the explicit node-destruction boundary");
            assertTrue(HbmFluidNodespace.getNode(level, fluidPos, HbmFluids.WATER) == null,
                    "removing the Fluid host remains the explicit typed-node destruction boundary");
            assertTrue(PneumaticNodespace.getNode(level, pneumaticPos) == null,
                    "removing the Pneumatic host remains the explicit node-destruction boundary");
        } finally {
            level.removeBlock(helper.absolutePos(new BlockPos(1, 4, 1)), false);
            HbmEnergyNodespace.unloadLevel(level);
            HbmFluidNodespace.unloadLevel(level);
            PneumaticNodespace.unloadLevel(level);
        }
        helper.succeed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosIcfPress")
    public static void icfPressUsesLegacyAdjacentReceiverPortsWithoutFluidNodes(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        HbmFluidNodespace.unloadLevel(level);
        try {
            BlockPos pressPos = helper.absolutePos(new BlockPos(8, 2, 8));
            BlockPos deuteriumNorthPos = pressPos.north();
            BlockPos deuteriumSouthPos = pressPos.south();
            BlockPos deuteriumWestPos = pressPos.west();
            BlockPos tritiumEastPos = pressPos.east();
            BlockPos tritiumUpPos = pressPos.above();
            BlockPos tritiumDownPos = pressPos.below();
            level.setBlock(pressPos, ModBlocks.MACHINE_ICF_PRESS.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(deuteriumNorthPos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(deuteriumSouthPos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(deuteriumWestPos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(tritiumEastPos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(tritiumUpPos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(tritiumDownPos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(pressPos) instanceof ICFPressBlockEntity press)
                    || !(level.getBlockEntity(deuteriumNorthPos) instanceof FluidPipeBlockEntity deuteriumNorth)
                    || !(level.getBlockEntity(deuteriumSouthPos) instanceof FluidPipeBlockEntity deuteriumSouth)
                    || !(level.getBlockEntity(deuteriumWestPos) instanceof FluidPipeBlockEntity deuteriumWest)
                    || !(level.getBlockEntity(tritiumEastPos) instanceof FluidPipeBlockEntity tritiumEast)
                    || !(level.getBlockEntity(tritiumUpPos) instanceof FluidPipeBlockEntity tritiumUp)
                    || !(level.getBlockEntity(tritiumDownPos) instanceof FluidPipeBlockEntity tritiumDown)) {
                throw new AssertionError("ICF press fixture did not create its required block entities");
            }
            deuteriumNorth.setFluidType(HbmFluids.DEUTERIUM);
            deuteriumSouth.setFluidType(HbmFluids.DEUTERIUM);
            deuteriumWest.setFluidType(HbmFluids.DEUTERIUM);
            tritiumEast.setFluidType(HbmFluids.TRITIUM);
            tritiumUp.setFluidType(HbmFluids.TRITIUM);
            tritiumDown.setFluidType(HbmFluids.TRITIUM);
            refreshFluidNodeAt(level, deuteriumNorthPos);
            refreshFluidNodeAt(level, deuteriumSouthPos);
            refreshFluidNodeAt(level, deuteriumWestPos);
            refreshFluidNodeAt(level, tritiumEastPos);
            refreshFluidNodeAt(level, tritiumUpPos);
            refreshFluidNodeAt(level, tritiumDownPos);

            ICFPressBlockEntity.serverTick(level, pressPos, level.getBlockState(pressPos), press);
            HbmFluidNodespace.tick(level);
            assertTrue(HbmFluidNodespace.getNode(level, pressPos, HbmFluids.DEUTERIUM) == null,
                    "icf press receives deuterium through remote ports without a core fluid node");
            assertTrue(HbmFluidNodespace.getNode(level, pressPos, HbmFluids.TRITIUM) == null,
                    "icf press receives tritium through remote ports without a core fluid node");
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, deuteriumNorthPos, HbmFluids.DEUTERIUM),
                    "icf press subscribes to its north deuterium port");
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, deuteriumSouthPos, HbmFluids.DEUTERIUM),
                    "icf press subscribes to its south deuterium port");
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, deuteriumWestPos, HbmFluids.DEUTERIUM),
                    "icf press subscribes to its west deuterium port");
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, tritiumEastPos, HbmFluids.TRITIUM),
                    "icf press subscribes to its east tritium port");
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, tritiumUpPos, HbmFluids.TRITIUM),
                    "icf press subscribes to its upper tritium port");
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, tritiumDownPos, HbmFluids.TRITIUM),
                    "icf press subscribes to its lower tritium port");
            assertEquals(0, HbmFluidNodespace.getNetworkReceiverCount(level, deuteriumNorthPos, HbmFluids.TRITIUM),
                    "icf press does not subscribe a tritium receiver to a deuterium pipe");
            assertEquals(0, HbmFluidNodespace.getNetworkReceiverCount(level, tritiumEastPos, HbmFluids.DEUTERIUM),
                    "icf press does not subscribe a deuterium receiver to a tritium pipe");

            TestFluidProvider deuteriumSource = new TestFluidProvider(HbmFluids.DEUTERIUM, 1_000);
            assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, deuteriumNorthPos, Direction.SOUTH,
                    HbmFluids.DEUTERIUM, deuteriumSource),
                    "test deuterium source subscribes to the ICF press north pipe");
            HbmFluidNet deuteriumNet = HbmFluidNodespace.getNode(level, deuteriumNorthPos, HbmFluids.DEUTERIUM)
                    .getFluidNet();
            assertTrue(deuteriumNet.update() > 0L,
                    "icf press north-port deuterium network transfers fluid");
            assertTrue(press.getDeuteriumTank().getFill() > 0,
                    "icf press receives deuterium through its legacy adjacent receiver port");

            TestFluidProvider tritiumSource = new TestFluidProvider(HbmFluids.TRITIUM, 1_000);
            assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, tritiumEastPos, Direction.WEST,
                    HbmFluids.TRITIUM, tritiumSource),
                    "test tritium source subscribes to the ICF press east pipe");
            HbmFluidNet tritiumNet = HbmFluidNodespace.getNode(level, tritiumEastPos, HbmFluids.TRITIUM)
                    .getFluidNet();
            assertTrue(tritiumNet.update() > 0L,
                    "icf press east-port tritium network transfers fluid");
            assertTrue(press.getTritiumTank().getFill() > 0,
                    "icf press receives tritium through its legacy adjacent receiver port");
        } finally {
            HbmFluidNodespace.unloadLevel(level);
        }
        helper.succeed();
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosCondenser")
    public static void condenserUsesLegacyAdjacentFluidPortsWithoutCoreNodes(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos condenserPos = helper.absolutePos(new BlockPos(12, 2, 5));
        clearBox(level, condenserPos.north(), condenserPos.east());
        try {
            BlockPos spentSteamPipePos = condenserPos.north();
            BlockPos waterPipePos = condenserPos.east();
            level.setBlock(condenserPos, ModBlocks.MACHINE_CONDENSER.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(spentSteamPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(waterPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(condenserPos) instanceof CondenserBlockEntity condenser)
                    || !(level.getBlockEntity(spentSteamPipePos) instanceof FluidPipeBlockEntity spentSteamPipe)
                    || !(level.getBlockEntity(waterPipePos) instanceof FluidPipeBlockEntity waterPipe)) {
                throw new AssertionError("Condenser fixture did not create its required block entities");
            }
            spentSteamPipe.setFluidType(HbmFluids.SPENTSTEAM);
            waterPipe.setFluidType(HbmFluids.WATER);
            refreshFluidNodeAt(level, spentSteamPipePos);
            refreshFluidNodeAt(level, waterPipePos);

            CondenserBlockEntity.serverTick(level, condenserPos, level.getBlockState(condenserPos), condenser);
            HbmFluidNodespace.tick(level);
            assertTrue(HbmFluidNodespace.getNode(level, condenserPos, HbmFluids.SPENTSTEAM) == null,
                    "condenser receives spent steam through remote ports without a core fluid node");
            assertTrue(HbmFluidNodespace.getNode(level, condenserPos, HbmFluids.WATER) == null,
                    "condenser provides water through remote ports without a core fluid node");
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, spentSteamPipePos, HbmFluids.SPENTSTEAM),
                    "condenser subscribes to its adjacent spent-steam input port");
            assertEquals(0, HbmFluidNodespace.getNetworkProviderCount(level, waterPipePos, HbmFluids.WATER),
                    "empty condenser does not subscribe a water provider");

            level.removeBlock(spentSteamPipePos, false);
            level.setBlock(spentSteamPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(spentSteamPipePos) instanceof FluidPipeBlockEntity replacementPipe)) {
                throw new AssertionError("Condenser input replacement did not create its remote duct");
            }
            replacementPipe.setFluidType(HbmFluids.SPENTSTEAM);
            refreshFluidNodeAt(level, spentSteamPipePos);
            HbmFluidNodespace.tick(level);
            CondenserBlockEntity.serverTick(level, condenserPos, level.getBlockState(condenserPos), condenser);
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, spentSteamPipePos,
                    HbmFluids.SPENTSTEAM),
                    "condenser retries its adjacent spent-steam receiver on the next legacy server tick");

            TestFluidProvider spentSteamSource = new TestFluidProvider(HbmFluids.SPENTSTEAM, 100);
            assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, spentSteamPipePos, Direction.SOUTH,
                    HbmFluids.SPENTSTEAM, spentSteamSource),
                    "test spent-steam source subscribes to the condenser input pipe");
            HbmFluidNet spentSteamNet = HbmFluidNodespace.getNode(level, spentSteamPipePos, HbmFluids.SPENTSTEAM)
                    .getFluidNet();
            assertTrue(spentSteamNet.update() > 0L,
                    "condenser adjacent spent-steam network transfers its input fluid");

            TestFluidReceiver waterSink = new TestFluidReceiver(HbmFluids.WATER, 100);
            assertTrue(HbmFluidUtil.subscribeReceiverToNetwork(level, waterPipePos, Direction.WEST,
                    HbmFluids.WATER, waterSink),
                    "test water sink subscribes to the condenser output pipe");
            CondenserBlockEntity.serverTick(level, condenserPos, level.getBlockState(condenserPos), condenser);
            HbmFluidNodespace.tick(level);
            assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, waterPipePos, HbmFluids.WATER),
                    "filled condenser subscribes as a water provider at its adjacent output port");
            assertTrue(waterSink.getStoredFluid() > 0,
                    "condenser converts remote spent steam and delivers water through its adjacent output port");
        } finally {
            clearBox(level, condenserPos.north(), condenserPos.east());
        }
        helper.succeed();
    }

