    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosFuelGenerators")
    public static void fuelGeneratorsUseLegacyRemoteFluidInputsWithoutCoreNodes(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos combustionPos = helper.absolutePos(new BlockPos(4, 2, 4));
        BlockPos dieselPos = helper.absolutePos(new BlockPos(20, 2, 4));
        clearBox(level, combustionPos.offset(-5, -1, -5), dieselPos.offset(5, 1, 5));
        try {
            level.setBlock(combustionPos, ModBlocks.MACHINE_COMBUSTION_ENGINE.get().defaultBlockState(),
                    Block.UPDATE_ALL);
            level.setBlock(dieselPos, ModBlocks.MACHINE_DIESEL.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(combustionPos) instanceof CombustionEngineBlockEntity combustion)
                    || !(level.getBlockEntity(dieselPos) instanceof DieselGeneratorBlockEntity diesel)) {
                throw new AssertionError("Fuel-generator fixture did not create both source-backed block entities");
            }
            assertLegacyRemoteFluidInput(level, combustion, combustion.getTank(), HbmFluids.DIESEL, 4,
                    "combustion engine");
            assertLegacyRemoteFluidInput(level, diesel, diesel.getTank(), HbmFluids.DIESEL, 6,
                    "diesel generator");
            assertLegacyAdjacentFluidReceiverRecoversOnNextTick(level, combustion, combustion.getTank(),
                    HbmFluids.DIESEL, "combustion engine", () -> CombustionEngineBlockEntity.serverTick(level,
                            combustion.getBlockPos(), level.getBlockState(combustion.getBlockPos()), combustion));
            assertLegacyAdjacentFluidReceiverRecoversOnNextTick(level, diesel, diesel.getTank(), HbmFluids.DIESEL,
                    "diesel generator", () -> DieselGeneratorBlockEntity.serverTick(level, diesel.getBlockPos(),
                            level.getBlockState(diesel.getBlockPos()), diesel));

            // TileEntityMachinePolluting exposed its live three smoke tanks, and both generators invoked
            // sendSmoke at every legacy connection position on every server tick. Exercise the shared soot
            // buffer through each real production ticker rather than treating the main diesel tank as smoke.
            assertLegacyRemoteFluidOutput(level, combustion, combustion.getSmokeTanks()[0], HbmFluids.SMOKE, 4,
                    "combustion engine smoke", () -> CombustionEngineBlockEntity.serverTick(level,
                            combustion.getBlockPos(), level.getBlockState(combustion.getBlockPos()), combustion));
            assertLegacyRemoteFluidProviderRecoversOnNextTick(level, combustion, combustion.getSmokeTanks()[0],
                    HbmFluids.SMOKE, "combustion engine smoke", () -> CombustionEngineBlockEntity.serverTick(level,
                            combustion.getBlockPos(), level.getBlockState(combustion.getBlockPos()), combustion));
            assertLegacyRemoteFluidOutput(level, diesel, diesel.getSmokeTanks()[0], HbmFluids.SMOKE, 6,
                    "diesel generator smoke", () -> DieselGeneratorBlockEntity.serverTick(level,
                            diesel.getBlockPos(), level.getBlockState(diesel.getBlockPos()), diesel));
            assertLegacyRemoteFluidProviderRecoversOnNextTick(level, diesel, diesel.getSmokeTanks()[0],
                    HbmFluids.SMOKE, "diesel generator smoke", () -> DieselGeneratorBlockEntity.serverTick(level,
                            diesel.getBlockPos(), level.getBlockState(diesel.getBlockPos()), diesel));
        } finally {
            clearBox(level, combustionPos.offset(-5, -1, -5), dieselPos.offset(5, 1, 5));
        }
        helper.succeed();
    }

