    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosFluidEndpointExpansion")
    public static void fluidPumpAndRefuelerUseAuditedRemotePortsWithoutCoreNodes(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        runOutsideLegacyTwentyTick(helper, () -> {
            BlockPos pumpPos = helper.absolutePos(new BlockPos(4, 2, 4));
            BlockPos refuelerPos = helper.absolutePos(new BlockPos(20, 2, 4));
            BlockPos pumpInputPipePos = pumpPos.west();
            BlockPos pumpOutputPipePos = pumpPos.east();
            BlockPos refuelerInputPipePos = refuelerPos.south();
            clearBox(level, pumpPos.offset(-3, -2, -3), refuelerPos.offset(3, 3, 3));
            try {
            level.setBlock(pumpPos, ModBlocks.FLUID_PUMP.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(refuelerPos, ModBlocks.REFUELER.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(pumpInputPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(pumpOutputPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(pumpPos) instanceof FluidPumpBlockEntity pump)
                    || !(level.getBlockEntity(refuelerPos) instanceof RefuelerBlockEntity refueler)
                    || !(level.getBlockEntity(pumpInputPipePos) instanceof FluidPipeBlockEntity pumpInputPipe)
                    || !(level.getBlockEntity(pumpOutputPipePos) instanceof FluidPipeBlockEntity pumpOutputPipe)) {
                throw new AssertionError("Fluid-pump/refueler fixture did not create its source-backed block entities");
            }

            pump.setIdentifiedType(HbmFluids.WATER);
            pumpInputPipe.setFluidType(HbmFluids.WATER);
            pumpOutputPipe.setFluidType(HbmFluids.WATER);
            refreshFluidNodeAt(level, pumpInputPipePos);
            refreshFluidNodeAt(level, pumpOutputPipePos);
            // The old nodespace update ran at server START, before this machine pass.
            HbmFluidNodespace.tick(level);
            FluidPumpBlockEntity.serverTick(level, pumpPos, level.getBlockState(pumpPos), pump);
            HbmFluidNodespace.tick(level);
            assertTrue(HbmFluidNodespace.getNode(level, pumpPos, HbmFluids.WATER) == null,
                    "fluid pump keeps its old remote ports without an ordinary water core node");
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, pumpInputPipePos, HbmFluids.WATER),
                    "fluid pump subscribes on the old facing-rotation input side");
            assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, pumpOutputPipePos, HbmFluids.WATER),
                    "empty fluid pump keeps its source-backed opposite output provider subscription");

            TestFluidProvider pumpSource = new TestFluidProvider(HbmFluids.WATER, 500);
            assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, pumpInputPipePos, Direction.EAST,
                    HbmFluids.WATER, pumpSource), "test water source subscribes to the fluid pump input pipe");
            HbmFluidNet pumpInputNet = HbmFluidNodespace.getNode(level, pumpInputPipePos, HbmFluids.WATER).getFluidNet();
            assertTrue(pumpInputNet.update() > 0L,
                    "fluid pump accepts water through its source-backed rotated input port: "
                            + describeFluidNet(pumpInputNet));
            assertTrue(pump.getTank().getFill() > 0, "fluid pump receives water from its rotated input port");

            pump.getTank().setFill(500);
            FluidPumpBlockEntity.serverTick(level, pumpPos, level.getBlockState(pumpPos), pump);
            HbmFluidNodespace.tick(level);
            assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, pumpOutputPipePos, HbmFluids.WATER),
                    "fluid pump provides on the side opposite its old rotated input");
            TestFluidReceiver pumpSink = new TestFluidReceiver(HbmFluids.WATER, 500);
            assertTrue(HbmFluidUtil.subscribeReceiverToNetwork(level, pumpOutputPipePos, Direction.WEST,
                    HbmFluids.WATER, pumpSink), "test water sink subscribes to the fluid pump output pipe");
            HbmFluidNet pumpOutputNet = HbmFluidNodespace.getNode(level, pumpOutputPipePos, HbmFluids.WATER).getFluidNet();
            assertTrue(pumpOutputNet.update() > 0L,
                    "fluid pump delivers water through its source-backed opposite output port: "
                            + describeFluidNet(pumpOutputNet));
            assertTrue(pumpSink.getStoredFluid() > 0, "fluid pump delivers water through its opposite output port");

            level.setBlock(pumpPos.above(), Blocks.REDSTONE_BLOCK.defaultBlockState(), Block.UPDATE_ALL);
            FluidPumpBlockEntity.serverTick(level, pumpPos, level.getBlockState(pumpPos), pump);
            HbmFluidNodespace.tick(level);
            // The blocked pump retries its input endpoint after START rebuilds its
            // remote pipe net, just like the original per-tick update loop.
            FluidPumpBlockEntity.serverTick(level, pumpPos, level.getBlockState(pumpPos), pump);
            assertTrue(pump.isRedstoneBlocked(), "fluid pump observes redstone at its legacy machine position");
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, pumpInputPipePos, HbmFluids.WATER),
                    "fluid pump keeps its legacy input subscription while redstone-blocked");
            assertEquals(0, HbmFluidNodespace.getNetworkProviderCount(level, pumpOutputPipePos, HbmFluids.WATER),
                    "fluid pump redstone blocks only its legacy output subscription");
            level.setBlock(pumpPos.above(), Blocks.AIR.defaultBlockState(), Block.UPDATE_ALL);
            pump.getTank().setFill(500);
            FluidPumpBlockEntity.serverTick(level, pumpPos, level.getBlockState(pumpPos), pump);
            HbmFluidNodespace.tick(level);
            // Output subscriptions are retried by the following legacy machine pass.
            FluidPumpBlockEntity.serverTick(level, pumpPos, level.getBlockState(pumpPos), pump);
            assertTrue(!pump.isRedstoneBlocked(), "fluid pump clears the redstone output block when power is removed");
            assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, pumpOutputPipePos, HbmFluids.WATER),
                    "fluid pump restores its legacy output subscription after redstone is removed");

            level.setBlock(refuelerInputPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            assertLegacyRemoteFluidInput(level, refueler, refueler.getTank(), HbmFluids.KEROSENE, 1, "refueler",
                    () -> RefuelerBlockEntity.serverTick(level, refueler.getBlockPos(),
                            level.getBlockState(refueler.getBlockPos()), refueler));
            // The initial transfer fills Refueler's source-backed 100-unit tank;
            // make the unchanged receiver actually receptive before replacement.
            refueler.getTank().setFill(0);
            assertLegacyAdjacentFluidReceiverRecoversOnNextTick(level, refueler, refueler.getTank(),
                    HbmFluids.KEROSENE, "refueler", () -> RefuelerBlockEntity.serverTick(level,
                            refueler.getBlockPos(), level.getBlockState(refueler.getBlockPos()), refueler));
            } finally {
                clearBox(level, pumpPos.offset(-3, -2, -3), refuelerPos.offset(3, 3, 3));
            }
        });
    }

