                    assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, pipePos, HbmFluids.SMOKE),
                            "combination oven dispatches smoke through its legacy remote port on the 20-tick pass");
                    HbmFluidNodespace.tick(level);
