    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosCompressor")
    public static void compressorKeepsLegacyInputAndOutputFluidCadence(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        int delayToNonTwentiethTick = Math.floorMod(20 - (int) (level.getGameTime() % 20L) + 1, 20);
        if (delayToNonTwentiethTick == 0) {
            delayToNonTwentiethTick = 1;
        }
        int delayToNextTwentiethTick = 20
                - (int) ((level.getGameTime() + delayToNonTwentiethTick) % 20L);
        if (delayToNextTwentiethTick == 0) {
            delayToNextTwentiethTick = 20;
        }
        BlockPos compressorPos = helper.absolutePos(new BlockPos(4, 2, 4));
        BlockPos compactPos = helper.absolutePos(new BlockPos(24, 2, 4));
        helper.startSequence()
                .thenIdle(delayToNonTwentiethTick)
                .thenExecute(() -> {
                    assertTrue(level.getGameTime() % 20L != 0L,
                            "compressor Fluid Mk2 fixture runs outside the legacy twenty-tick input boundary");
                    clearBox(level, compressorPos.offset(-5, -2, -5), compactPos.offset(7, 3, 5));
                    forceLoadedChunks(level, compressorPos.offset(-5, -2, -5), compactPos.offset(7, 3, 5));
                    level.setBlock(compressorPos, ModBlocks.MACHINE_COMPRESSOR.get().defaultBlockState(), Block.UPDATE_ALL);
                    level.setBlock(compactPos, ModBlocks.MACHINE_COMPRESSOR_COMPACT.get().defaultBlockState(),
                            Block.UPDATE_ALL);
                    CompressorBlockEntity compressor = requireBlockEntity(level, compressorPos,
                            CompressorBlockEntity.class, "compressor Fluid Mk2 cadence fixture");
                    CompressorBlockEntity compact = requireBlockEntity(level, compactPos,
                            CompressorBlockEntity.class, "compact compressor Fluid Mk2 cadence fixture");

                    assertLegacyCompressorFluidCadenceOutsideInputBoundary(level, compressor, 3, "compressor");
                    assertLegacyCompressorFluidCadenceOutsideInputBoundary(level, compact, 6, "compact compressor");
                })
                .thenIdle(delayToNextTwentiethTick)
                .thenExecute(() -> {
                    assertEquals(0L, level.getGameTime() % 20L,
                            "compressor Fluid Mk2 fixture reaches the legacy twenty-tick input boundary");
                    assertLegacyCompressorInputRecoversOnTwentyTick(level, compressorPos, "compressor");
                    assertLegacyCompressorInputRecoversOnTwentyTick(level, compactPos, "compact compressor");
                    clearBox(level, compressorPos.offset(-5, -2, -5), compactPos.offset(7, 3, 5));
                })
                .thenSucceed();
    }

