                if (!(level.getBlockEntity(intakePos) instanceof IntakeBlockEntity intake)) {
                    throw new AssertionError("Intake fluid fixture did not create its source-backed block entity");
                }

                // TileEntityMachineIntake sends non-empty AIR through all eight
