    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosPrecassCrystallizerFluid")
    public static void precassAndCrystallizerUseLegacyRemoteFluidPortsWithoutCoreNodes(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        runOutsideLegacyTwentyTick(helper, () -> {
            BlockPos precassPos = helper.absolutePos(new BlockPos(8, 2, 8));
            BlockPos crystallizerPos = helper.absolutePos(new BlockPos(28, 2, 8));
            clearBox(level, precassPos.offset(-4, -2, -4), crystallizerPos.offset(4, 3, 4));
            try {
                forceLoadedChunks(level, precassPos.offset(-4, -2, -4), crystallizerPos.offset(4, 3, 4));
                level.setBlock(precassPos, ModBlocks.MACHINE_PRECASS.get().defaultBlockState(), Block.UPDATE_ALL);
                level.setBlock(crystallizerPos, ModBlocks.MACHINE_CRYSTALLIZER.get().defaultBlockState(), Block.UPDATE_ALL);
                if (!(level.getBlockEntity(precassPos) instanceof LegacyGenericSelectorMachineBlockEntity precass)
                        || !(level.getBlockEntity(crystallizerPos) instanceof ProcessingMachineBlockEntity crystallizer)) {
                    throw new AssertionError("precision assembler / crystallizer fluid fixture did not create both block entities");
                }

                List<HbmFluidUtil.FluidPort> precassPorts = LegacyMultiblockPorts.xrFloorRingFluidPorts(2);
                assertDirectRemoteFluidInput(level, precassPos, precassPorts, precass.getInputTank(0), HbmFluids.WATER,
                        12, "precision assembler", () -> LegacyGenericSelectorMachineBlockEntity.serverTick(level,
                                precassPos, level.getBlockState(precassPos), precass));
                level.removeBlock(precassPorts.get(0).connectorPos(precassPos), false);
                assertDirectRemoteFluidOutput(level, precassPos, precassPorts, precass.getOutputTank(0), HbmFluids.DIESEL,
                        12, "precision assembler", () -> LegacyGenericSelectorMachineBlockEntity.serverTick(level,
                                precassPos, level.getBlockState(precassPos), precass));

                assertDirectRemoteFluidInput(level, crystallizerPos, LegacyMultiblockPorts.crystallizerFluidPorts(),
                        crystallizer.getCrystallizerTank(), HbmFluids.PEROXIDE, 8, "crystallizer",
                        () -> ProcessingMachineBlockEntity.serverTick(level, crystallizerPos,
                                level.getBlockState(crystallizerPos), crystallizer));
            } finally {
                clearBox(level, precassPos.offset(-4, -2, -4), crystallizerPos.offset(4, 3, 4));
            }
        });
    }

    @GameTest(templateNamespace = HbmNtm.MOD_ID, template = "empty", batch = "uninosRadiolysisFluid")
    public static void radiolysisUsesLegacyDirectFluidPortsWithoutCoreNodes(GameTestHelper helper) {
        ServerLevel level = helper.getLevel();
        BlockPos inputPos = helper.absolutePos(new BlockPos(4, 2, 4));
        BlockPos outputPos = helper.absolutePos(new BlockPos(20, 2, 4));
        clearBox(level, inputPos.offset(-4, -2, -4), outputPos.offset(4, 3, 4));
        try {
            forceLoadedChunks(level, inputPos.offset(-4, -2, -4), outputPos.offset(4, 3, 4));
            level.setBlock(inputPos, ModBlocks.MACHINE_RADIOLYSIS.get().defaultBlockState(), Block.UPDATE_ALL);
            level.setBlock(outputPos, ModBlocks.MACHINE_RADIOLYSIS.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(inputPos) instanceof RadiolysisBlockEntity input)
                    || !(level.getBlockEntity(outputPos) instanceof RadiolysisBlockEntity output)) {
                throw new AssertionError("Radiolysis fluid fixture did not create both source-backed block entities");
            }

            assertLegacyHbmFluidRemoteInput(level, input, input.getInputTank(), HbmFluids.WATER, 4,
                    "radiolysis water", () -> RadiolysisBlockEntity.serverTick(level, inputPos,
                            level.getBlockState(inputPos), input));

            // WATER is the source-backed radiolysis recipe selector: its datapack result fixes
            // the two independent output tanks to PEROXIDE and HYDROGEN before each provider pass.
            output.getInputTank().setTankType(HbmFluids.WATER);
            assertLegacyHbmFluidRemoteOutput(level, output, output.getOutputTank1(), HbmFluids.PEROXIDE, 4,
                    "radiolysis peroxide", () -> RadiolysisBlockEntity.serverTick(level, outputPos,
                            level.getBlockState(outputPos), output));
            assertLegacyHbmFluidRemoteOutput(level, output, output.getOutputTank2(), HbmFluids.HYDROGEN, 4,
                    "radiolysis hydrogen", () -> RadiolysisBlockEntity.serverTick(level, outputPos,
                            level.getBlockState(outputPos), output));
        } finally {
            clearBox(level, inputPos.offset(-4, -2, -4), outputPos.offset(4, 3, 4));
        }
        helper.succeed();
    }

