        ModItems.NUKE_ELECTRIC_KIT.get().use(level, player, InteractionHand.MAIN_HAND);
        assertTrue(player.getItemInHand(InteractionHand.MAIN_HAND).isEmpty(),
                "nuke_electric_kit right-click consumes the kit");
