    private static void assertNoSavedStackMigrationDiagnostics(SavedStackMigrationResult result, String label) {
        assertEquals(0, result.numericItemStacksWithoutMap(), label + " numeric stacks without map");
        assertEquals(0, result.unknownNumericItemStacks(), label + " unknown numeric item stacks");
        assertEquals(0, result.unknownLegacyBatteryMetas(), label + " unknown legacy battery metas");
    }

    private record SavedStackMigrationResult(int migrated, int sourcesWithMigrations, int numericItemStacksWithoutMap,
            int unknownNumericItemStacks, int unknownLegacyBatteryMetas, int chargedEnergyStacks,
            int droppedEnergyEntities, int lowercaseItemContainers,
            Map<String, Integer> migratedIds) {
        static SavedStackMigrationResult empty() {
            return new SavedStackMigrationResult(0, 0, 0, 0, 0, 0, 0, 0, Map.of());
        }

        SavedStackMigrationResult withSource() {
            return new SavedStackMigrationResult(migrated, 1, numericItemStacksWithoutMap, unknownNumericItemStacks,
                    unknownLegacyBatteryMetas, chargedEnergyStacks, droppedEnergyEntities, lowercaseItemContainers,
                    migratedIds);
        }

        SavedStackMigrationResult plus(SavedStackMigrationResult other) {
            if (other == null || other.isEmpty()) {
                return this;
            }
            Map<String, Integer> merged = new LinkedHashMap<>(migratedIds);
            other.migratedIds.forEach((id, count) -> merged.merge(id, count, Integer::sum));
            return new SavedStackMigrationResult(
                    migrated + other.migrated,
                    sourcesWithMigrations + other.sourcesWithMigrations,
                    numericItemStacksWithoutMap + other.numericItemStacksWithoutMap,
                    unknownNumericItemStacks + other.unknownNumericItemStacks,
                    unknownLegacyBatteryMetas + other.unknownLegacyBatteryMetas,
                    chargedEnergyStacks + other.chargedEnergyStacks,
                    droppedEnergyEntities + other.droppedEnergyEntities,
                    lowercaseItemContainers + other.lowercaseItemContainers,
                    merged);
        }

        boolean isEmpty() {
            return migrated == 0
                    && sourcesWithMigrations == 0
                    && numericItemStacksWithoutMap == 0
                    && unknownNumericItemStacks == 0
                    && unknownLegacyBatteryMetas == 0
                    && chargedEnergyStacks == 0
                    && droppedEnergyEntities == 0
                    && lowercaseItemContainers == 0
                    && migratedIds.isEmpty();
        }

        int count(RegistryObject<Item> item) {
            return migratedIds.getOrDefault(item.getId().toString(), 0);
        }
    }

    private record SavedStackShapeCounts(int chargedStacks, int droppedEnergyEntities, int lowercaseItemContainers) {
        static SavedStackShapeCounts empty() {
            return new SavedStackShapeCounts(0, 0, 0);
        }

        SavedStackShapeCounts plus(SavedStackShapeCounts other) {
            return new SavedStackShapeCounts(chargedStacks + other.chargedStacks,
                    droppedEnergyEntities + other.droppedEnergyEntities,
                    lowercaseItemContainers + other.lowercaseItemContainers);
        }
    }

    private static CompoundTag legacyStackTag(String id, int damage, int count) {
        CompoundTag tag = new CompoundTag();
        tag.putString("id", id);
        tag.putByte("Count", (byte) count);
        tag.putShort("Damage", (short) damage);
        return tag;
    }

    private static CompoundTag legacyNumericStackTag(int id, int damage, int count) {
        CompoundTag tag = new CompoundTag();
        tag.putShort("id", (short) id);
        tag.putByte("Count", (byte) count);
        tag.putShort("Damage", (short) damage);
        return tag;
    }

    private static CompoundTag legacyNumericRoot(int id, int damage) {
        CompoundTag root = new CompoundTag();
        ListTag items = new ListTag();
        items.add(legacyNumericStackTag(id, damage, 1));
        root.put("Items", items);
        return root;
    }

    private static CompoundTag legacyDroppedItemEntityRoot(int id, int damage, long charge) {
        CompoundTag root = new CompoundTag();
        CompoundTag level = new CompoundTag();
        ListTag entities = new ListTag();
        CompoundTag entity = new CompoundTag();
        entity.putString("id", "Item");
        CompoundTag stack = legacyNumericStackTag(id, damage, 1);
        if (charge > 0L) {
            CompoundTag itemTag = new CompoundTag();
            itemTag.putLong(HbmBatteryItem.DEFAULT_CHARGE_TAG, charge);
            stack.put("tag", itemTag);
        }
        entity.put("Item", stack);
        entities.add(entity);
        level.put("Entities", entities);
        root.put("Level", level);
        return root;
    }

    private static CompoundTag legacyItemData(String key, int value) {
        CompoundTag tag = new CompoundTag();
        tag.putString("K", key);
        tag.putInt("V", value);
        return tag;
    }

    private static CompoundTag legacyItemDataInsideDataLevelDat() {
        CompoundTag levelDat = new CompoundTag();
        CompoundTag data = new CompoundTag();
        CompoundTag fml = new CompoundTag();
        ListTag itemData = new ListTag();
        itemData.add(legacyItemData("\u0002hbm:item.battery_pack", 4727));
        itemData.add(legacyItemData("\u0002hbm:item.battery_sc", 4728));
        fml.put("ItemData", itemData);
        data.put("FML", fml);
        levelDat.put("Data", data);
        return levelDat;
    }

    private static CompoundTag legacyModItemDataLevelDat() {
        CompoundTag levelDat = new CompoundTag();
        CompoundTag fml = new CompoundTag();
        ListTag modItemData = new ListTag();
        modItemData.add(legacyModItemData("hbm", "item.battery_pack", 6725));
        modItemData.add(legacyModItemData("hbm", "item.battery_sc", 6726));
        modItemData.add(legacyModItemData("hbm", "item.battery_creative", 6727));
        fml.put("ModItemData", modItemData);
        levelDat.put("FML", fml);
        return levelDat;
    }

    private static CompoundTag legacyModItemData(String modId, String forcedName, int itemId) {
        CompoundTag tag = new CompoundTag();
        tag.putString("ModId", modId);
        tag.putString("ItemType", "item");
        tag.putInt("ItemId", itemId);
        tag.putInt("ordinal", 0);
        tag.putString("ForcedName", forcedName);
        return tag;
    }

    private static int setBlockMigrationCachedBuildNumberForTesting(int buildNumber) {
        try {
            Field field = BlockMigrationHelper.class.getDeclaredField("cachedBuildNumber");
            field.setAccessible(true);
            int previous = field.getInt(null);
            field.setInt(null, buildNumber);
            return previous;
        } catch (ReflectiveOperationException exception) {
            throw new AssertionError("Failed to set BlockMigrationHelper cached build number", exception);
        }
    }

    private static void refreshEnergyNodeAt(ServerLevel level, BlockPos pos) {
        if (level.getBlockEntity(pos) instanceof HbmEnergyNodeHost host) {
            host.refreshEnergyNode();
            return;
        }
        throw new AssertionError("No HBM energy node host at " + pos);
    }

    @SuppressWarnings("unchecked")
    private static List<String> scannerLegacyTargetNames(Class<?> lensClass) {
        try {
            Field field = lensClass.getDeclaredField("SCANNER_TARGETS");
            field.setAccessible(true);
            List<Object> targets = (List<Object>) field.get(null);
            List<String> legacyNames = new ArrayList<>();
            for (Object target : targets) {
                Method name = target.getClass().getDeclaredMethod("legacyName");
                name.setAccessible(true);
                Object value = name.invoke(target);
                if (value instanceof String legacyName) {
                    legacyNames.add(legacyName);
                }
            }
            return legacyNames;
        } catch (ReflectiveOperationException exception) {
            throw new AssertionError("Could not inspect the source-shaped neutrino lens scanner table", exception);
        }
    }

    private static void invokeSatelliteDockAddToOutput(
            com.hbm.ntm.blockentity.SatelliteDockBlockEntity dock, ItemStack stack) {
        try {
            Method method = com.hbm.ntm.blockentity.SatelliteDockBlockEntity.class
                    .getDeclaredMethod("addToOutput", ItemStack.class);
            method.setAccessible(true);
            method.invoke(dock, stack);
        } catch (ReflectiveOperationException exception) {
            throw new AssertionError("Failed to invoke TileEntityMachineSatDock's cargo-output carrier", exception);
        }
    }

    @SuppressWarnings({ "rawtypes", "unchecked" })
    private static void tickLegacyWireHost(ServerLevel level, BlockPos pos, HbmLegacyWireNodeBlockEntity host,
            BlockEntityType<?> type) {
        BlockState state = level.getBlockState(pos);
        if (!(state.getBlock() instanceof EntityBlock entityBlock)) {
            throw new AssertionError("Legacy wire host block has no BlockEntity ticker contract at " + pos);
        }
        BlockEntityTicker ticker = entityBlock.getTicker(level, state, (BlockEntityType) type);
        if (ticker == null) {
            throw new AssertionError("No source-backed server ticker for legacy wire host at " + pos);
        }
        ticker.tick(level, pos, state, host);
    }

    private static HbmEnergyNode requireEnergyNodeAt(ServerLevel level, BlockPos pos) {
        if (level.getBlockEntity(pos) instanceof HbmEnergyNodeHost host
                && host.getEnergyNode() != null
                && !host.getEnergyNode().isExpired()) {
            return host.getEnergyNode();
        }
        throw new AssertionError("No live HBM energy node host at " + pos);
    }

    private static HbmLegacyWireNode requireLegacyWireNodeAt(ServerLevel level, BlockPos pos) {
        if (level.getBlockEntity(pos) instanceof HbmLegacyWireNode wireNode) {
            return wireNode;
        }
        throw new AssertionError("No HBM legacy wire node at " + pos);
    }

    private static void assertStoredWireStart(ItemStack stack, BlockPos expected, String label) {
        CompoundTag tag = stack.getTag();
        assertTrue(tag != null, label + " tag exists");
        assertEquals(expected.getX(), tag.getInt("x"), label + " x");
        assertEquals(expected.getY(), tag.getInt("y"), label + " y");
        assertEquals(expected.getZ(), tag.getInt("z"), label + " z");
    }

    private static void refreshFluidNodeAt(ServerLevel level, BlockPos pos) {
        if (level.getBlockEntity(pos) instanceof FluidPipeBlockEntity pipe) {
            pipe.refreshFluidNode();
            return;
        }
        throw new AssertionError("No HBM fluid pipe at " + pos);
    }

    private static void prepareOilRemoteFluidCadencePipe(ServerLevel level, BlockPos origin,
            HbmFluidUtil.FluidPort port, FluidType type) {
        BlockPos pipePos = port.connectorPos(origin);
        level.setBlock(pipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(pipePos) instanceof FluidPipeBlockEntity pipe)) {
            throw new AssertionError("oil remote-fluid cadence fixture did not create a fluid_duct_neo at " + pipePos);
        }
        pipe.setFluidType(type);
        refreshFluidNodeAt(level, pipePos);
    }

    private static <T> T requireBlockEntity(ServerLevel level, BlockPos pos, Class<T> type, String message) {
        Object blockEntity = level.getBlockEntity(pos);
        if (type.isInstance(blockEntity)) {
            return type.cast(blockEntity);
        }
        throw new AssertionError(message + "; found "
                + (blockEntity == null ? "no block entity" : blockEntity.getClass().getName()));
    }

    private static void prepareDieselFluidPipeLine(ServerLevel level, BlockPos firstPipePos, BlockPos lastPipePos) {
        forceLoadedChunks(level, firstPipePos, lastPipePos);
        for (int x = firstPipePos.getX(); x <= lastPipePos.getX(); x++) {
            BlockPos pipePos = new BlockPos(x, firstPipePos.getY(), firstPipePos.getZ());
            level.removeBlock(pipePos, false);
            level.setBlock(pipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            if (level.getBlockEntity(pipePos) instanceof FluidPipeBlockEntity pipe) {
                pipe.setFluidType(HbmFluids.DIESEL);
            } else {
                throw new AssertionError("No fluid_duct_neo block entity at " + pipePos);
            }
        }
        for (int x = firstPipePos.getX(); x <= lastPipePos.getX(); x++) {
            refreshFluidNodeAt(level, new BlockPos(x, firstPipePos.getY(), firstPipePos.getZ()));
        }
        HbmFluidNodespace.forceRebuild(level);
        HbmFluidNodespace.tick(level);
        HbmFluidNodespace.Diagnostics joined = HbmFluidNodespace.getDiagnostics(level);
        assertTrue(joined.uniqueNodes() >= 4, "cross-chunk fluid_duct_neo diesel line node count");
        assertTrue(joined.networks() >= 1, "cross-chunk fluid_duct_neo diesel line joined network");
    }


    private static HbmFluidUtil.PortSnapshot requireSubscribedFluidPort(ServerLevel level, BlockPos origin,
            Iterable<HbmFluidUtil.FluidPort> ports, FluidType type) {
        for (HbmFluidUtil.FluidPort port : ports) {
            HbmFluidUtil.PortSnapshot snapshot = HbmFluidUtil.inspectPort(level, origin, port, type);
            if (snapshot.receivers() >= 1) {
                return snapshot;
            }
        }
        throw new AssertionError("No subscribed fluid receiver port found; ports="
                + HbmFluidUtil.inspectPorts(level, origin, ports, type));
    }

    private static void assertLegacyRemoteCoolingTowerFluidEndpoints(ServerLevel level,
            com.hbm.ntm.blockentity.CoolingTowerBlockEntity tower, int expectedPortCount, String towerName) {
        List<HbmFluidUtil.FluidPort> inputPorts = legacyRemoteFluidPorts(tower, HbmFluids.SPENTSTEAM);
        List<HbmFluidUtil.FluidPort> outputPorts = legacyRemoteFluidPorts(tower, HbmFluids.WATER);
        assertEquals(expectedPortCount, inputPorts.size(), towerName + " exposes all legacy spent-steam ports");
        assertEquals(expectedPortCount, outputPorts.size(), towerName + " reuses all legacy water output ports");

        HbmFluidUtil.FluidPort inputPort = inputPorts.get(0);
        HbmFluidUtil.FluidPort outputPort = outputPorts.get(1);
        BlockPos inputPipePos = inputPort.connectorPos(tower.getBlockPos());
        BlockPos outputPipePos = outputPort.connectorPos(tower.getBlockPos());
        level.setBlock(inputPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        level.setBlock(outputPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(inputPipePos) instanceof FluidPipeBlockEntity inputPipe)
                || !(level.getBlockEntity(outputPipePos) instanceof FluidPipeBlockEntity outputPipe)) {
            throw new AssertionError(towerName + " fixture did not create its source-backed remote pipes");
        }
        inputPipe.setFluidType(HbmFluids.SPENTSTEAM);
        outputPipe.setFluidType(HbmFluids.WATER);
        refreshFluidNodeAt(level, inputPipePos);
        refreshFluidNodeAt(level, outputPipePos);

        tickCoolingTower(level, tower);
        HbmFluidNodespace.tick(level);
        assertTrue(HbmFluidNodespace.getNode(level, tower.getBlockPos(), HbmFluids.SPENTSTEAM) == null,
                towerName + " receives spent steam through remote ports without a core fluid node");
        assertTrue(HbmFluidNodespace.getNode(level, tower.getBlockPos(), HbmFluids.WATER) == null,
                towerName + " provides water through remote ports without a core fluid node");
        assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, inputPipePos, HbmFluids.SPENTSTEAM),
                towerName + " subscribes to its legacy spent-steam input port");

        level.removeBlock(inputPipePos, false);
        level.setBlock(inputPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(inputPipePos) instanceof FluidPipeBlockEntity replacementInputPipe)) {
            throw new AssertionError(towerName + " input replacement did not create its remote duct");
        }
        replacementInputPipe.setFluidType(HbmFluids.SPENTSTEAM);
        refreshFluidNodeAt(level, inputPipePos);
        HbmFluidNodespace.tick(level);
        tickCoolingTower(level, tower);
        assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, inputPipePos, HbmFluids.SPENTSTEAM),
                towerName + " retries its spent-steam receiver on the next legacy server tick");

        TestFluidProvider source = new TestFluidProvider(HbmFluids.SPENTSTEAM, 500);
        TestFluidReceiver sink = new TestFluidReceiver(HbmFluids.WATER, 500);
        assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, inputPipePos, inputPort.connectorSide(),
                HbmFluids.SPENTSTEAM, source), towerName + " input source subscribes");
        assertTrue(HbmFluidUtil.subscribeReceiverToNetwork(level, outputPipePos, outputPort.connectorSide(),
                HbmFluids.WATER, sink), towerName + " output sink subscribes");
        assertTrue(HbmFluidNodespace.getNode(level, inputPipePos, HbmFluids.SPENTSTEAM).getFluidNet().update() > 0L,
                towerName + " remote spent-steam network transfers into its input tank");
        assertTrue(tower.getInputTank().getFill() > 0, towerName + " receives spent steam through its legacy port");

        tickCoolingTower(level, tower);
        HbmFluidNodespace.tick(level);
        tickCoolingTower(level, tower);
        HbmFluidNodespace.tick(level);
        assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, outputPipePos, HbmFluids.WATER),
                towerName + " subscribes as a water provider at its legacy output port");
        assertTrue(sink.getStoredFluid() > 0, towerName + " delivers condensed water through its legacy port");
    }

    private static void tickCoolingTower(ServerLevel level, com.hbm.ntm.blockentity.CoolingTowerBlockEntity tower) {
        BlockPos pos = tower.getBlockPos();
        if (tower instanceof SmallCoolingTowerBlockEntity small) {
            SmallCoolingTowerBlockEntity.serverTick(level, pos, level.getBlockState(pos), small);
        } else if (tower instanceof LargeCoolingTowerBlockEntity large) {
            LargeCoolingTowerBlockEntity.serverTick(level, pos, level.getBlockState(pos), large);
        } else {
            throw new AssertionError("Unexpected cooling tower type " + tower.getClass().getName());
        }
    }

    private static void assertLegacyOilDrillFluidEndpoints(ServerLevel level, OilDrillBlockEntity drill,
            int expectedPortCount, String drillName) {
        List<HbmFluidUtil.FluidPort> oilPorts = legacyRemoteFluidPorts(drill, HbmFluids.OIL);
        List<HbmFluidUtil.FluidPort> gasPorts = legacyRemoteFluidPorts(drill, HbmFluids.GAS);
        assertEquals(expectedPortCount, oilPorts.size(), drillName + " exposes all legacy oil output ports");
        assertEquals(expectedPortCount, gasPorts.size(), drillName + " exposes all legacy gas output ports");

        HbmFluidUtil.FluidPort oilPort = oilPorts.get(0);
        HbmFluidUtil.FluidPort gasPort = gasPorts.get(1);
        BlockPos oilPipePos = oilPort.connectorPos(drill.getBlockPos());
        BlockPos gasPipePos = gasPort.connectorPos(drill.getBlockPos());
        level.setBlock(oilPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        level.setBlock(gasPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(oilPipePos) instanceof FluidPipeBlockEntity oilPipe)
                || !(level.getBlockEntity(gasPipePos) instanceof FluidPipeBlockEntity gasPipe)) {
            throw new AssertionError(drillName + " fixture did not create its source-backed oil and gas pipes");
        }
        oilPipe.setFluidType(HbmFluids.OIL);
        gasPipe.setFluidType(HbmFluids.GAS);
        refreshFluidNodeAt(level, oilPipePos);
        refreshFluidNodeAt(level, gasPipePos);

        HbmFluidTank frackingTank = drill.getFrackingTank();
        HbmFluidUtil.FluidPort frackingPort = null;
        BlockPos frackingPipePos = null;
        if (frackingTank != null) {
            List<HbmFluidUtil.FluidPort> frackingPorts = legacyRemoteFluidPorts(drill, HbmFluids.FRACKSOL);
            assertEquals(expectedPortCount, frackingPorts.size(), drillName + " exposes all legacy fracksol input ports");
            frackingPort = frackingPorts.get(2);
            frackingPipePos = frackingPort.connectorPos(drill.getBlockPos());
            level.setBlock(frackingPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(frackingPipePos) instanceof FluidPipeBlockEntity frackingPipe)) {
                throw new AssertionError(drillName + " fixture did not create its source-backed fracksol pipe");
            }
            frackingPipe.setFluidType(HbmFluids.FRACKSOL);
            refreshFluidNodeAt(level, frackingPipePos);
        }

        drill.getSendingTanks().get(0).setFill(500);
        drill.getSendingTanks().get(1).setFill(500);
        BlockPos drillPos = drill.getBlockPos();
        OilDrillBlockEntity.serverTick(level, drillPos, level.getBlockState(drillPos), drill);
        HbmFluidNodespace.tick(level);

        assertTrue(HbmFluidNodespace.getNode(level, drillPos, HbmFluids.OIL) == null,
                drillName + " provides oil through remote ports without a core fluid node");
        assertTrue(HbmFluidNodespace.getNode(level, drillPos, HbmFluids.GAS) == null,
                drillName + " provides gas through remote ports without a core fluid node");
        assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, oilPipePos, HbmFluids.OIL),
                drillName + " subscribes its oil output at a legacy remote port");
        assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, gasPipePos, HbmFluids.GAS),
                drillName + " subscribes its gas output at a legacy remote port");

        TestFluidReceiver oilSink = new TestFluidReceiver(HbmFluids.OIL, 500);
        TestFluidReceiver gasSink = new TestFluidReceiver(HbmFluids.GAS, 500);
        assertTrue(HbmFluidUtil.subscribeReceiverToNetwork(level, oilPipePos, oilPort.connectorSide(), HbmFluids.OIL,
                oilSink), drillName + " oil output sink subscribes");
        assertTrue(HbmFluidUtil.subscribeReceiverToNetwork(level, gasPipePos, gasPort.connectorSide(), HbmFluids.GAS,
                gasSink), drillName + " gas output sink subscribes");
        assertTrue(HbmFluidNodespace.getNode(level, oilPipePos, HbmFluids.OIL).getFluidNet().update() > 0L,
                drillName + " remote oil network transfers to its sink");
        assertTrue(HbmFluidNodespace.getNode(level, gasPipePos, HbmFluids.GAS).getFluidNet().update() > 0L,
                drillName + " remote gas network transfers to its sink");
        assertTrue(oilSink.getStoredFluid() > 0, drillName + " delivers oil through its legacy remote port");
        assertTrue(gasSink.getStoredFluid() > 0, drillName + " delivers gas through its legacy remote port");

        // TileEntityOilDrillBase#updateEntity called updateConnections and sent both non-empty output
        // tanks every tick. Replacing a same-type duct must therefore recover on the next production tick.
        level.removeBlock(oilPipePos, false);
        level.setBlock(oilPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(oilPipePos) instanceof FluidPipeBlockEntity replacedOilPipe)) {
            throw new AssertionError(drillName + " cadence fixture did not replace its oil output duct");
        }
        replacedOilPipe.setFluidType(HbmFluids.OIL);
        refreshFluidNodeAt(level, oilPipePos);
        HbmFluidNodespace.tick(level);
        drill.getSendingTanks().get(0).setFill(500);
        OilDrillBlockEntity.serverTick(level, drillPos, level.getBlockState(drillPos), drill);
        assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, oilPipePos, HbmFluids.OIL),
                drillName + " retries its replaced oil provider on the next legacy server tick");
        assertTrue(HbmFluidNodespace.getNode(level, drillPos, HbmFluids.OIL) == null,
                drillName + " keeps its replaced oil provider remote from the ordinary core node");
        TestFluidReceiver replacedOilSink = new TestFluidReceiver(HbmFluids.OIL, 500);
        assertTrue(HbmFluidUtil.subscribeReceiverToNetwork(level, oilPipePos, oilPort.connectorSide(), HbmFluids.OIL,
                replacedOilSink), drillName + " replacement oil output sink subscribes");
        HbmFluidNet replacedOilNet = HbmFluidNodespace.getNode(level, oilPipePos, HbmFluids.OIL).getFluidNet();
        assertTrue(replacedOilNet.update() > 0L,
                drillName + " transfers through its next-tick restored oil provider: " + describeFluidNet(replacedOilNet));
        assertTrue(replacedOilSink.getStoredFluid() > 0,
                drillName + " delivers oil through its next-tick restored legacy remote port");

        level.removeBlock(gasPipePos, false);
        level.setBlock(gasPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(gasPipePos) instanceof FluidPipeBlockEntity replacedGasPipe)) {
            throw new AssertionError(drillName + " cadence fixture did not replace its gas output duct");
        }
        replacedGasPipe.setFluidType(HbmFluids.GAS);
        refreshFluidNodeAt(level, gasPipePos);
        HbmFluidNodespace.tick(level);
        drill.getSendingTanks().get(1).setFill(500);
        OilDrillBlockEntity.serverTick(level, drillPos, level.getBlockState(drillPos), drill);
        assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, gasPipePos, HbmFluids.GAS),
                drillName + " retries its replaced gas provider on the next legacy server tick");
        assertTrue(HbmFluidNodespace.getNode(level, drillPos, HbmFluids.GAS) == null,
                drillName + " keeps its replaced gas provider remote from the ordinary core node");
        TestFluidReceiver replacedGasSink = new TestFluidReceiver(HbmFluids.GAS, 500);
        assertTrue(HbmFluidUtil.subscribeReceiverToNetwork(level, gasPipePos, gasPort.connectorSide(), HbmFluids.GAS,
                replacedGasSink), drillName + " replacement gas output sink subscribes");
        HbmFluidNet replacedGasNet = HbmFluidNodespace.getNode(level, gasPipePos, HbmFluids.GAS).getFluidNet();
        assertTrue(replacedGasNet.update() > 0L,
                drillName + " transfers through its next-tick restored gas provider: " + describeFluidNet(replacedGasNet));
        assertTrue(replacedGasSink.getStoredFluid() > 0,
                drillName + " delivers gas through its next-tick restored legacy remote port");

        if (frackingTank != null && frackingPort != null && frackingPipePos != null) {
            assertTrue(HbmFluidNodespace.getNode(level, drillPos, HbmFluids.FRACKSOL) == null,
                    drillName + " receives fracksol through remote ports without a core fluid node");
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, frackingPipePos, HbmFluids.FRACKSOL),
                    drillName + " subscribes its fracksol input at a legacy remote port");
            TestFluidProvider fracksolSource = new TestFluidProvider(HbmFluids.FRACKSOL, 500);
            assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, frackingPipePos, frackingPort.connectorSide(),
                    HbmFluids.FRACKSOL, fracksolSource), drillName + " fracksol input source subscribes");
            assertTrue(HbmFluidNodespace.getNode(level, frackingPipePos, HbmFluids.FRACKSOL).getFluidNet().update() > 0L,
                    drillName + " remote fracksol network transfers into its input tank");
            assertTrue(frackingTank.getFill() > 0, drillName + " receives fracksol through its legacy remote port");

            level.removeBlock(frackingPipePos, false);
            level.setBlock(frackingPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
            if (!(level.getBlockEntity(frackingPipePos) instanceof FluidPipeBlockEntity replacedFrackingPipe)) {
                throw new AssertionError(drillName + " cadence fixture did not replace its fracksol input duct");
            }
            replacedFrackingPipe.setFluidType(HbmFluids.FRACKSOL);
            refreshFluidNodeAt(level, frackingPipePos);
            HbmFluidNodespace.tick(level);
            int fracksolBeforeReplacement = frackingTank.getFill();
            OilDrillBlockEntity.serverTick(level, drillPos, level.getBlockState(drillPos), drill);
            assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, frackingPipePos, HbmFluids.FRACKSOL),
                    drillName + " retries its replaced fracksol receiver on the next legacy server tick");
            assertTrue(HbmFluidNodespace.getNode(level, drillPos, HbmFluids.FRACKSOL) == null,
                    drillName + " keeps its replaced fracksol receiver remote from the ordinary core node");
            TestFluidProvider replacedFracksolSource = new TestFluidProvider(HbmFluids.FRACKSOL, 500);
            assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, frackingPipePos, frackingPort.connectorSide(),
                    HbmFluids.FRACKSOL, replacedFracksolSource),
                    drillName + " replacement fracksol input source subscribes");
            HbmFluidNet replacedFracksolNet = HbmFluidNodespace.getNode(level, frackingPipePos, HbmFluids.FRACKSOL)
                    .getFluidNet();
            assertTrue(replacedFracksolNet.update() > 0L,
                    drillName + " transfers through its next-tick restored fracksol receiver: "
                            + describeFluidNet(replacedFracksolNet));
            assertTrue(frackingTank.getFill() > fracksolBeforeReplacement,
                    drillName + " receives fracksol through its next-tick restored legacy remote port");
        }
    }

    private static void assertLegacyRemoteOreSlopperFluidEndpoint(ServerLevel level, OreSlopperBlockEntity slopper) {
        List<HbmFluidUtil.FluidPort> ports = legacyRemoteFluidPorts(slopper, HbmFluids.WATER);
        assertEquals(8, ports.size(), "ore slopper exposes eight legacy remote fluid ports");
        HbmFluidUtil.FluidPort testedPort = ports.get(0);
        BlockPos pipePos = testedPort.connectorPos(slopper.getBlockPos());
        forceLoadedChunks(level, slopper.getBlockPos(), pipePos.relative(testedPort.direction().getOpposite()));
        level.setBlock(pipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(pipePos) instanceof FluidPipeBlockEntity pipe)) {
            throw new AssertionError("No fluid_duct_neo block entity at " + pipePos + " for ore slopper");
        }
        pipe.setFluidType(HbmFluids.WATER);
        refreshFluidNodeAt(level, pipePos);
        OreSlopperBlockEntity.serverTick(level, slopper.getBlockPos(), level.getBlockState(slopper.getBlockPos()),
                slopper);
        HbmFluidNodespace.tick(level);

        assertTrue(HbmFluidNodespace.getNode(level, slopper.getBlockPos(), HbmFluids.WATER) == null,
                "ore slopper uses legacy remote fluid endpoints without a core fluid node");
        HbmFluidUtil.PortSnapshot receiverPort = requireSubscribedFluidPort(level, slopper.getBlockPos(), ports,
                HbmFluids.WATER);
        TestFluidProvider source = new TestFluidProvider(HbmFluids.WATER, 500);
        assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, receiverPort.connectorPos(),
                receiverPort.connectorSide(), HbmFluids.WATER, source),
                "test source subscribes to the ore slopper remote water port");
        HbmFluidNet net = HbmFluidNodespace.getNode(level, receiverPort.connectorPos(), HbmFluids.WATER)
                .getFluidNet();
        assertTrue(net.update() > 0L, "ore slopper remote fluid network transfers into its water tank");
        assertTrue(slopper.getWaterTank().getFill() > 0,
                "ore slopper receives water through its source-backed remote port");
        assertTrue(source.getStoredFluid() < 500,
                "test source drains into the ore slopper remote fluid network");
    }

