    private static void assertLegacyCompressorFluidCadenceOutsideInputBoundary(ServerLevel level,
            CompressorBlockEntity compressor, int expectedPortCount, String compressorName) {
        compressor.getReceivingTanks().get(0).setTankType(HbmFluids.KEROSENE);
        compressor.getSendingTanks().get(0).setTankType(HbmFluids.KEROSENE);
        List<HbmFluidUtil.FluidPort> ports = legacyRemoteFluidPorts(compressor, HbmFluids.KEROSENE);
        assertEquals(expectedPortCount, ports.size(), compressorName + " keeps its complete legacy remote port set");
        HbmFluidUtil.FluidPort inputPort = ports.get(0);
        HbmFluidUtil.FluidPort outputPort = ports.get(1);
        BlockPos inputPipePos = inputPort.connectorPos(compressor.getBlockPos());
        BlockPos outputPipePos = outputPort.connectorPos(compressor.getBlockPos());
        prepareCompressorCadencePipe(level, inputPipePos, HbmFluids.KEROSENE, compressorName + " input");
        prepareCompressorCadencePipe(level, outputPipePos, HbmFluids.KEROSENE, compressorName + " output");
        HbmFluidNodespace.tick(level);
        // TileEntityMachineCompressorBase#setupTanks changes the fallback output
        // from pressure 0 to input-pressure + 1, which clears that tank.  First
        // execute the same initialization tick, then fill the now-conforming
        // output tank and execute the independent every-tick provider pass.
        CompressorBlockEntity.serverTick(level, compressor.getBlockPos(), level.getBlockState(compressor.getBlockPos()),
                compressor);
        compressor.getSendingTanks().get(0).setFill(500);
        CompressorBlockEntity.serverTick(level, compressor.getBlockPos(), level.getBlockState(compressor.getBlockPos()),
                compressor);
        assertEquals(0, HbmFluidNodespace.getNetworkReceiverCount(level, inputPipePos, HbmFluids.KEROSENE),
                compressorName + " does not renew its input receiver outside the legacy twenty-tick boundary");
        assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, outputPipePos, HbmFluids.KEROSENE),
                compressorName + " renews its non-empty output provider on every legacy server tick");
        assertTrue(HbmFluidNodespace.getNode(level, compressor.getBlockPos(), HbmFluids.KEROSENE) == null,
                compressorName + " keeps remote Fluid Mk2 ports without an ordinary core node");
        // TileEntityMachineCompressorBase#setupTanks raises fallback kerosene
        // from input pressure 0 to output pressure 1 before its every-tick
        // tryProvide(tanks[1], ...) loop.  The fixture must accept that source
        // pressure rather than accidentally testing a mismatched pressure lane.
        TestFluidReceiver outputSink = new TestFluidReceiver(HbmFluids.KEROSENE, 500,
                compressor.getSendingTanks().get(0).getPressure());
        assertTrue(HbmFluidUtil.subscribeReceiverToNetwork(level, outputPipePos, outputPort.connectorSide(),
                HbmFluids.KEROSENE, outputSink),
                "test sink subscribes to the " + compressorName + " per-tick remote output duct");
        HbmFluidNet outputNet = HbmFluidNodespace.getNode(level, outputPipePos, HbmFluids.KEROSENE).getFluidNet();
        assertTrue(outputNet.update() > 0L,
                compressorName + " per-tick output provider transfers through its source-backed remote duct");
        assertTrue(outputSink.getStoredFluid() > 0,
                compressorName + " delivers output fluid before its input connection boundary");
        compressor.getSendingTanks().get(0).setFill(500);

        // Rebuild both real ducts off-boundary. The input must stay absent until
        // the next twenty-tick pass, while the output provider returns immediately.
        prepareCompressorCadencePipe(level, inputPipePos, HbmFluids.KEROSENE, compressorName + " replacement input");
        prepareCompressorCadencePipe(level, outputPipePos, HbmFluids.KEROSENE, compressorName + " replacement output");
        HbmFluidNodespace.tick(level);
        CompressorBlockEntity.serverTick(level, compressor.getBlockPos(), level.getBlockState(compressor.getBlockPos()),
                compressor);
        assertEquals(0, HbmFluidNodespace.getNetworkReceiverCount(level, inputPipePos, HbmFluids.KEROSENE),
                compressorName + " leaves a replaced input duct unsubscribed before the legacy boundary");
        assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, outputPipePos, HbmFluids.KEROSENE),
                compressorName + " restores a replaced non-empty output duct on the next legacy server tick");
    }

    private static void assertLegacyCompressorInputRecoversOnTwentyTick(ServerLevel level, BlockPos compressorPos,
            String compressorName) {
        CompressorBlockEntity compressor = requireBlockEntity(level, compressorPos, CompressorBlockEntity.class,
                compressorName + " remains available at the legacy input boundary");
        List<HbmFluidUtil.FluidPort> ports = legacyRemoteFluidPorts(compressor, HbmFluids.KEROSENE);
        HbmFluidUtil.FluidPort inputPort = ports.get(0);
        HbmFluidUtil.FluidPort outputPort = ports.get(1);
        BlockPos inputPipePos = inputPort.connectorPos(compressorPos);
        BlockPos outputPipePos = outputPort.connectorPos(compressorPos);
        CompressorBlockEntity.serverTick(level, compressorPos, level.getBlockState(compressorPos), compressor);
        assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, inputPipePos, HbmFluids.KEROSENE),
                compressorName + " restores its replaced input receiver on the next legacy twenty-tick pass");
        assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, outputPipePos, HbmFluids.KEROSENE),
                compressorName + " keeps its non-empty output provider on the input refresh boundary");
        assertTrue(HbmFluidNodespace.getNode(level, compressorPos, HbmFluids.KEROSENE) == null,
                compressorName + " preserves the no-core-node boundary after replaying both remote ducts");
    }

    private static void prepareCompressorCadencePipe(ServerLevel level, BlockPos pipePos, FluidType type,
            String pipeName) {
        level.removeBlock(pipePos, false);
        level.setBlock(pipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(pipePos) instanceof FluidPipeBlockEntity pipe)) {
            throw new AssertionError(pipeName + " fixture did not create its real fluid_duct_neo");
        }
        pipe.setFluidType(type);
        refreshFluidNodeAt(level, pipePos);
    }

    private static void assertLegacyRemoteGasCentFluidEndpoint(ServerLevel level, GasCentBlockEntity gasCent) {
        List<HbmFluidUtil.FluidPort> ports = legacyRemoteFluidPorts(gasCent, HbmFluids.UF6);
        assertEquals(5, ports.size(), "gas centrifuge exposes its five legacy remote fluid ports");
        HbmFluidUtil.FluidPort testedPort = ports.get(0);
        BlockPos pipePos = testedPort.connectorPos(gasCent.getBlockPos());
        forceLoadedChunks(level, gasCent.getBlockPos(), pipePos.relative(testedPort.direction().getOpposite()));
        level.setBlock(pipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(pipePos) instanceof FluidPipeBlockEntity pipe)) {
            throw new AssertionError("No fluid_duct_neo block entity at " + pipePos + " for gas centrifuge");
        }
        pipe.setFluidType(HbmFluids.UF6);
        refreshFluidNodeAt(level, pipePos);
        GasCentBlockEntity.serverTick(level, gasCent.getBlockPos(), level.getBlockState(gasCent.getBlockPos()), gasCent);
        HbmFluidNodespace.tick(level);

        assertTrue(HbmFluidNodespace.getNode(level, gasCent.getBlockPos(), HbmFluids.UF6) == null,
                "gas centrifuge receives UF6 through remote ports without a core fluid node");
        HbmFluidUtil.PortSnapshot receiverPort = requireSubscribedFluidPort(level, gasCent.getBlockPos(), ports,
                HbmFluids.UF6);

        // TileEntityMachineGasCent#updateEntity called updateConnections every tick. A replacement duct has
        // the same port geometry and tank eligibility, so its receiver must return on the immediately next tick.
        level.removeBlock(pipePos, false);
        level.setBlock(pipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(pipePos) instanceof FluidPipeBlockEntity replacementPipe)) {
            throw new AssertionError("Gas centrifuge fixture did not recreate its remote UF6 duct");
        }
        replacementPipe.setFluidType(HbmFluids.UF6);
        refreshFluidNodeAt(level, pipePos);
        HbmFluidNodespace.tick(level);
        GasCentBlockEntity.serverTick(level, gasCent.getBlockPos(), level.getBlockState(gasCent.getBlockPos()), gasCent);
        assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, pipePos, HbmFluids.UF6),
                "gas centrifuge retries its UF6 receiver on the tick after a legacy remote duct is replaced");

        TestFluidProvider source = new TestFluidProvider(HbmFluids.UF6, 500);
        assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, receiverPort.connectorPos(),
                receiverPort.connectorSide(), HbmFluids.UF6, source),
                "test source subscribes to the gas centrifuge remote UF6 port");
        HbmFluidNet net = HbmFluidNodespace.getNode(level, receiverPort.connectorPos(), HbmFluids.UF6).getFluidNet();
        assertTrue(net.update() > 0L, "gas centrifuge remote fluid network transfers UF6 into its input tank");
        assertTrue(gasCent.getTank().getFill() > 0,
                "gas centrifuge receives UF6 through its source-backed remote port");
        assertTrue(source.getStoredFluid() < 500,
                "test source drains into the gas centrifuge remote fluid network");
    }

