    private static void assertLegacyHbmFluidRemoteInput(ServerLevel level, HbmFluidBlockEntity machine,
            HbmFluidTank tank, FluidType type, int expectedPortCount, String machineName, Runnable machineTick) {
        tank.setTankType(type);
        List<HbmFluidUtil.FluidPort> ports = legacyRemoteFluidPorts(machine);
        assertEquals(expectedPortCount, ports.size(), machineName + " exposes its complete legacy remote fluid port set");
        HbmFluidUtil.FluidPort port = ports.get(0);
        BlockPos pipePos = port.connectorPos(machine.getBlockPos());
        level.setBlock(pipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(pipePos) instanceof FluidPipeBlockEntity pipe)) {
            throw new AssertionError(machineName + " fixture did not create its remote input pipe");
        }
        pipe.setFluidType(type);
        refreshFluidNodeAt(level, pipePos);
        // Legacy UniNodespace updates at server START. The remote duct must join its
        // network before the machine's 20-tick connection pass can subscribe to it.
        HbmFluidNodespace.tick(level);
        machineTick.run();
        HbmFluidNodespace.tick(level);
        assertTrue(HbmFluidNodespace.getNode(level, machine.getBlockPos(), type) == null,
                machineName + " receives through remote ports without an ordinary core fluid node");
        assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, pipePos, type),
                machineName + " subscribes its input tank at a legacy remote port");
        TestFluidProvider source = new TestFluidProvider(type, 500, tank.getPressure());
        assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, pipePos, port.connectorSide(), type, source),
                "test source subscribes to the " + machineName + " input port");
        assertTrue(HbmFluidNodespace.getNode(level, pipePos, type).getFluidNet().update() > 0L,
                machineName + " remote input network transfers into its source-backed tank");
        assertTrue(tank.getFill() > 0, machineName + " receives fluid through its legacy remote port");

        // TileEntityMachineBlastFurnace and TileEntityMachineRadiolysis retried
        // these direct Fluid Mk2 receivers every legacy server tick.  Verify the
        // actual production ticker, not a direct utility call, restores a duct
        // replaced at the same remote endpoint.
        level.removeBlock(pipePos, false);
        level.setBlock(pipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(pipePos) instanceof FluidPipeBlockEntity replacementPipe)) {
            throw new AssertionError(machineName + " fixture did not recreate its remote input pipe");
        }
        replacementPipe.setFluidType(type);
        refreshFluidNodeAt(level, pipePos);
        HbmFluidNodespace.tick(level);
        machineTick.run();
        assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, pipePos, type),
                machineName + " restores its replaced remote input on the next legacy tick");
        TestFluidProvider replacementSource = new TestFluidProvider(type, 500, tank.getPressure());
        assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, pipePos, port.connectorSide(), type, replacementSource),
                "test source subscribes to the replaced " + machineName + " input port");
        assertTrue(HbmFluidNodespace.getNode(level, pipePos, type).getFluidNet().update() > 0L,
                machineName + " replacement input network transfers on the next legacy tick");
    }

    private static void assertLegacyHbmFluidRemoteOutput(ServerLevel level, HbmFluidBlockEntity machine,
            HbmFluidTank tank, FluidType type, int expectedPortCount, String machineName, Runnable machineTick) {
        tank.setTankType(type);
        tank.setFill(500);
        List<HbmFluidUtil.FluidPort> ports = legacyRemoteFluidPorts(machine);
        assertEquals(expectedPortCount, ports.size(), machineName + " exposes its complete legacy remote fluid port set");
        HbmFluidUtil.FluidPort port = ports.get(0);
        BlockPos pipePos = port.connectorPos(machine.getBlockPos());
        level.setBlock(pipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(pipePos) instanceof FluidPipeBlockEntity pipe)) {
            throw new AssertionError(machineName + " fixture did not create its remote output pipe");
        }
        pipe.setFluidType(type);
        refreshFluidNodeAt(level, pipePos);
        // Match the old START nodespace update before the machine's provider scan.
        HbmFluidNodespace.tick(level);
        machineTick.run();
        HbmFluidNodespace.tick(level);
        assertTrue(HbmFluidNodespace.getNode(level, machine.getBlockPos(), type) == null,
                machineName + " provides through remote ports without an ordinary core fluid node");
        assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, pipePos, type),
                machineName + " provides its output tank at a legacy remote port");
        TestFluidReceiver sink = new TestFluidReceiver(type, 500);
        assertTrue(HbmFluidUtil.subscribeReceiverToNetwork(level, pipePos, port.connectorSide(), type, sink),
                "test sink subscribes to the " + machineName + " output port");
        assertTrue(HbmFluidNodespace.getNode(level, pipePos, type).getFluidNet().update() > 0L,
                machineName + " remote output network transfers from its source-backed tank");
        assertTrue(sink.getStoredFluid() > 0, machineName + " delivers fluid through its legacy remote port");

        // The legacy hosts served by this helper also retry non-empty providers
        // every tick, so a replacement duct must be recovered by their real
        // production ticker before the next Fluid Mk2 transfer.
        level.removeBlock(pipePos, false);
        level.setBlock(pipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(pipePos) instanceof FluidPipeBlockEntity replacementPipe)) {
            throw new AssertionError(machineName + " fixture did not recreate its remote output pipe");
        }
        replacementPipe.setFluidType(type);
        refreshFluidNodeAt(level, pipePos);
        HbmFluidNodespace.tick(level);
        tank.setFill(500);
        machineTick.run();
        assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, pipePos, type),
                machineName + " restores its replaced remote output on the next legacy tick");
        TestFluidReceiver replacementSink = new TestFluidReceiver(type, 500);
        assertTrue(HbmFluidUtil.subscribeReceiverToNetwork(level, pipePos, port.connectorSide(), type, replacementSink),
                "test sink subscribes to the replaced " + machineName + " output port");
        assertTrue(HbmFluidNodespace.getNode(level, pipePos, type).getFluidNet().update() > 0L,
                machineName + " replacement output network transfers on the next legacy tick");
        assertTrue(replacementSink.getStoredFluid() > 0,
                machineName + " delivers fluid through its restored remote output port");
    }

