    private static void assertStrandCasterRemoteFluidEndpoints(ServerLevel level, StrandCasterBlockEntity caster) {
        List<HbmFluidUtil.FluidPort> ports = legacyRemoteFluidPorts(caster);
        assertEquals(4, ports.size(), "strand caster exposes four shared legacy remote fluid ports");
        HbmFluidUtil.FluidPort waterPort = ports.get(0);
        HbmFluidUtil.FluidPort steamPort = ports.get(1);
        BlockPos waterPipePos = waterPort.connectorPos(caster.getBlockPos());
        BlockPos steamPipePos = steamPort.connectorPos(caster.getBlockPos());
        forceLoadedChunks(level, waterPipePos, steamPipePos);
        level.setBlock(waterPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        level.setBlock(steamPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(waterPipePos) instanceof FluidPipeBlockEntity waterPipe)
                || !(level.getBlockEntity(steamPipePos) instanceof FluidPipeBlockEntity steamPipe)) {
            throw new AssertionError("Strand-caster fixture did not create both source-backed remote fluid pipes");
        }
        waterPipe.setFluidType(HbmFluids.WATER);
        steamPipe.setFluidType(HbmFluids.SPENTSTEAM);
        refreshFluidNodeAt(level, waterPipePos);
        refreshFluidNodeAt(level, steamPipePos);
        caster.getSteamTank().setFill(500);
        StrandCasterBlockEntity.serverTick(level, caster.getBlockPos(),
                level.getBlockState(caster.getBlockPos()), caster);
        HbmFluidNodespace.tick(level);

        assertTrue(HbmFluidNodespace.getNode(level, caster.getBlockPos(), HbmFluids.WATER) == null,
                "strand caster receives water through remote ports without a core fluid node");
        assertTrue(HbmFluidNodespace.getNode(level, caster.getBlockPos(), HbmFluids.SPENTSTEAM) == null,
                "strand caster provides spent steam through remote ports without a core fluid node");
        assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, waterPipePos, HbmFluids.WATER),
                "strand caster subscribes water at every source-backed remote endpoint");
        assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, steamPipePos, HbmFluids.SPENTSTEAM),
                "strand caster provides spent steam at every source-backed remote endpoint");

        TestFluidProvider waterSource = new TestFluidProvider(HbmFluids.WATER, 500);
        TestFluidReceiver steamSink = new TestFluidReceiver(HbmFluids.SPENTSTEAM, 500);
        assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, waterPipePos, waterPort.connectorSide(),
                HbmFluids.WATER, waterSource), "test source subscribes to a shared strand-caster water port");
        assertTrue(HbmFluidUtil.subscribeReceiverToNetwork(level, steamPipePos, steamPort.connectorSide(),
                HbmFluids.SPENTSTEAM, steamSink), "test sink subscribes to a shared strand-caster steam port");
        assertTrue(HbmFluidNodespace.getNode(level, waterPipePos, HbmFluids.WATER).getFluidNet().update() > 0L,
                "strand caster water-port network transfers water into its input tank");
        assertTrue(HbmFluidNodespace.getNode(level, steamPipePos, HbmFluids.SPENTSTEAM).getFluidNet().update() > 0L,
                "strand caster steam-port network transfers spent steam to its sink");
        assertTrue(caster.getWaterTank().getFill() > 0,
                "strand caster receives water through a shared source-backed remote port");
        assertTrue(steamSink.getStoredFluid() > 0,
                "strand caster delivers spent steam through a shared source-backed remote port");

        // TileEntityMachineStrandCaster#updateConnections retries both direct
        // endpoints every server tick. A same-type duct replacement must not
        // make the modern direct-port path fall back to a generic keepalive.
        int waterBeforeReplacement = caster.getWaterTank().getFill();
        level.removeBlock(waterPipePos, false);
        HbmFluidNodespace.tick(level);
        level.setBlock(waterPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(waterPipePos) instanceof FluidPipeBlockEntity replacementWaterPipe)) {
            throw new AssertionError("strand caster cadence fixture did not replace its remote water duct");
        }
        replacementWaterPipe.setFluidType(HbmFluids.WATER);
        refreshFluidNodeAt(level, waterPipePos);
        HbmFluidNodespace.tick(level);
        StrandCasterBlockEntity.serverTick(level, caster.getBlockPos(), level.getBlockState(caster.getBlockPos()), caster);
        assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, waterPipePos, HbmFluids.WATER),
                "strand caster retries its replaced remote water receiver on the next legacy server tick");
        TestFluidProvider replacementWaterSource = new TestFluidProvider(HbmFluids.WATER, 500);
        assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, waterPipePos, waterPort.connectorSide(),
                HbmFluids.WATER, replacementWaterSource),
                "test source subscribes after the strand-caster water duct replacement");
        assertTrue(HbmFluidNodespace.getNode(level, waterPipePos, HbmFluids.WATER).getFluidNet().update() > 0L,
                "strand caster replacement water network transfers on the next legacy server tick");
        assertTrue(caster.getWaterTank().getFill() > waterBeforeReplacement,
                "strand caster receives water after its remote duct replacement");

        level.removeBlock(steamPipePos, false);
        HbmFluidNodespace.tick(level);
        level.setBlock(steamPipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(steamPipePos) instanceof FluidPipeBlockEntity replacementSteamPipe)) {
            throw new AssertionError("strand caster cadence fixture did not replace its remote steam duct");
        }
        replacementSteamPipe.setFluidType(HbmFluids.SPENTSTEAM);
        refreshFluidNodeAt(level, steamPipePos);
        HbmFluidNodespace.tick(level);
        caster.getSteamTank().setFill(500);
        StrandCasterBlockEntity.serverTick(level, caster.getBlockPos(), level.getBlockState(caster.getBlockPos()), caster);
        assertEquals(1, HbmFluidNodespace.getNetworkProviderCount(level, steamPipePos, HbmFluids.SPENTSTEAM),
                "strand caster retries its replaced remote spent-steam provider on the next legacy server tick");
        TestFluidReceiver replacementSteamSink = new TestFluidReceiver(HbmFluids.SPENTSTEAM, 500);
        assertTrue(HbmFluidUtil.subscribeReceiverToNetwork(level, steamPipePos, steamPort.connectorSide(),
                HbmFluids.SPENTSTEAM, replacementSteamSink),
                "test sink subscribes after the strand-caster steam duct replacement");
        assertTrue(HbmFluidNodespace.getNode(level, steamPipePos, HbmFluids.SPENTSTEAM).getFluidNet().update() > 0L,
                "strand caster replacement steam network transfers on the next legacy server tick");
        assertTrue(replacementSteamSink.getStoredFluid() > 0,
                "strand caster sends spent steam after its remote duct replacement");
    }

