    private static void assertLegacyRemoteFluidInput(ServerLevel level, HbmFluidNetworkBlockEntity machine,
            HbmFluidTank tank, FluidType type, int expectedPortCount, String machineName, Runnable machineTick) {
        tank.setTankType(type);
        List<HbmFluidUtil.FluidPort> ports = legacyRemoteFluidPorts(machine, type);
        assertEquals(expectedPortCount, ports.size(), machineName + " exposes its complete legacy remote fluid port set");
        HbmFluidUtil.FluidPort port = ports.get(0);
        BlockPos pipePos = port.connectorPos(machine.getBlockPos());
        level.setBlock(pipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(pipePos) instanceof FluidPipeBlockEntity pipe)) {
            throw new AssertionError(machineName + " fixture did not create its remote input pipe");
        }
        pipe.setFluidType(type);
        refreshFluidNodeAt(level, pipePos);
        // UniNodespace updates during the server START phase, before the
        // legacy machine's twenty-tick trySubscribe pass.  A newly placed
        // remote duct therefore needs its nodespace pass before this fixture
        // invokes the machine ticker at the already-selected world-time
        // boundary.
        HbmFluidNodespace.tick(level);
        machineTick.run();
        assertTrue(HbmFluidNodespace.getNode(level, machine.getBlockPos(), type) == null,
                machineName + " retains its dedicated UNINOS node without an ordinary " + type.getName()
                        + " core fluid node");
        assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, pipePos, type),
                machineName + " subscribes its input tank at a legacy remote port");
        TestFluidProvider source = new TestFluidProvider(type, 500, tank.getPressure());
        assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, pipePos, port.connectorSide(), type, source),
                "test source subscribes to the " + machineName + " input port");
        HbmFluidNet inputNet = HbmFluidNodespace.getNode(level, pipePos, type).getFluidNet();
        long transferred = inputNet.update();
        assertTrue(transferred > 0L, machineName + " remote input network transfers into its source-backed tank: "
                + describeFluidNet(inputNet));
        assertTrue(tank.getFill() > 0, machineName + " receives fluid through its legacy remote port");
    }

