    private static void assertLegacyAdjacentFluidReceiverRecoversOnNextTick(ServerLevel level,
            HbmFluidNetworkBlockEntity machine, HbmFluidTank tank, FluidType type, String machineName,
            Runnable machineTick) {
        List<HbmFluidUtil.FluidPort> ports = legacyRemoteFluidPorts(machine, type);
        HbmFluidUtil.FluidPort port = ports.get(0);
        BlockPos pipePos = port.connectorPos(machine.getBlockPos());
        level.removeBlock(pipePos, false);
        level.setBlock(pipePos, ModBlocks.FLUID_DUCT_NEO.get().defaultBlockState(), Block.UPDATE_ALL);
        if (!(level.getBlockEntity(pipePos) instanceof FluidPipeBlockEntity pipe)) {
            throw new AssertionError(machineName + " cadence fixture did not replace its remote input pipe");
        }
        pipe.setFluidType(type);
        refreshFluidNodeAt(level, pipePos);
        HbmFluidNodespace.tick(level);
        machineTick.run();
        assertEquals(1, HbmFluidNodespace.getNetworkReceiverCount(level, pipePos, type),
                machineName + " retries its replaced adjacent " + type.getName()
                        + " receiver on the next legacy server tick");
        assertTrue(HbmFluidNodespace.getNode(level, machine.getBlockPos(), type) == null,
                machineName + " keeps its replaced adjacent input remote without an ordinary core fluid node");
        assertTrue(tank.getTankType() == type,
                machineName + " preserves its source-backed input tank type while retrying the adjacent receiver");
        int fillBefore = tank.getFill();
        TestFluidProvider source = new TestFluidProvider(type, 500, tank.getPressure());
        assertTrue(HbmFluidUtil.subscribeProviderToNetwork(level, pipePos, port.connectorSide(), type, source),
                "test source subscribes to the replaced " + machineName + " input port");
        HbmFluidNet inputNet = HbmFluidNodespace.getNode(level, pipePos, type).getFluidNet();
        assertTrue(inputNet.update() > 0L,
                machineName + " transfers through its next-tick restored " + type.getName() + " receiver: "
                        + describeFluidNet(inputNet));
        assertTrue(tank.getFill() > fillBefore,
                machineName + " receives fluid through its next-tick restored " + type.getName() + " receiver");
    }

