    private static void setTubeInsertion(PneumaticTubeBlockEntity tube, Direction direction, String label) {
        for (int i = 0; i < Direction.values().length + 1; i++) {
            if (tube.getInsertionDirection() == direction) {
                return;
            }
            tube.cycleInsertionDirection();
        }
        throw new AssertionError(label + ": expected " + direction + " but got " + tube.getInsertionDirection());
    }

    private static void setTubeEjection(PneumaticTubeBlockEntity tube, Direction direction, String label) {
        for (int i = 0; i < Direction.values().length + 1; i++) {
            if (tube.getEjectionDirection() == direction) {
                return;
            }
            tube.cycleEjectionDirection();
        }
        throw new AssertionError(label + ": expected " + direction + " but got " + tube.getEjectionDirection());
    }

    private static boolean sendPneumaticOnce(ServerLevel level, PneumaticTubeBlockEntity tube) {
        tube.refreshPneumaticNode();
        PneumaticNetwork network = tube.getPneumaticNet();
        // Preserve normal server-tick transfers, but let a just-created fixture
        // cross its first legacy START boundary before it is used.
        if (network == null) {
            PneumaticNodespace.tick(level);
            network = tube.getPneumaticNet();
        }
        if (network == null) {
            throw new AssertionError("Pneumatic tube has no network at " + tube.getBlockPos());
        }
        PneumaticReceiver receiver = PneumaticUtil.receiver(level, tube.getBlockPos(), tube.getEjectionDirection(), tube)
                .orElseThrow(() -> new AssertionError("Pneumatic tube has no receiver at " + tube.getBlockPos()));
        PneumaticItemAccess source = PneumaticUtil.sourceAccess(level, tube.getBlockPos(), tube.getInsertionDirection())
                .orElseThrow(() -> new AssertionError("Pneumatic tube has no source at " + tube.getBlockPos()));
        network.addReceiver(receiver);
        return network.send(source, tube, tube.getSendOrder(), tube.getReceiveOrder(),
                PneumaticUtil.rangeForPressure(1), 0);
    }

    private static void assertPneumaticServerTickProgress(ServerLevel level, PneumaticTubeBlockEntity sourceTube,
            PneumaticTubeBlockEntity endpointTube, ChestBlockEntity sourceChest, AtomicBoolean receiverRegistered,
            String label) {
        if (sourceChest.getItem(0).isEmpty()) {
            return;
        }
        PneumaticNetwork sourceNetwork = sourceTube.getPneumaticNet();
        PneumaticNetwork endpointNetwork = endpointTube.getPneumaticNet();
        assertTrue(sourceNetwork != null && sourceNetwork.isValid(), label + ": source has a valid network");
        assertTrue(endpointNetwork != null && endpointNetwork.isValid(), label + ": endpoint has a valid network");
        assertSame(sourceNetwork, endpointNetwork, label + ": endpoints share the joined network");
        assertTrue(endpointTube.isEndpoint(), label + ": endpoint retained its configured ejection direction");
        assertTrue(sourceTube.saveWithoutMetadata().getInt("sendCounter") > 0,
                label + ": source ticker reached a legacy five-tick sender pass");
        recordPneumaticReceiverRegistration(endpointTube, receiverRegistered);
        assertTrue(receiverRegistered.get(),
                label + ": endpoint registered a receiver during the legacy ten-tick ticker phase");
    }

    private static boolean pneumaticTubeLegacyCompressorSendTick(long gameTime, BlockPos pos) {
        try {
            Method method = PneumaticTubeBlockEntity.class.getDeclaredMethod("isLegacyCompressorSendTick",
                    long.class, BlockPos.class);
            method.setAccessible(true);
            return (boolean) method.invoke(null, gameTime, pos);
        } catch (ReflectiveOperationException exception) {
            throw new AssertionError("Could not inspect PneumaticTubeBlockEntity legacy compressor timing", exception);
        }
    }

    private static void recordPneumaticReceiverRegistration(PneumaticTubeBlockEntity endpointTube,
            AtomicBoolean receiverRegistered) {
        PneumaticNetwork endpointNetwork = endpointTube.getPneumaticNet();
        if (endpointNetwork != null && !endpointNetwork.receivers.isEmpty()) {
            receiverRegistered.set(true);
        }
    }

