    private static void forceSubscriptionLastSeen(HbmPowerNet net, long lastSeen) {
        forceMapValues(net, "providerEntries", lastSeen);
        forceMapValues(net, "receiverEntries", lastSeen);
    }

    @SuppressWarnings("unchecked")
    private static void forceFluidSubscriptionLastSeen(HbmFluidNet net, long lastSeen) {
        forceFluidSubscriptionLastSeen(net, "providerEntries", lastSeen);
    }

    @SuppressWarnings("unchecked")
    private static void forceFluidSubscriptionLastSeen(HbmFluidNet net, String fieldName, long lastSeen) {
        try {
            Field field = findInheritedField(HbmFluidNet.class, fieldName);
            field.setAccessible(true);
            Map<Object, Long> entries = (Map<Object, Long>) field.get(net);
            entries.replaceAll((subscriber, ignored) -> lastSeen);
        } catch (ReflectiveOperationException exception) {
            throw new AssertionError("Unable to force HbmFluidNet " + fieldName + " timestamps", exception);
        }
    }

    @SuppressWarnings("unchecked")
    private static int getFluidSubscriptionEntryCount(HbmFluidNet net, String fieldName) {
        try {
            Field field = findInheritedField(HbmFluidNet.class, fieldName);
            field.setAccessible(true);
            return ((Map<Object, Long>) field.get(net)).size();
        } catch (ReflectiveOperationException exception) {
            throw new AssertionError("Unable to inspect HbmFluidNet " + fieldName, exception);
        }
    }

    @SuppressWarnings("unchecked")
    private static void forceMapValues(HbmPowerNet net, String fieldName, long value) {
        try {
            Field field = findInheritedField(HbmPowerNet.class, fieldName);
            field.setAccessible(true);
            Map<Object, Long> entries = (Map<Object, Long>) field.get(net);
            for (Object key : entries.keySet()) {
                entries.put(key, value);
            }
        } catch (ReflectiveOperationException exception) {
            throw new AssertionError("Unable to force HbmPowerNet " + fieldName + " timestamps", exception);
        }
    }

