    private static Field findInheritedField(Class<?> type, String fieldName) throws NoSuchFieldException {
        for (Class<?> current = type; current != null; current = current.getSuperclass()) {
            try {
                return current.getDeclaredField(fieldName);
            } catch (NoSuchFieldException ignored) {
                // NodeNet owns the source-shaped public maps; specialised
                // Power/Fluid nets intentionally inherit rather than hide it.
            }
        }
        throw new NoSuchFieldException(fieldName);
    }

    private static void prepareSolidTestMissileLaunch(ServerLevel level, LaunchPadBlockEntity launchPad) {
        // TileEntityLaunchPad keeps a source-backed 100-tick loading timer:
        // an unloaded pad resets to 100, then a valid solid missile counts it
        // down to immediate-ready. Do not bypass that state with test-only NBT.
        launchPad.setPower(100_000L);
        launchPad.getItems().setStackInSlot(LaunchPadBlockEntity.SLOT_MISSILE,
                new ItemStack(ModItems.MISSILE_TEST.get()));
        for (int tick = 0; tick < 100; tick++) {
            tickLaunchPad(level, launchPad);
        }
    }

    private static void tickLaunchPad(ServerLevel level, LaunchPadBlockEntity launchPad) {
        LaunchPadBlockEntity.serverTick(level, launchPad.getBlockPos(),
                level.getBlockState(launchPad.getBlockPos()), launchPad);
    }

    private static ItemStack completeSize10SolidCustomMissile() {
        return CustomMissileItem.buildMissile(customMissilePart("mp_c_5"),
                customMissilePart("mp_warhead_10_he"), customMissilePart("mp_fuselage_10_solid"), null,
                customMissilePart("mp_thruster_10_solid"));
    }

    private static void prepareSolidCustomMissileLaunch(ServerLevel level, CustomMissileLauncherBlockEntity launcher) {
        launcher.setPower(100_000L);
        launcher.getItems().setStackInSlot(CustomMissileLauncherBlockEntity.SLOT_MISSILE,
                completeSize10SolidCustomMissile());
        Item rocketFuel = ForgeRegistries.ITEMS.getValue(new ResourceLocation(HbmNtm.MOD_ID, "rocket_fuel"));
        if (rocketFuel == null) {
            throw new AssertionError("Missing registered rocket_fuel required by custom missile launcher fixture");
        }
        launcher.getItems().setStackInSlot(CustomMissileLauncherBlockEntity.SLOT_SOLID_FUEL,
                new ItemStack(rocketFuel, 10));
        for (int tick = 0; tick < 10; tick++) {
            CustomMissileLauncherBlockEntity.serverTick(level, launcher.getBlockPos(),
                    level.getBlockState(launcher.getBlockPos()), launcher);
        }
        // A continuously powered legacy launcher launches as soon as this loop
        // reaches its required solid-fuel threshold, then subtracts that fuel.
        // Callers that keep redstone off retain the loaded reserve for their
        // readiness assertions; callers with an existing signal verify the
        // resulting missile instead of incorrectly requiring unspent fuel.
    }

