    private static MissileEntity singleMissileAt(ServerLevel level, BlockPos launchPos) {
        List<MissileEntity> missiles = missilesAt(level, launchPos);
        if (missiles.size() != 1) {
            throw new AssertionError("Expected exactly one missile at " + launchPos + " but found " + missiles.size()
                    + "; global missile entities=" + globalMissileDiagnostics(level));
        }
        return missiles.get(0);
    }

    private static String globalMissileDiagnostics(ServerLevel level) {
        int total = 0;
        List<String> positions = new ArrayList<>();
        for (var entity : level.getAllEntities()) {
            if (entity instanceof MissileEntity missile) {
                total++;
                if (positions.size() < 8) {
                    positions.add(missile.getUUID() + "@(" + missile.getX() + "," + missile.getY() + ","
                            + missile.getZ() + ") removed=" + missile.isRemoved());
                }
            }
        }
        return "count=" + total + ", first=" + positions;
    }

    private static List<MissileEntity> missilesAt(ServerLevel level, BlockPos launchPos) {
        // GameTest can advance a freshly spawned missile by several real server
        // ticks before the next assertion, especially while another fixture is
        // loading chunks. Its current position is therefore not a stable launch
        // identity. EntityMissileBaseNT persists the integral launch X/Z endpoints
        // (sX/sZ), so use that source-backed identity instead of a small current-
        // position AABB. This still distinguishes nearby simultaneous launch pads
        // without masking an absent or wrongly configured missile.
        List<MissileEntity> missiles = new ArrayList<>();
        for (Entity entity : level.getAllEntities()) {
            if (entity instanceof MissileEntity missile) {
                CompoundTag tag = missile.saveWithoutId(new CompoundTag());
                if (tag.getInt("sX") == launchPos.getX() && tag.getInt("sZ") == launchPos.getZ()) {
                    missiles.add(missile);
                }
            }
        }
        return missiles;
    }

