    /**
     * GameTest batches share a server level but run fixtures interleaved. Forge's
     * {@code getMinecraft} factory profile is a singleton for that level, so its
     * position, facing and held stack leak between otherwise unrelated tests.
     */
    private static net.minecraftforge.common.util.FakePlayer gameTestPlayer(ServerLevel level) {
        String caller = StackWalker.getInstance(StackWalker.Option.RETAIN_CLASS_REFERENCE).walk(frames -> frames
                .filter(frame -> frame.getDeclaringClass() == EnergyMk2GameTests.class)
                .map(StackWalker.StackFrame::getMethodName)
                .filter(method -> !method.equals("gameTestPlayer"))
                .findFirst()
                .orElse("unknown"));
        java.util.UUID playerId = java.util.UUID.nameUUIDFromBytes(("hbm_ntm_rebirth_gametest:" + caller)
                .getBytes(java.nio.charset.StandardCharsets.UTF_8));
        // FakePlayerFactory implementations may key their world cache by player
        // name rather than UUID, so both identity fields must be test-specific.
        var profile = new com.mojang.authlib.GameProfile(playerId,
                "hbm_gt_" + playerId.toString().substring(0, 8));
        return FakePlayerFactory.get(level, profile);
    }

