    /** Runs a fixture on the same 20-tick boundary used by legacy fixed-machine connection passes. */
    private static void runOnLegacyTwentyTick(GameTestHelper helper, Runnable fixture) {
        ServerLevel level = helper.getLevel();
        int ticksUntilBoundary = Math.floorMod(20 - (int) (level.getGameTime() % 20L), 20);
        if (ticksUntilBoundary == 0) {
            ticksUntilBoundary = 20;
        }
        helper.startSequence()
                .thenIdle(ticksUntilBoundary)
                .thenExecute(() -> {
                    assertEquals(0L, level.getGameTime() % 20L,
                            "fixed-machine fixture reaches the legacy 20-tick connection boundary");
                    fixture.run();
                })
                .thenSucceed();
    }

    /** Places a fixture before, then verifies it after, the next natural legacy 20-tick connection pass. */
    private static void runAfterNextLegacyTwentyTick(GameTestHelper helper, Runnable setup, Runnable verification) {
        ServerLevel level = helper.getLevel();
        int ticksUntilBoundary = Math.floorMod(20 - (int) (level.getGameTime() % 20L), 20);
        if (ticksUntilBoundary == 0) {
            ticksUntilBoundary = 20;
        }
        helper.startSequence()
                .thenExecute(setup)
                .thenIdle(ticksUntilBoundary)
                .thenExecute(() -> {
                    assertEquals(0L, level.getGameTime() % 20L,
                            "placed fixed-machine fixture reaches its next legacy 20-tick connection boundary");
                    verification.run();
                })
                .thenSucceed();
    }

    /** Runs a fixture off the 20-tick cadence so per-tick legacy subscriptions cannot be masked. */
    private static void runOutsideLegacyTwentyTick(GameTestHelper helper, Runnable fixture) {
        ServerLevel level = helper.getLevel();
        int ticksUntilOutsideBoundary = level.getGameTime() % 20L == 0L ? 1 : 0;
        helper.startSequence()
                .thenIdle(ticksUntilOutsideBoundary)
                .thenExecute(() -> {
                    assertTrue(level.getGameTime() % 20L != 0L,
                            "per-tick fluid fixture runs outside the legacy 20-tick boundary");
                    fixture.run();
                })
                .thenSucceed();
    }

