    private static final class TestFluidProvider implements HbmStandardFluidSender {
        private final HbmFluidTank tank;

        private TestFluidProvider(FluidType type, int fill) {
            this(type, fill, 0);
        }

        private TestFluidProvider(FluidType type, int fill, int pressure) {
            this.tank = new HbmFluidTank(type, Math.max(fill, 1));
            this.tank.withPressure(pressure);
            this.tank.setFill(fill);
        }

        private int getStoredFluid() {
            return tank.getFill();
        }

        @Override
        public List<HbmFluidTank> getSendingTanks() {
            return List.of(tank);
        }

        @Override
        public List<HbmFluidTank> getAllTanks() {
            return List.of(tank);
        }
    }

    private static final class TestFluidReceiver implements HbmFluidReceiver {
        private final HbmFluidTank tank;

        private TestFluidReceiver(FluidType type, int capacity) {
            this(type, capacity, 0);
        }

        private TestFluidReceiver(FluidType type, int capacity, int pressure) {
            this.tank = new HbmFluidTank(type, Math.max(capacity, 1));
            this.tank.withPressure(pressure);
        }

        private int getStoredFluid() {
            return tank.getFill();
        }

        @Override
        public long transferFluid(FluidType type, int pressure, long amount) {
            if (type != tank.getTankType() || amount <= 0L || !tank.canAccept(type, pressure)) {
                return amount;
            }
            int accepted = tank.fill(type, (int) Math.min(Integer.MAX_VALUE, amount), pressure, false);
            return amount - accepted;
        }

        @Override
        public long getDemand(FluidType type, int pressure) {
            return type == tank.getTankType() && tank.canAccept(type, pressure) ? tank.getSpace() : 0L;
        }

        @Override
        public int[] getReceivingPressureRange(FluidType type) {
            return new int[] {tank.getPressure(), tank.getPressure()};
        }

        @Override
        public List<HbmFluidTank> getAllTanks() {
            return List.of(tank);
        }
    }

